window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II e frasi con wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Se fossi in te, …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"La realtà di Eva – i desideri di Eva. Completa con: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Però le piacerebbe essere più alta.","why":"*grösser sein*: la forma del desiderio di *sein* è **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Però le piacerebbe parlare bene lo spagnolo.","why":"Alla fine c'è un infinito (*sprechen*), quindi il desiderio è **würde** + infinito.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Però preferirebbe lavorare come guida turistica.","why":"Infinito alla fine (*arbeiten*) → **würde** + infinito. *lieber* = piuttosto, preferibilmente.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Però le piacerebbe avere un appartamento grande.","why":"*eine Wohnung haben*: la forma del desiderio di *haben* è **hätte**. Non serve un infinito.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"Che cosa pensano le persone?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Abbina ogni immagine a un'espressione del riquadro.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Se non dovessi lavorare, adesso sarei seduto in giardino.","why":"L'immagine 1 lo mostra mentre lavora, poi mentre sogna su una sdraio. Dopo una frase con *wenn* la principale comincia con il verbo (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Se avessi una macchina, non dovrei andare in bici sotto la pioggia.","why":"Va in bici sotto la pioggia; una macchina gli risparmierebbe questo. *müsste* è il Konjunktiv II di *müssen*. *Velo* è la parola svizzera per *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Se il bus non fosse in ritardo, sarei puntuale in ufficio.","why":"Un bus in ritardo la fa arrivare tardi al lavoro. *wäre* è il Konjunktiv II di *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Riscrivi le frasi di a: comincia con la principale, poi la frase con wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"Non dovrei andare in bici sotto la pioggia, se avessi una macchina.","why":"Prima la principale, poi la frase con *wenn*. Nella frase con *wenn* il verbo (*hätte*) va alla fine.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Sarei puntuale in ufficio, se il bus non fosse in ritardo.","why":"Stesso schema: principale, virgola, *wenn* … verbo alla fine (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Completa con le parole del riquadro. Ogni parola si usa una volta; quelle barrate sono usate nell'esempio.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Farei alcune cose in modo diverso, se fossi a capo della nostra ditta.","why":"*machen* alla fine → **würde** + infinito. *Chefin sein* → **wäre**, alla fine della frase con *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Se fossi Marco, farei assolutamente una formazione professionale.","why":"*Marco sein* → **wäre** (come *Wenn ich du wäre …*). La principale ha l'infinito *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Se potessi decidere liberamente, lavorerei in una piccola ditta.","why":"*frei entscheiden können* → **könnte** alla fine della frase con *wenn*. Principale con *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Se avessimo dei figli, dovrei lavorare solo a metà tempo.","why":"*Kinder haben* con *wir* → **hätten**. Il riquadro lascia **müsste** per l'ultimo spazio.","source":"k2","check":"*müsste* e *würde* sono entrambi tedesco corretto in b, c ed e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* va altrettanto bene). Il riquadro dice solo che tre spazi prendono *würde* e uno prende *müsste*; questa soluzione è la ripartizione più probabile. Chiedi al tuo insegnante quale vuole il libro."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Devo sbrigarmi a causa del mio lavoro.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Riscrivi le risposte con weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Perché la mia ragazza non è puntuale.","why":"*wegen* + sostantivo diventa *weil* + una frase con un verbo; il verbo (*ist*) va alla fine.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Perché il tempo è brutto.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; dopo *weil* il verbo va alla fine.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Perché ho un appuntamento importante.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (accusativo dopo *haben*); verbo alla fine.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Completa con: wegen – weshalb – weil – deswegen – denn. Una parola può essere usata più volte.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"A causa della sua pronuncia lo capisco solo male.","why":"Segue un sostantivo (*seiner Aussprache*, genitivo), non una frase → la preposizione **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Un giorno vorrei viaggiare in Italia, perché vorrei vedere il mare.","why":"Dopo lo spazio il verbo resta in 2a posizione (*ich möchte*) → **denn**. Con *weil* andrebbe alla fine.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Devo migliorare la comprensione orale, per questo guardo molti film.","why":"La seconda parte è la conseguenza, e il verbo viene subito dopo lo spazio (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"I miei figli hanno imparato il tedesco in fretta, perché all'asilo stanno sempre con bambini svizzeri.","why":"Il verbo è alla fine (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Perché scrivi le parole su dei bigliettini?","why":"Serve una parola interrogativa: **Weshalb** significa *warum* (perché)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Mia sorella parla già il tedesco quasi correntemente, per questo può aiutarmi a impararlo.","why":"Conseguenza, e il verbo viene subito dopo lo spazio (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"Al corso di lingua. Completa con: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"Non sono riuscito a fare l'ultimo esercizio, perché non l'avevo capito.","why":"Il verbo è alla fine (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"All'iscrizione non c'era nessuno. Per questo sono tornato a casa.","why":"Una nuova frase che dà la conseguenza, con il verbo subito dopo lo spazio (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Grazie ai miei bei voti non ho dovuto fare un test all'inizio del corso.","why":"Segue un gruppo nominale (*meiner guten Noten*, genitivo plurale) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"C'è un corso di lingua in più, perché si sono iscritti moltissimi partecipanti.","why":"Il verbo è alla fine (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Ieri purtroppo non sono potuto venire al corso a causa del mal di denti.","why":"Segue un gruppo nominale (*meiner Zahnschmerzen*, genitivo plurale) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Chi trova le scuse migliori? Scegli una situazione e scrivi. Le risposte modello sono solo una possibilità ciascuna.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Purtroppo non ho potuto riordinare la cucina, perché all'improvviso ho avuto un forte mal di schiena. Ho dovuto sdraiarmi. Per questo ho guardato un film.","why":"Usa *weil* (verbo alla fine: *hatte*) e *Deswegen* (verbo subito dopo: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"A causa dell'influenza non sono andato all'esame finale. Avevo la febbre alta, per questo sono rimasto a letto.","why":"Usa *wegen* + genitivo (*einer Grippe*) e *deswegen* + verbo (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"Mi dispiace tanto! Purtroppo sono arrivato tardi, perché in autostrada c'era stato un incidente. A causa della coda ho perso due ore.","why":"*denn* lascia il verbo in 2a posizione (*war*). *wegen des Staus*: genitivo di *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (frasi ipotetiche, comprese quelle irreali con il Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"dizionario dei connettivi di grammis: wenn (subordinante, verbo alla fine)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"dizionario dei connettivi di grammis: weil (subordinante, verbo alla fine)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"dizionario dei connettivi di grammis: denn (causale, il verbo resta in 2a posizione)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"dizionario dei connettivi di grammis: deswegen (conseguenza; sta prima del verbo o in mezzo alla frase)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen con il genitivo)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Crescere con più lingue · lettura, post nel forum, cruciverba, parole preferite","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"A casa in più lingue","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Due o tre lingue in una famiglia – nessun problema?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"Chi dice cosa? Leggi i tre testi e scrivi il nome della persona che dice ciascuna frase.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"“I bambini vogliono parlare la stessa lingua dei loro amici.” – Janusz","why":"Janusz (testo B): *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"“È bello parlare molto bene più lingue, no?” – Yara","why":"Yara (testo C): *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"“I miei figli passano da una lingua all'altra.” – Amira","why":"Amira (testo A): *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* È l'unica che parla dei propri figli."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Che cosa è giusto? Rileggi i testi. Scrivi *richtig* (giusto) o *falsch* (sbagliato) dopo ogni frase; nel libro segni solo quelle giuste.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"I figli di Amira parlano l'arabo meglio del tedesco. → giusto","why":"In famiglia si parla sempre arabo: *Darum können das die Kinder viel besser.* (Il loro tedesco qui è lo svizzero tedesco.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"Nella famiglia di Amira si parla solo tedesco. → sbagliato","why":"Il contrario: *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz ha imparato il tedesco per sei anni. → sbagliato","why":"Aveva sei anni quando la famiglia si è trasferita (*als ich sechs Jahre alt war*) e dopo un anno parlava correntemente l'alto tedesco."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz e sua sorella non volevano parlare polacco con i genitori. → giusto","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara parla tre lingue correntemente. → giusto","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* Il tedesco è la sua quarta lingua e non lo parla ancora bene."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara presto imparerà anche il tedesco. → sbagliato","why":"Non comincia presto (*bald*): impara già il tedesco da due anni (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"A casa in più lingue","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Scrivere un post nel forum. Hai guardato un dibattito in TV sul crescere con più lingue. Nel forum online della trasmissione trovi questa opinione:","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Prendi appunti sulle quattro domande. Bastano appunti brevi, niente frasi complete. Gli appunti del modello sono una possibilità.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Sì: il figlio della mia vicina – italiano con la madre, svizzero tedesco a scuola","why":"Solo appunti: un nome o una persona e quali lingue dove."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"imparare due lingue senza un corso, contatto con la famiglia all'estero, vantaggi nel lavoro","why":"Raccogli due o tre vantaggi; ti servono per *Ich finde es sehr gut, dass …* in b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mescolare le lingue, una lingua è più debole, molto lavoro per i genitori","why":"Questi vanno in *Es könnte schwierig sein, dass …* e *Auf der anderen Seite …* in b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"no – i bambini imparano bene due lingue se i genitori parlano molto con loro","why":"Decidi sì o no e dai un motivo: diventa *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Ora scrivi la tua opinione sul tema (circa 80 parole). Usa i tuoi appunti di a e alcune delle espressioni.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"Non sono d'accordo con Sandra, perché molti bambini imparano due lingue senza problemi. Il figlio della mia vicina cresce con l'italiano e il tedesco. Con sua madre parla italiano, a scuola svizzero tedesco. Trovo molto bello che impari due lingue così presto. Potrebbe essere difficile che a volte mescoli le lingue. D'altra parte, per i bambini piccoli è normale. La cosa più importante di tutte è che i genitori parlino molto con il bambino. Per questo ogni genitore dovrebbe parlare la propria lingua.","why":"Circa 85 parole, con sei delle espressioni. *denn* lascia il verbo al secondo posto (*lernen*); dopo *Deswegen* viene subito il verbo (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Risolvi il cruciverba. Ogni frase indica la prima lettera della parola mancante. La griglia non è mostrata qui: scrivi la parola intera. Nella griglia del libro la Ä occupa una sola casella.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Il nostro paese d'origine è la Spagna. Veniamo dalla Spagna.","why":"*aus einem Land stammen* = provenire da un paese (come *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda e Mike non si vedono per sei mesi. È una lunga separazione.","why":"*die Trennung* = separazione, il sostantivo di *sich trennen*. *eine lange* → un sostantivo femminile."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"Il tedesco e l'arabo non hanno la stessa scrittura.","why":"*die Schrift* = scrittura, le lettere con cui si scrive una lingua. L'arabo usa un altro alfabeto."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter ora vive in America. Da quando vive lì, è cambiato molto.","why":"*sich verändern* = cambiare (come persona). Perfekt: *hat sich verändert*. La Ä occupa una sola casella."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"Scrive libri. Di professione è un'autrice.","why":"*Sie* → la forma femminile con *-in*: *der Autor → die Autorin*. Nessun articolo dopo *sein … von Beruf*."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"I bambini non fanno i compiti. Per questo i genitori li sgridano.","why":"*mit jemandem schimpfen* = sgridare qualcuno. Soggetto plurale *die Eltern* → *schimpfen*. Dopo *Deshalb* viene subito il verbo."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"Lavora solo da pochi mesi. Ha ancora poca esperienza nel suo lavoro.","why":"*die Erfahrung* = esperienza. *wenig Erfahrung haben* = avere poca esperienza."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Ora abbiamo il caos. È tutto in disordine.","why":"*durcheinander sein* = essere in disordine, confuso. Si scrive in una parola."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"Per Ye-Jon i suoni P e F suonano uguali. Non riesce a distinguerli.","why":"*unterscheiden* = distinguere. Con *kann* l'infinito va in fondo. *tönen* è svizzero per *klingen* (suonare)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"In vacanza vado in Grecia, ma purtroppo non so parlare il greco.","why":"*Griechisch* = la lingua greca, con la maiuscola. *kein Griechisch können* = non saper parlare il greco."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"Mangia solo verdura e riso. Mangia esclusivamente verdura e riso.","why":"*ausschliesslich* = esclusivamente, nient'altro che. Grafia svizzera con *ss*; in Germania si scrive con la s scharf (Eszett)."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Parola risolutiva (la riga evidenziata nella griglia): lingua madre","why":"Ogni parola dà una lettera della riga evidenziata: stam**M**en, trenn**U**ng, schrif**T**, (T nella griglia), veränd**E**rt, auto**R**in, (S nella griglia), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"A casa in più lingue","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"La mia parola tedesca più bella","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Abbina ogni foto a una parola del riquadro. I pallini colorati del libro indicano l'articolo: blu = der, verde = das, rosso = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (un dolce al cucchiaio al caramello)","why":"Nome svizzero della crème caramel. *Chöpfli* in svizzero tedesco significa “testolina” (*Kopf*). Pallino verde → *das*."},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – stella cadente","why":"*der Stern* = stella; *die Sternschnuppe* = stella cadente. Pallino rosso → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – farfalla","why":"Parola svizzera per *der Schmetterling* (farfalla); il Duden la segna come *schweizerisch, sonst landschaftlich*. Pallino blu → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"Perché qualcuno potrebbe trovare proprio queste parole le più belle? Tu che cosa ne pensi? Prendi appunti, poi parlatene. Gli appunti del modello sono una possibilità.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"così colorata e leggera, ricorda l'estate, buffo: l'animale non è affatto un uccello","why":"Pensa a che cosa ti fa vedere o sentire la parola e a come suona."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"dolce, ricorda l'infanzia, suona buffa e tipicamente svizzera","why":"*tönen* = svizzero per *klingen* (suonare)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romantica, si può esprimere un desiderio, suona morbida","why":"Bastano appunti brevi: aggettivi e un motivo."}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"La mia parola preferita","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"Quale parola tedesca e quale parola della tua lingua madre ti piacciono? Perché? Scrivi un breve testo usando le espressioni. La risposta modello è una possibilità.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"La mia parola tedesca preferita è “gemütlich” (accogliente). Quando sento questa parola, penso a una sera d'inverno con tè, candele e amici. Per questo la trovo così bella. Suona morbida e calda. Nella mia lingua madre, l'Inglese, non c'è una parola con esattamente questo significato. In inglese mi piace la parola “sunshine”. Per me è una parola allegra, perché suona luminosa e amichevole.","why":"*Wenn …, dann* + verbo subito dopo (*denke ich*); *Deshalb* + verbo subito dopo (*finde ich*). Sostituisci con la tua lingua madre e le tue parole.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Presenta il tuo testo in classe. Nel modello trovi un possibile inizio.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Oggi vorrei presentarvi la mia parola preferita. È la parola “gemütlich”. …","why":"Comincia nominando la parola, poi leggi il tuo testo di a. *euch* per i compagni di classe, *Ihnen* se parli in modo formale."}]}]}],"sources":[{"id":"sommervogel","title":"Duden: Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"grammis, dizionario dei connettori: deswegen (conseguenza; sta prima del verbo o in mezzo)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"grammis, dizionario dei connettori: wenn (subordinante, verbo in fondo)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]},{"id":"03-nachfragen-test","no":3,"title":"Nachfragen · Fremdsprachen lernen · Test Lektion 4","title_en":"Chiedere spiegazioni con cortesia, imparare le lingue, cercare lavoro · Test della lezione 4","added":"2026-11-10","book":"Schritte plus Neu 5 · Arbeitsbuch und Testheft · Lektion 4","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (soluzioni ufficiali, Lektion 4)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (frasi ipotetiche, comprese quelle irreali con il Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"weil","title":"dizionario dei connettivi di grammis: weil (subordinante, verbo alla fine)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"dizionario dei connettivi di grammis: denn (causale, il verbo resta in 2a posizione)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"dizionario dei connettivi di grammis: deswegen (conseguenza; sta prima del verbo o in mezzo alla frase)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"deshalb","title":"dizionario dei connettivi di grammis: deshalb (conseguenza; sinonimi daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"darum","title":"dizionario dei connettivi di grammis: d(a)rum (conseguenza)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen con il genitivo)","url":"https://grammis.ids-mannheim.de/fragen/67"}],"pages":[{"page":"AB 133","heading":"C  Entschuldigung, könnten Sie das bitte wiederholen?","heading_en":"Scusi, potrebbe ripeterlo, per favore?","exercises":[{"no":"13","tag":"C2","instruction":"Ordnen Sie zu.","instruction_en":"Completa ogni domanda o frase con un inizio del riquadro. Ogni inizio si usa una volta; quello barrato è usato nell'esempio.","box":["Tut mir leid, das Wort habe ich","Könnten Sie bitte langsamer","Entschuldigung, habe ich das","Könnten Sie das bitte","Darf ich Sie schnell","Was bedeutet","Könnten Sie mir vielleicht sagen","Wissen Sie, ob"],"box_used":[4],"box_exact":true,"example":[{"label":"a","text":"**Darf ich Sie schnell** etwas fragen?"}],"items":[{"label":"b","text":"___ der Ausdruck «es eilig haben»?","gaps":[["Was bedeutet"]],"solution":"**Was bedeutet** der Ausdruck «es eilig haben»?","en":"Che cosa significa l'espressione “es eilig haben”?","why":"*Was bedeutet …?* chiede il significato di una parola o di un'espressione. (*es eilig haben* = avere fretta.)","source":"hueber"},{"label":"c","text":"___ sprechen?","gaps":[["Könnten Sie bitte langsamer"]],"solution":"**Könnten Sie bitte langsamer** sprechen?","en":"Potrebbe parlare più lentamente, per favore?","why":"*Könnten Sie …* (Konjunktiv II) rende la richiesta cortese; l'infinito *sprechen* va alla fine.","source":"hueber"},{"label":"d","text":"___ nicht verstanden.","gaps":[["Tut mir leid, das Wort habe ich"]],"solution":"**Tut mir leid, das Wort habe ich** nicht verstanden.","en":"Mi dispiace, quella parola non l'ho capita.","why":"Perfekt: *habe … verstanden*; *das Wort* sta al primo posto per dare enfasi, quindi il verbo *habe* viene subito dopo.","source":"hueber"},{"label":"e","text":"Wie bitte? ___ wiederholen?","gaps":[["Könnten Sie das bitte"]],"solution":"Wie bitte? **Könnten Sie das bitte** wiederholen?","en":"Come, scusi? Potrebbe ripeterlo, per favore?","why":"Una richiesta cortese con *Könnten Sie …*; *wiederholen* (ripetere) va alla fine.","source":"hueber"},{"label":"f","text":"___ es hier auch Integrationskurse gibt?","gaps":[["Wissen Sie, ob"]],"solution":"**Wissen Sie, ob** es hier auch Integrationskurse gibt?","en":"Sa se qui ci sono anche dei corsi d'integrazione?","why":"*ob* introduce una domanda indiretta sì/no, quindi il verbo *gibt* va alla fine.","source":"hueber"},{"label":"g","text":"___ richtig verstanden?","gaps":[["Entschuldigung, habe ich das"]],"solution":"**Entschuldigung, habe ich das** richtig verstanden?","en":"Scusi, ho capito bene?","why":"Una domanda sì/no al Perfekt: prima *habe*, *verstanden* alla fine.","source":"hueber"},{"label":"h","text":"___, wo die Mensa ist?","gaps":[["Könnten Sie mir vielleicht sagen"]],"solution":"**Könnten Sie mir vielleicht sagen**, wo die Mensa ist?","en":"Potrebbe dirmi per caso dov'è la mensa?","why":"Una domanda indiretta con *wo*: il verbo *ist* va alla fine. *die Mensa* = la mensa universitaria.","source":"hueber"}]},{"no":"14","tag":"C2","instruction":"Ergänzen Sie.","instruction_en":"Completa i dialoghi. Le iniziali stampate (e alcune lettere all'interno delle parole) sono date; scrivi le parole mancanti per intero.","example":[{"label":"a","lead":"◆ Was ist denn das? ○ Das ist ein Zigerkrapfen. ◆ Entschuldigung, Zigerkrapfen kenne ich nicht.","text":"**Könnten Sie mir sagen**, was das ist?"}],"items":[{"label":"b","lead":"◆ Entschuldigen Sie bitte. Wo ist denn da die Mensa?  ○ Wie bitte? Das letzte Wort h… i… n… v… .  ◆ Die Mensa, die Uni-Kantine.","text":"Wie bitte? Das letzte Wort ___.","gaps":[["habe ich nicht verstanden"]],"solution":"Wie bitte? Das letzte Wort **habe ich nicht verstanden**.","en":"Come, scusi? L'ultima parola non l'ho capita.","why":"Perfekt: *habe* in 2a posizione dopo *Das letzte Wort*, *verstanden* alla fine.","source":"hueber"},{"label":"c","lead":"◆ Also, dann treffen wir uns am 12.5. um 13.35 Uhr am Bahnhof.  ○ Entschuldigen Sie, es ist so laut da. K… S… den Termin b… w…?","text":"Entschuldigen Sie, es ist so laut da. ___ den Termin ___ ___?","gaps":[["Könnten Sie"],["bitte"],["wiederholen"]],"solution":"Entschuldigen Sie, es ist so laut da. **Könnten Sie** den Termin **bitte wiederholen**?","en":"Mi scusi, qui c'è così tanto rumore. Potrebbe ripetere l'orario, per favore?","why":"Richiesta cortese: *Könnten Sie* … infinito *wiederholen* alla fine. *der Termin* qui = l'orario dell'appuntamento.","source":"hueber"},{"label":"d","lead":"◆ D… i… S… etwas f…?  ○ Ja, gern.  ◆ W… S…, o… es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","text":"◆ ___ etwas ___? ○ Ja, gern. ◆ ___, ___ es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","gaps":[["Darf ich Sie"],["fragen"],["Wissen Sie"],["ob"]],"solution":"◆ **Darf ich Sie** etwas **fragen**? ○ Ja, gern. ◆ **Wissen Sie**, **ob** es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","en":"Posso chiederle una cosa? – Sì, certo. – Sa se sul treno delle 14.33 per Ginevra c'è anche un bistrot o un ristorante?","why":"*Darf ich Sie etwas fragen?* apre in modo cortese; *ob* introduce una domanda indiretta sì/no, quindi *gibt* va alla fine.","source":"hueber"}]},{"no":"15","tag":"C2","instruction":"Bilden Sie Wörter und ordnen Sie zu.","instruction_en":"Forma delle parole con le sillabe del riquadro e completa le frasi. Le sillabe barrate (Men, sa) sono usate nell'esempio.","phrases":["schrei · druck · ni · lung · ker · der · auf · Aus · ben · ho · Me · Wie · cha  (durchgestrichen im Beispiel: Men, sa)"],"example":[{"label":"a","text":"Ich wähle in der **Mensa** immer ein vegetarisches Gericht."}],"items":[{"label":"b","text":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten ___ geben? Diesmal will ich sie mir gleich in meinem Adressbuch ___, damit ich sie nicht wieder verliere.","gaps":[["Mechaniker"],["aufschreiben"]],"solution":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten **Mechaniker** geben? Diesmal will ich sie mir gleich in meinem Adressbuch **aufschreiben**, damit ich sie nicht wieder verliere.","en":"La mia macchina è di nuovo rotta. Potresti darmi ancora una volta il numero di telefono del tuo bravo meccanico, per favore? Questa volta voglio scrivermelo subito nella rubrica, così non lo perdo di nuovo.","why":"Me-cha-ni-ker (una persona che ripara le automobili) e auf-schrei-ben (infinito alla fine dopo *will*).","source":"hueber"},{"label":"c","text":"Was bedeutet der ___ «eine Entscheidung treffen»? Den habe ich noch nie gehört.","gaps":[["Ausdruck"]],"solution":"Was bedeutet der **Ausdruck** «eine Entscheidung treffen»? Den habe ich noch nie gehört.","en":"Che cosa significa l'espressione “eine Entscheidung treffen”? Non l'ho mai sentita.","why":"Aus-druck: *der Ausdruck* = espressione; *der* e *Den* mostrano che è maschile. (*eine Entscheidung treffen* = prendere una decisione.)","source":"hueber"},{"label":"d","text":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur ___.","gaps":[["Wiederholung"]],"solution":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur **Wiederholung**.","en":"Purtroppo dimentico spesso parole tedesche importanti. Ho bisogno di più tempo per il ripasso.","why":"Wie-der-ho-lung: *zur* = *zu der*, quindi segue un sostantivo femminile: *die Wiederholung* (ripasso, ripetizione).","source":"hueber"}]}]},{"page":"AB 134","heading":"D  Fremdsprachen lernen – aber wie?","heading_en":"Imparare le lingue straniere – ma come?","exercises":[{"no":"16","tag":"D1","instruction":"Fremdsprachen lernen – aber wie?","instruction_en":"Imparare le lingue straniere – ma come?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ordnen Sie zu.","part_instruction_en":"Chi dice cosa? Leggi i tre testi e scrivi dopo ogni frase la lettera del testo (A, B o C).","reading":[{"label":"A  Mila, 17 Jahre","text":"Ich finde es total wichtig, dass man neue Wörter lernt und sie immer wieder wiederholt. Ich schreibe sie auf kleine Zettel oder Karten, auf der einen Seite das fremdsprachige Wort und auf der anderen die Übersetzung in meine Muttersprache. Diese Wortkarten habe ich immer in meiner Handtasche. Jeden Tag fahre ich eine Stunde mit dem Zug zur Schule. Das ist langweilig. Da habe ich viel Zeit und dann hole ich meine Wortkarten heraus und wiederhole die Wörter."},{"label":"B  Hakan, 19 Jahre","text":"Ich lerne seit vier Jahren Englisch in der Schule. Mir hilft es sehr, wenn ich viel Englisch höre. Ich habe viele MP3s mit Übungen aus dem Englischbuch und für die Aussprache auf meinem Smartphone. Ausserdem habe ich im Internet gute englische Podcasts gefunden. Die höre ich, wenn ich unterwegs bin. Ich möchte irgendwann nach der Schule ein Jahr nach London gehen und mir dort einen Job suchen. Darum will ich gut Englisch sprechen und auch meine Aussprache verbessern."},{"label":"C  Danila, 16 Jahre","text":"Ich bin vor drei Jahren in die Schweiz gekommen. Jetzt kann ich schon ziemlich gut Deutsch. Viel Zuhören ist für mich am allerwichtigsten. Deswegen habe ich im Bus, auf der Strasse, einfach überall immer den Schweizern zugehört und viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien. So habe ich viele Wörter und kleine Sätze der Alltagssprache gelernt, sogar auf Dialekt. Immer nur Grammatik und Wörter lernen, das finde ich uninteressant."}],"example":[{"label":"1","text":"Ich möchte meine Aussprache verbessern. → **B**"}],"items":[{"label":"2","text":"Ich höre oft anderen Leuten zu. → ___","gaps":[["C","Danila"]],"solution":"Ich höre oft anderen Leuten zu. → **C**","en":"Ascolto spesso le altre persone. → C (Danila)","why":"Danila: *Deswegen habe ich … einfach überall immer den Schweizern zugehört.*","source":"hueber"},{"label":"3","text":"Auf dem Weg zur Schule lerne ich Wörter. → ___","gaps":[["A","Mila"]],"solution":"Auf dem Weg zur Schule lerne ich Wörter. → **A**","en":"Mentre vado a scuola imparo le parole. → A (Mila)","why":"Mila tira fuori i suoi bigliettini durante l'ora di treno per andare a scuola.","source":"hueber"},{"label":"4","text":"Ich möchte nach der Schule in England arbeiten. → ___","gaps":[["B","Hakan"]],"solution":"Ich möchte nach der Schule in England arbeiten. → **B**","en":"Dopo la scuola vorrei lavorare in Inghilterra. → B (Hakan)","why":"Hakan: *… ein Jahr nach London gehen und mir dort einen Job suchen.*","source":"hueber"},{"label":"5","text":"Ich schaue viel deutschsprachiges Fernsehen. → ___","gaps":[["C","Danila"]],"solution":"Ich schaue viel deutschsprachiges Fernsehen. → **C**","en":"Guardo molta televisione in lingua tedesca. → C (Danila)","why":"Danila: *… viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien.*","source":"hueber"},{"label":"6","text":"Ich schreibe Wortkarten. → ___","gaps":[["A","Mila"]],"solution":"Ich schreibe Wortkarten. → **A**","en":"Scrivo bigliettini con le parole. → A (Mila)","why":"Mila scrive la parola straniera su un lato del bigliettino e la traduzione sull'altro.","source":"hueber"}]},{"no":"16","part":"b","part_instruction":"Schreiben Sie Sätze.","part_instruction_en":"Scrivi la seconda frase: comincia con la parola data (Deshalb, Darum …) e usa le parole tra parentesi. Il verbo viene subito dopo la parola iniziale.","example":[{"label":"1","lead":"Mila möchte viele neue Wörter lernen. (neue Wörter auf Wortkarten schreiben)","text":"Deshalb **schreibt sie neue Wörter auf Wortkarten**."}],"items":[{"label":"2","lead":"Mila findet den Weg zur Schule langweilig. (mit Wortkarten neue Wörter wiederholen)","text":"","accept":["Darum wiederholt sie neue Wörter mit Wortkarten.","Darum wiederholt sie mit Wortkarten neue Wörter."],"solution":"**Darum wiederholt sie neue Wörter mit Wortkarten.**","en":"Per questo ripassa le parole nuove con i bigliettini.","why":"*Darum* occupa la 1a posizione, quindi segue il verbo coniugato *wiederholt*, poi il soggetto *sie*.","source":"darum"},{"label":"3","lead":"Hakan hilft es, wenn er viel Englisch hört. (viele Podcasts auf seinem Smartphone haben)","text":"","accept":["Aus diesem Grund hat er viele Podcasts auf seinem Smartphone."],"solution":"**Aus diesem Grund hat er viele Podcasts auf seinem Smartphone.**","en":"Per questo motivo ha molti podcast sul suo smartphone.","why":"*Aus diesem Grund* occupa la 1a posizione come *deshalb*: subito dopo il verbo *hat*, poi *er*.","source":"hueber"},{"label":"4","lead":"Hakan möchte nach der Schule ein Jahr in London arbeiten. (gut Englisch sprechen wollen)","text":"","accept":["Deswegen will er gut Englisch sprechen."],"solution":"**Deswegen will er gut Englisch sprechen.**","en":"Per questo vuole parlare bene l'inglese.","why":"*Deswegen* + verbo modale *will* in 2a posizione, infinito *sprechen* alla fine.","source":"deswegen"},{"label":"5","lead":"Danila findet Grammatik und Wörter lernen uninteressant. (viel deutschsprachiges Fernsehen schauen)","text":"","accept":["Daher schaut sie viel deutschsprachiges Fernsehen."],"solution":"**Daher schaut sie viel deutschsprachiges Fernsehen.**","en":"Perciò guarda molta televisione in lingua tedesca.","why":"*Daher* significa lo stesso di *deshalb*; il verbo *schaut* viene subito dopo.","source":"deshalb"},{"label":"6","lead":"Für Danila ist Zuhören am allerwichtigsten. (einfach überall immer den Schweizern zugehört)","text":"","accept":["Aus diesem Grund hört sie einfach überall immer den Schweizern zu.","Aus diesem Grund hat sie einfach überall immer den Schweizern zugehört."],"solution":"**Aus diesem Grund hört sie einfach überall immer den Schweizern zu.**","en":"Per questo motivo ascolta semplicemente gli svizzeri, sempre e ovunque.","why":"*zuhören* è separabile: *hört … zu*. Il testo stampa *zugehört*, quindi è corretto anche il Perfekt *hat … zugehört* (come nel testo di Danila).","source":"hueber","check":"La soluzione ufficiale dà il presente (*hört … zu*), anche se il testo stampa il participio *zugehört*. Entrambe le frasi sono tedesco corretto; chiedi al tuo insegnante quale vuole il libro."}]}]},{"page":"AB 138","heading":"Test Lektion 4","heading_en":"Test della lezione 4","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Completa il testo di Arif. Il libro dà la prima lettera e alcune lettere all'interno di ogni parola; scrivi la parola intera.","reading":[{"text":"Ich heisse Arif und bin 16 Jahre alt. Meine Familie und ich stammen (a) aus Syrien und unsere M… (b) ist Arabisch. Jetzt lerne ich seit einem Jahr Deutsch. Nächstes Jahr möchte ich eine Lehre beginnen. D… (c) möchte ich mein Deutsch verbessern. Natürlich spreche ich dann noch nicht f… (d) Deutsch. Besonders die Schrift und die A… (e) finde ich schwierig und ich verstehe auch noch nicht alle A… (f). Aber ich bin optimistisch."}],"example":[{"label":"a","text":"Meine Familie und ich **stammen** aus Syrien."}],"items":[{"label":"b","lead":"… und unsere M _ t _ _ _ s _ _ _ c _ _ ist Arabisch.","text":"… und unsere ___ ist Arabisch.","gaps":[["Muttersprache"]],"solution":"… und unsere **Muttersprache** ist Arabisch.","en":"… e la nostra lingua madre è l'arabo.","why":"*die Muttersprache* = la prima lingua con cui cresci."},{"label":"c","lead":"D _ _ _ e _ e _ möchte ich mein Deutsch verbessern.","text":"___ möchte ich mein Deutsch verbessern.","gaps":[["Deswegen"]],"solution":"**Deswegen** möchte ich mein Deutsch verbessern.","en":"Per questo vorrei migliorare il mio tedesco.","why":"Lo schema delle lettere (D, e, e) corrisponde a *Deswegen*; esprime la conseguenza, e il verbo *möchte* viene subito dopo.","source":"deswegen"},{"label":"d","lead":"Natürlich spreche ich dann noch nicht f _ _ _ _ _ e _ _ Deutsch.","text":"Natürlich spreche ich dann noch nicht ___ Deutsch.","gaps":[["fliessend"]],"solution":"Natürlich spreche ich dann noch nicht **fliessend** Deutsch.","en":"Naturalmente allora non parlerò ancora il tedesco correntemente.","why":"*fliessend* = correntemente, fluente. Ortografia svizzera con *ss*."},{"label":"e","lead":"Besonders die Schrift und die A _ _ _ p _ _ _ _ e finde ich schwierig …","text":"Besonders die Schrift und die ___ finde ich schwierig …","gaps":[["Aussprache"]],"solution":"Besonders die Schrift und die **Aussprache** finde ich schwierig …","en":"Trovo difficili soprattutto la scrittura e la pronuncia …","why":"*die Aussprache* = pronuncia (*aussprechen* = pronunciare)."},{"label":"f","lead":"… und ich verstehe auch noch nicht alle A _ _ d _ _ c _ e.","text":"… und ich verstehe auch noch nicht alle ___.","gaps":[["Ausdrücke"]],"solution":"… und ich verstehe auch noch nicht alle **Ausdrücke**.","en":"… e non capisco ancora nemmeno tutte le espressioni.","why":"*der Ausdruck, die Ausdrücke* = espressione/espressioni; *alle* richiede il plurale."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit wenn.","instruction_en":"Scrivi frasi ipotetiche irreali con *wenn* e il Konjunktiv II (*wäre, hätte, könnte, müsste* o *würde* + infinito).","example":[{"label":"a","lead":"(ich heute nicht so viel vorhaben – spazieren gehen)","text":"Wenn **ich heute nicht so viel vorhätte, würde ich spazieren gehen**."}],"items":[{"label":"b","lead":"(ich mein Englisch besser sein – dir bei der Hausaufgabe helfen können)","text":"","accept":["Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.","Wenn mein Englisch besser wäre, würde ich dir bei der Hausaufgabe helfen können."],"solution":"**Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.**","en":"Se il mio inglese fosse migliore, potrei aiutarti con i compiti.","why":"*sein* → **wäre** alla fine della frase con *wenn*; *können* → **könnte**, poi la principale comincia con il verbo.","source":"kond"},{"label":"c","lead":"(ich euch besser verstehen – ihr nicht durcheinander sprechen)","text":"","accept":["Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.","Ich würde euch besser verstehen, wenn ihr nicht durcheinandersprechen würdet.","Ich könnte euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet."],"solution":"**Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.**","en":"Vi capirei meglio se non parlaste tutti insieme.","why":"Prima la principale; *würde* + infinito in entrambe le parti. Nella frase con *wenn* *würdet* va alla fine.","source":"kond"},{"label":"d","lead":"(ich mehr Freizeit haben – nicht so viel arbeiten müssen)","text":"","accept":["Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste."],"solution":"**Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste.**","en":"Avrei più tempo libero se non dovessi lavorare così tanto.","why":"*haben* → **hätte**, *müssen* → **müsste** (alla fine della frase con *wenn*).","source":"k2"}]},{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Completa con una parola del riquadro. Ogni parola si usa una volta; quella barrata è usata nell'esempio (la soluzione della frase a).","box":["denn","Weshalb","Weil","Wegen","Deswegen"],"box_used":[2],"box_exact":true,"items":[{"label":"a","text":"___ möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","gaps":[["Weshalb"]],"solution":"**Weshalb** möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","en":"Perché Costa vuole diventare meccatronico? – Perché si interessa di automobili.","why":"Serve una parola interrogativa; **Weshalb** = *warum* (perché). La risposta stampata comincia con *Weil*.","source":"weil"},{"label":"b","text":"___ seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","gaps":[["Wegen"]],"solution":"**Wegen** seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","en":"Grazie alle sue buone conoscenze di tedesco ha trovato in fretta un posto di apprendistato.","why":"Segue un gruppo nominale (*seiner guten Deutschkenntnisse*, genitivo plurale) → la preposizione **Wegen**.","source":"wegen"},{"label":"c","text":"Er ist erst 17 Jahre alt. ___ wohnt er noch bei seinen Eltern.","gaps":[["Deswegen"]],"solution":"Er ist erst 17 Jahre alt. **Deswegen** wohnt er noch bei seinen Eltern.","en":"Ha solo 17 anni. Per questo abita ancora dai suoi genitori.","why":"Una conseguenza, e il verbo viene subito dopo lo spazio (*wohnt er*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Jetzt spart er Geld, ___ er möchte nach der Ausbildung eine eigene Wohnung haben.","gaps":[["denn"]],"solution":"Jetzt spart er Geld, **denn** er möchte nach der Ausbildung eine eigene Wohnung haben.","en":"Adesso risparmia, perché dopo la formazione vorrebbe avere un appartamento suo.","why":"Una causa, e il verbo resta in 2a posizione (*er möchte*) → **denn**.","source":"denn"}]},{"no":"4","instruction":"Wie kann man auch sagen? Ergänzen Sie.","instruction_en":"In quale altro modo puoi dirlo? Completa la seconda espressione. Il libro dà alcune lettere; scrivi le parole intere.","example":[{"label":"a","text":"Können Sie mir sagen, wo …? – **Wissen Sie**, wo …?"}],"items":[{"label":"b","lead":"Ich habe eine Frage. – D _ _ _  i _ _  S _ _  e _ _ _ _  f _ _ _ _ _?","text":"Ich habe eine Frage. – ___?","gaps":[["Darf ich Sie etwas fragen"]],"solution":"Ich habe eine Frage. – **Darf ich Sie etwas fragen**?","en":"Ho una domanda. – Posso chiederle una cosa?","why":"Un modo cortese per introdurre una domanda: *Darf ich Sie etwas fragen?*"},{"label":"c","lead":"Könnten Sie das bitte noch einmal sagen? – K _ _ _ t _ _  S _ _  d _ s  b _ _ t _  wi _ _ _ h _ _ _ _?","text":"Könnten Sie das bitte noch einmal sagen? – ___?","gaps":[["Könnten Sie das bitte wiederholen"]],"solution":"Könnten Sie das bitte noch einmal sagen? – **Könnten Sie das bitte wiederholen**?","en":"Potrebbe dirlo ancora una volta, per favore? – Potrebbe ripeterlo, per favore?","why":"*wiederholen* = ripetere = *noch einmal sagen*."},{"label":"d","lead":"Was meinen Sie mit …? – W _ _  b _ _ e _ _ _ _ …?","text":"Was meinen Sie mit …? – ___ …?","gaps":[["Was bedeutet"]],"solution":"Was meinen Sie mit …? – **Was bedeutet** …?","en":"Che cosa intende con …? – Che cosa significa …?","why":"*Was bedeutet …?* chiede il significato, come *Was meinen Sie mit …?*","check":"Nella foto le lettere di questo spazio si leggono male; *Was bedeutet …?* corrisponde a quelle lettere ed è l'espressione dell'esercizio 13. Chiedi al tuo insegnante se il tuo libro mostra altro."},{"label":"e","lead":"Entschuldigung. – T _ _  m _ _  l _ _ _.","text":"Entschuldigung. – ___.","gaps":[["Tut mir leid"]],"solution":"Entschuldigung. – **Tut mir leid**.","en":"Scusi. – Mi dispiace.","why":"*Tut mir leid* = mi dispiace, un altro modo per scusarsi."}]}]},{"page":"AB 139","heading":"Fokus Beruf: Stellensuche","heading_en":"Focus lavoro: cercare un impiego","exercises":[{"no":"1","instruction":"Yusuf sucht eine neue Stelle als Coiffeur. Er liest eine Broschüre mit Tipps für die Stellensuche. Lesen Sie die Tipps und ordnen Sie die Überschriften zu.","instruction_en":"Yusuf cerca un nuovo lavoro come parrucchiere. Legge un opuscolo con consigli per la ricerca di lavoro. Leggi i consigli e scrivi dopo ogni paragrafo la lettera del titolo giusto (A–E).","reading":[{"label":"1","text":"Machen Sie eine Liste von Personen, die Sie persönlich kennen: Bekannte, Kollegen, Freunde und Verwandte. Notieren Sie auch die Namen von früheren Arbeitgebern und Arbeitskollegen. Informieren Sie diese Personen – mündlich oder schriftlich – darüber, dass Sie auf Stellensuche sind. Wichtig: Informieren Sie Ihre Kontaktpersonen, wenn Sie eine Stelle gefunden haben."},{"label":"2","text":"Werden Sie aktiv. Warten Sie nicht, bis Sie ein passendes Stelleninserat finden, sondern schreiben Sie Ihre eigene Stellenanzeige. Suchen Sie ein Internet-Portal, das zu Ihrer Branche passt, und präsentieren Sie sich. Solche Annoncen kosten viel weniger als gedruckte Annoncen und Sie können sie ausserdem noch mit einer eigenen Bewerber-Website verbinden."},{"label":"3","text":"Erhöhen Sie Ihre Erfolgschancen mit einer Kurzbewerbung. Suchen Sie sich Ihre Wunschfirma und bewerben Sie sich. Dafür braucht es natürlich eine gute Recherche, damit Sie die «richtige» Firma und die «richtige» Person anschreiben. Wie ihr Name sagt, ist diese Bewerbung kurz: Sie besteht aus einem Bewerbungsschreiben und dem tabellarischen Lebenslauf."},{"label":"4","text":"Sind in Ihrer Branche Bewerbungen per Telefon üblich? Sind Sie besonders mutig und überzeugen vor allem mündlich sehr gut? Aus welchem Grund Sie sich für diese Bewerbungsform entscheiden: Wichtig ist auch hier eine gründliche Vorbereitung. Machen Sie Notizen und üben Sie das Gespräch mit Freunden. Fehlt Ihnen der Mut dazu, wählen Sie die schriftliche Bewerbung."},{"label":"5","text":"Die grösste Auswahl an Stelleninseraten finden Sie im Internet. Wichtig ist eine sorgfältige Analyse der Inserate: Was will die Firma? Welche Qualifikationen und Erfahrungen haben Sie? Machen Sie eine Liste und beantworten Sie diese Fragen. Können Sie ca. 80 Prozent der Anforderungen erfüllen, dann ist eine Bewerbung sinnvoll."}],"items":[{"label":"1","text":"Absatz 1 (Liste von Personen, die Sie kennen) → ___","gaps":[["C","C Das persönliche Netzwerk"]],"solution":"Absatz 1 (Liste von Personen, die Sie kennen) → **C**","en":"Paragrafo 1 (un elenco di persone che conosci) → C, La tua rete personale","why":"Amici, colleghi ed ex datori di lavoro sono la tua rete personale.","source":"hueber"},{"label":"2","text":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → ___","gaps":[["A","A Online-Stellengesuch"]],"solution":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → **A**","en":"Paragrafo 2 (il tuo annuncio di ricerca di lavoro su internet) → A, Annuncio di ricerca di lavoro online","why":"*das Stellengesuch* = un annuncio in cui cerchi lavoro; qui su un portale internet.","source":"hueber"},{"label":"3","text":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → ___","gaps":[["E","E Spontanbewerbung"]],"solution":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → **E**","en":"Paragrafo 3 (una breve candidatura presso l'azienda dei tuoi sogni) → E, Candidatura spontanea","why":"Ti candidi presso un'azienda che non ha pubblicato nessuna offerta di lavoro: *die Spontanbewerbung*.","source":"hueber"},{"label":"4","text":"Absatz 4 (Bewerbungen per Telefon) → ___","gaps":[["D","D Telefonische Bewerbung"]],"solution":"Absatz 4 (Bewerbungen per Telefon) → **D**","en":"Paragrafo 4 (candidarsi per telefono) → D, Candidatura telefonica","why":"*per Telefon* = *telefonisch*.","source":"hueber"},{"label":"5","text":"Absatz 5 (Stelleninserate im Internet analysieren) → ___","gaps":[["B","B Stelleninserate"]],"solution":"Absatz 5 (Stelleninserate im Internet analysieren) → **B**","en":"Paragrafo 5 (analizzare gli annunci di lavoro su internet) → B, Annunci di lavoro","why":"*das Stelleninserat* (svizzero) = un annuncio di lavoro pubblicato da un'azienda.","source":"hueber"}],"phrases":["A Online-Stellengesuch","B Stelleninserate","C Das persönliche Netzwerk","D Telefonische Bewerbung","E Spontanbewerbung"]},{"no":"2","instruction":"Yusuf hat entschieden, selbst aktiv zu werden, und hat ein Stellengesuch geschrieben. Lesen Sie seinen Text und unterstreichen Sie: – Wer und wie ist Yusuf? – Was kann er? – Was sucht er?","instruction_en":"Yusuf ha deciso di prendere l'iniziativa e ha scritto un annuncio in cui cerca lavoro. Leggi il suo testo e trova: chi è Yusuf e com'è, che cosa sa fare e che cosa cerca. Scrivi le parole giuste per ogni domanda.","reading":[{"text":"Suchen Sie einen engagierten Coiffeur, der kreativ und flexibel ist? Dann rufen Sie mich, 24, an. Ich biete sechs Jahre Berufserfahrung und diverse Weiterbildungen im Bereich Stilberatung. Ich suche eine Herausforderung, bei der ich Neues lernen und mich weiter spezialisieren kann."}],"items":[{"label":"1","lead":"Wer und wie ist Yusuf?","text":"","open":true,"solution":"ein engagierter Coiffeur, kreativ und flexibel, 24 Jahre alt","en":"un parrucchiere motivato, creativo e flessibile, 24 anni","why":"Chi è (professione, età) e com'è (aggettivi).","source":"hueber"},{"label":"2","lead":"Was kann er?","text":"","open":true,"solution":"sechs Jahre Berufserfahrung, diverse Weiterbildungen im Bereich Stilberatung","en":"sei anni di esperienza professionale, diversi corsi di perfezionamento nel campo della consulenza d'immagine","why":"Che cosa offre: esperienza e formazione.","source":"hueber"},{"label":"3","lead":"Was sucht er?","text":"","open":true,"solution":"eine Herausforderung, bei der er Neues lernen und sich weiter spezialisieren kann","en":"una sfida in cui possa imparare cose nuove e specializzarsi ulteriormente","why":"L'ultima frase: *Ich suche …*","source":"hueber"}]},{"no":"3","instruction":"Ein Stellengesuch im Internet aufgeben. Sie suchen eine neue Stelle. Machen Sie eine Tabelle. Schreiben Sie dann einen Profiltext wie in 2.","instruction_en":"Pubblica su internet un annuncio in cui cerchi lavoro. Stai cercando un nuovo impiego. Fai una tabella con tre colonne (Chi sono e come sono? Che cosa so fare? Che cosa cerco?), poi scrivi un testo di presentazione come quello di Yusuf in 2. La risposta modello è una possibilità.","phrases":["teamfähig/selbstständig/kontaktfreudig/zuverlässig/verantwortungsbewusst / … sein","gute Computer-/Sprachkenntnisse/Kenntnisse in … haben","gut mit … umgehen können","… Vollzeit/Teilzeit/auf Stundenbasis arbeiten","ab sofort / ab nächstem Monat / … suchen"],"example":[{"label":"Tabelle","text":"Wer und wie bin ich? flexibel, teamfähig, … | Was kann ich? … | Was suche ich? …"}],"items":[{"label":"1","lead":"Tabelle","text":"","open":true,"solution":"Wer und wie bin ich? flexibel, teamfähig, zuverlässig, kontaktfreudig | Was kann ich? gut mit Kunden umgehen, gute Computerkenntnisse, fliessend Deutsch und Englisch | Was suche ich? eine Teilzeitstelle ab nächstem Monat, ein internationales Team","en":"Chi sono e come sono? flessibile, capace di lavorare in team, affidabile, socievole | Che cosa so fare? trattare bene con i clienti, buone conoscenze informatiche, tedesco e inglese fluenti | Che cosa cerco? un posto a tempo parziale dal mese prossimo, un team internazionale","why":"Bastano poche parole chiave per colonna; usa le espressioni del riquadro.","source":"hueber"},{"label":"2","lead":"Profiltext","text":"","open":true,"solution":"Suchen Sie eine zuverlässige Verkäuferin, die teamfähig und kontaktfreudig ist? Ich kann gut mit Kunden umgehen, habe gute Computerkenntnisse und spreche fliessend Deutsch und Englisch. Ich suche ab nächstem Monat eine Teilzeitstelle in einem internationalen Team.","en":"Cercate una venditrice affidabile, capace di lavorare in team e socievole? So trattare bene con i clienti, ho buone conoscenze informatiche e parlo correntemente tedesco e inglese. Dal mese prossimo cerco un posto a tempo parziale in un team internazionale.","why":"Gli stessi tre passi di Yusuf: chi sei, che cosa sai fare, che cosa cerchi. Nella frase relativa *die* si riferisce a *Verkäuferin*.","source":"hueber"}]}]},{"page":"Test L4 · 19","heading":"Grammatik","heading_en":"Grammatica","exercises":[{"no":"1","instruction":"Wunsch und Realität?","instruction_en":"Desiderio e realtà?","part":"a","part_instruction":"Ergänzen Sie.","part_instruction_en":"Nina deve fare una cosa, ma ne farebbe volentieri un'altra. Scrivi che cosa preferirebbe fare con *würde* + le parole tra parentesi (con *lieber*, o *gern* nella frase 5).","example":[{"label":"1","lead":"Nina macht Diät. (Sahnetorte essen)","text":"Aber sie **würde lieber Sahnetorte essen**."}],"items":[{"label":"2","lead":"Nina muss für eine Sprachprüfung lernen. (Musik hören)","text":"Aber sie ___.","gaps":[["würde lieber Musik hören"]],"solution":"Aber sie **würde lieber Musik hören**.","en":"Ma preferirebbe ascoltare musica.","why":"*würde* in 2a posizione, *lieber* = piuttosto, infinito *hören* alla fine.","source":"k2"},{"label":"3","lead":"Nina muss ihre Kleider aufräumen. (mit ihrer Freundin telefonieren)","text":"Aber sie ___.","gaps":[["würde lieber mit ihrer Freundin telefonieren"]],"solution":"Aber sie **würde lieber mit ihrer Freundin telefonieren**.","en":"Ma preferirebbe telefonare alla sua amica.","why":"*würde* + *lieber* + infinito alla fine.","source":"k2"},{"label":"4","lead":"Nina arbeitet am Computer. (Computerspiele spielen)","text":"Aber sie ___.","gaps":[["würde lieber Computerspiele spielen"]],"solution":"Aber sie **würde lieber Computerspiele spielen**.","en":"Ma preferirebbe giocare ai videogiochi.","why":"*würde* + *lieber* + infinito alla fine.","source":"k2"},{"label":"5","lead":"Nina hat morgen sehr früh einen Termin. (bis spät in die Nacht lesen)","text":"Sie ___ gern ___.","gaps":[["würde aber"],["bis spät in die Nacht lesen"]],"solution":"Sie **würde aber** gern **bis spät in die Nacht lesen**.","en":"Però le piacerebbe leggere fino a tarda notte.","why":"Il libro stampa *gern*: *würde* + *gern* + infinito (un desiderio), con *aber* dopo il verbo.","source":"k2"},{"label":"6","lead":"Nina verbringt den Abend mit ihren Eltern. (tanzen gehen)","text":"Aber sie ___.","gaps":[["würde lieber tanzen gehen"]],"solution":"Aber sie **würde lieber tanzen gehen**.","en":"Ma preferirebbe andare a ballare.","why":"*würde* + *lieber*; entrambi gli infiniti *tanzen gehen* alla fine.","source":"k2"}]},{"no":"1","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Riscrivi le frasi di a come frasi ipotetiche irreali: *Wenn Nina nicht …, würde sie …*","example":[{"label":"1","text":"Wenn Nina nicht Diät machen würde, würde sie Sahnetorte essen."}],"items":[{"label":"2","text":"","accept":["Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören."],"solution":"**Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören.**","en":"Se Nina non dovesse studiare per un esame di lingua, ascolterebbe musica.","why":"*muss* → **müsste** alla fine della frase con *wenn*; la principale comincia con *würde*.","source":"kond"},{"label":"3","text":"","accept":["Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.","Wenn Nina ihre Kleider nicht aufräumen müsste, würde sie mit ihrer Freundin telefonieren."],"solution":"**Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.**","en":"Se Nina non dovesse riordinare i suoi vestiti, telefonerebbe alla sua amica.","why":"*müsste* + infinito *aufräumen*: nella frase con *wenn* *müsste* va per ultimo.","source":"kond"},{"label":"4","text":"","accept":["Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.","Wenn Nina nicht am Computer arbeiten müsste, würde sie Computerspiele spielen."],"solution":"**Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.**","en":"Se Nina non lavorasse al computer, giocherebbe ai videogiochi.","why":"La soluzione accetta *arbeiten würde* o *arbeiten müsste* nella frase con *wenn*."},{"label":"5","text":"","accept":["Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.","Wenn Nina morgen keinen Termin sehr früh hätte, würde sie bis spät in die Nacht lesen."],"solution":"**Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.**","en":"Se domani Nina non avesse un appuntamento molto presto, leggerebbe fino a tarda notte.","why":"*hat* → **hätte**, alla fine della frase con *wenn*."},{"label":"6","text":"","accept":["Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.","Wenn Nina den Abend nicht mit ihren Eltern verbringen müsste, würde sie tanzen gehen."],"solution":"**Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.**","en":"Se Nina non passasse la serata con i suoi genitori, andrebbe a ballare.","why":"*würde* + infinito in entrambe le parti; *verbringen würde* alla fine della frase con *wenn*."}]},{"no":"2","instruction":"Ergänzen Sie: darum – weil – wegen.","instruction_en":"Completa con *darum*, *weil* o *wegen*. Ogni parola si usa due volte.","box":["darum","weil","wegen"],"items":[{"label":"a","text":"Viele Deutsche hören Majids Grammatikfehler nicht, ___ er eine sehr gute Aussprache hat.","gaps":[["weil"]],"solution":"Viele Deutsche hören Majids Grammatikfehler nicht, **weil** er eine sehr gute Aussprache hat.","en":"Molti tedeschi non sentono gli errori di grammatica di Majid, perché ha un'ottima pronuncia.","why":"Una causa, e il verbo *hat* è alla fine → **weil**.","source":"weil"},{"label":"b","text":"Mirko hat die Prüfung nicht bestanden, ___ will er jetzt einen Intensivkurs machen.","gaps":[["darum"]],"solution":"Mirko hat die Prüfung nicht bestanden, **darum** will er jetzt einen Intensivkurs machen.","en":"Mirko non ha superato l'esame, per questo ora vuole fare un corso intensivo.","why":"Una conseguenza, e il verbo *will* viene subito dopo lo spazio → **darum**.","source":"darum"},{"label":"c","text":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, ___ braucht er sehr gute Deutschkenntnisse.","gaps":[["darum"]],"solution":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, **darum** braucht er sehr gute Deutschkenntnisse.","en":"Hassan vuole lavorare come medico in un ospedale tedesco, per questo ha bisogno di ottime conoscenze di tedesco.","why":"Conseguenza + verbo subito dopo lo spazio (*braucht er*) → **darum**.","source":"darum"},{"label":"d","text":"Camilla ist Managerin und kann ___ ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","gaps":[["wegen"]],"solution":"Camilla ist Managerin und kann **wegen** ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","en":"Camilla è manager e, a causa delle sue numerose conferenze, non può frequentare regolarmente il corso di tedesco.","why":"Segue un gruppo nominale (*ihrer vielen Konferenzen*, genitivo plurale) → **wegen**.","source":"wegen"},{"label":"e","text":"Boris wird ___ seines Akzents sofort als Russe erkannt.","gaps":[["wegen"]],"solution":"Boris wird **wegen** seines Akzents sofort als Russe erkannt.","en":"Boris viene subito riconosciuto come russo a causa del suo accento.","why":"Gruppo nominale al genitivo (*seines Akzents*) → **wegen**.","source":"wegen"},{"label":"f","text":"Anja würde gern Arabisch lernen, ___ sie die arabische Schrift so schön findet.","gaps":[["weil"]],"solution":"Anja würde gern Arabisch lernen, **weil** sie die arabische Schrift so schön findet.","en":"Ad Anja piacerebbe imparare l'arabo, perché trova così bella la scrittura araba.","why":"Causa con il verbo *findet* alla fine → **weil**.","source":"weil"}]}]},{"page":"Test L4 · 20","heading":"Wortschatz","heading_en":"Lessico","exercises":[{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Completa il testo di Ferdez con le parole del riquadro. Ogni parola si usa una volta; quella barrata è usata nell'esempio. La scheda usa l'ortografia tedesca con l'Eszett; qui si usa l'ortografia svizzera con *ss* (*fliessend*).","box":["Akzent","fliessend","schimpfe","Muttersprache","Schrift","übersetzen","vergleiche"],"box_used":[3],"box_exact":true,"example":[{"label":"a","text":"Mein Name ist Ferdez. Ich komme aus Mazedonien. Meine **Muttersprache** ist Albanisch, aber ich spreche auch Mazedonisch."}],"items":[{"label":"b","text":"Im Mazedonischen wird die kyrillische ___ verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","gaps":[["Schrift"]],"solution":"Im Mazedonischen wird die kyrillische **Schrift** verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","en":"In macedone si usa l'alfabeto cirillico. Per questo all'inizio non è stato facile per me scrivere in tedesco.","why":"*die kyrillische Schrift* = l'alfabeto cirillico."},{"label":"c","text":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich ___ Deutsch, finde ich.","gaps":[["fliessend"]],"solution":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich **fliessend** Deutsch, finde ich.","en":"Vivo in Baviera da otto anni. Ormai parlo il tedesco correntemente, mi pare.","why":"*fliessend Deutsch sprechen* = parlare il tedesco correntemente."},{"label":"d","text":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen ___ habe!","gaps":[["Akzent"]],"solution":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen **Akzent** habe!","en":"Ma i miei colleghi della Germania del Nord dicono che ho un accento bavarese!","why":"*einen … Akzent haben* = avere un accento; *einen bayerischen* → sostantivo maschile."},{"label":"e","text":"Wenn ich auf Bayerisch ___, lachen meine Kollegen sich kaputt.","gaps":[["schimpfe"]],"solution":"Wenn ich auf Bayerisch **schimpfe**, lachen meine Kollegen sich kaputt.","en":"Quando impreco in bavarese, i miei colleghi si sbellicano dalle risate.","why":"*schimpfen* = brontolare, imprecare; *ich schimpfe* alla fine della frase con *wenn*."},{"label":"f","text":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander ___, dann fällt mir auf, …","gaps":[["vergleiche"]],"solution":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander **vergleiche**, dann fällt mir auf, …","en":"Quando confronto tra loro il tedesco, il macedone e l'albanese, noto …","why":"*miteinander vergleichen* = confrontare tra loro; *ich vergleiche* alla fine della frase con *wenn*."},{"label":"g","text":"… dass man nicht alle Wörter wirklich gut in die andere Sprache ___ kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","gaps":[["übersetzen"]],"solution":"… dass man nicht alle Wörter wirklich gut in die andere Sprache **übersetzen** kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","en":"… che non tutte le parole si possono tradurre davvero bene nell'altra lingua. Oggi mi sento a casa sia in Macedonia sia in Germania.","why":"*in eine Sprache übersetzen* = tradurre in una lingua; l'infinito sta prima di *kann*, alla fine della frase con *dass*."}]},{"no":"Pause","instruction":"Was bedeutet das? Kreuzen Sie an. «Lügen haben kurze Beine.»","instruction_en":"Che cosa significa il proverbio “Lügen haben kurze Beine” (le bugie hanno le gambe corte)? Scrivi A o B.","items":[{"label":"A/B","lead":"A Die Wahrheit kommt immer schnell ans Licht. Darum sollte man nicht lügen.  B Wer lügt, der bekommt zur Strafe kurze Beine.","text":"___","gaps":[["A"]],"solution":"**A**","en":"A: La verità viene sempre fuori in fretta. Per questo non si dovrebbe mentire.","why":"Una bugia non va lontano, come chi ha le gambe corte: viene scoperta presto. B è un gioco sul senso letterale delle parole."}]},{"no":"4","instruction":"Welches Wort passt auch? Notieren Sie.","instruction_en":"Quale parola del riquadro potrebbe sostituire la parola sottolineata? Scrivila. Ogni parola si usa una volta; quella barrata è usata nell'esempio. Le parole sottolineate sono in grassetto.","box":["allerdings","allmählich","aufschreiben","deswegen","ebenso","irgendwann","korrekt","stammt"],"box_used":[7],"box_exact":true,"example":[{"label":"a","text":"Meine Familie **kommt** aus Iran. → stammt"}],"items":[{"label":"b","lead":"Ich selbst bin **aber** in Mainz geboren.","text":"___","gaps":[["allerdings"]],"solution":"**allerdings**","en":"Io però sono nato a Magonza.","why":"*allerdings* = *aber*: limita quanto detto prima."},{"label":"c","lead":"Mit mir haben meine Eltern immer Deutsch gesprochen, **deshalb** kann ich leider nicht Farsi.","text":"___","gaps":[["deswegen"]],"solution":"**deswegen**","en":"I miei genitori hanno sempre parlato tedesco con me, per questo purtroppo non so parlare il farsi.","why":"*deswegen* = *deshalb* (conseguenza, il verbo segue subito dopo).","source":"deswegen"},{"label":"d","lead":"Jetzt nehme ich an einem Sprachkurs teil. Ich finde, Farsi ist **genauso** schwierig wie Deutsch.","text":"___","gaps":[["ebenso"]],"solution":"**ebenso**","en":"Adesso faccio un corso di lingua. Secondo me il farsi è difficile quanto il tedesco.","why":"*ebenso … wie* = *genauso … wie* = tanto … quanto."},{"label":"e","lead":"Besonders die Schrift! Ich bin ein Mensch, der sich alle neuen Wörter **notieren** muss.","text":"___","gaps":[["aufschreiben"]],"solution":"**aufschreiben**","en":"Soprattutto la scrittura! Sono una persona che deve scriversi tutte le parole nuove.","why":"*sich etwas notieren* = *sich etwas aufschreiben* = annotarsi qualcosa."},{"label":"f","lead":"Das ist schwierig, wenn man es in einer Schrift tun muss, die man auch erst **langsam** lernt.","text":"___","gaps":[["allmählich"]],"solution":"**allmählich**","en":"È difficile se devi farlo in una scrittura che stai imparando solo a poco a poco.","why":"*allmählich* = lentamente, passo dopo passo, gradualmente."},{"label":"g","lead":"Auch die Aussprache ist nicht leicht. Es gibt da diesen Laut «gh», den kann ich nicht **richtig** aussprechen.","text":"___","gaps":[["korrekt"]],"solution":"**korrekt**","en":"Anche la pronuncia non è facile. C'è questo suono “gh” che non riesco a pronunciare correttamente.","why":"*korrekt* = *richtig* = correttamente."},{"label":"h","lead":"**Eines Tages** klappt es – hoffe ich jedenfalls!","text":"___","gaps":[["irgendwann","Irgendwann"]],"solution":"**irgendwann**","en":"Prima o poi ci riuscirò – almeno lo spero!","why":"*irgendwann* = prima o poi, un giorno = *eines Tages*."}]}]},{"page":"Test L4 · 21","heading":"Lesen","heading_en":"Lettura","exercises":[{"no":"5","instruction":"Lesen Sie und kreuzen Sie an: Was ist richtig?","instruction_en":"Leggi le risposte al sondaggio “È importante imparare il tedesco?” e scegli la fine giusta per ogni frase. Scrivi la fine (o solo le sue prime parole).","reading":[{"label":"Brad, 30, aus Australien","text":"«Meine Freundin ist Deutsche. Deshalb bin ich vor einem Jahr nach Deutschland gekommen. Ich dachte, dass ich mit Englisch als Muttersprache keine Schwierigkeiten haben würde, einen Job zu finden. Aber immer wenn ich mich bewarb, bekam ich zur Antwort: Lernen Sie erst einmal richtig Deutsch. Dann können Sie wiederkommen. Offenbar glauben die Leute, dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht. Seit sechs Monaten besuche ich nun einen Deutschkurs.»"},{"label":"Alena, 24, aus Tschechien","text":"«Meine Grossmutter hat 30 Jahre in Wien gelebt. Ich habe sie als Kind oft besucht und Wien dabei sehr gut kennengelernt. Ich denke, ich habe in Wien bessere Karrierechancen als bei uns zu Hause. Darum habe ich jetzt das Zertifikat Deutsch gemacht. Mit dem Zertifikat habe ich bestimmt gute Chancen, wenn ich mich bei österreichischen Firmen bewerbe.»"},{"label":"Ewa, 23, aus Polen","text":"«Ich finde es aus historischen Gründen wichtig, Deutsch zu lernen. Denn Polen und Deutschland verbindet eine lange Geschichte, die nicht immer schön war. Aber gerade deshalb ist es wichtig, dass wir uns gegenseitig gut kennenlernen. Ich würde mir wünschen, dass auch mehr Deutsche sich für die polnische Sprache interessieren würden.»"},{"label":"Sopha, 32, aus Thailand","text":"«Mein Mann stammt aus Hessen. Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche. Aber jetzt gehen unsere beiden Söhne zur Schule, und ich habe gemerkt, dass meine Deutschkenntnisse nicht mehr ausreichend sind: In der Kommunikation mit der Klassenlehrerin und bei Elternabenden habe ich grosse Schwierigkeiten. Deshalb nehme ich jetzt an einem Deutschkurs für Eltern teil.»"},{"label":"Abdullah, 35, aus Bahrain","text":"«Ich arbeite seit ein paar Monaten an einer deutschen Klinik als Arzt. Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen. Im Krankenhaus brauche ich eigentlich gar nicht so viel Deutsch, denn für die Gespräche mit den Patienten genügt mein Deutsch, und die Kollegen sprechen alle sehr gut Englisch. Aber natürlich möchte ich die Sprache des Landes gut können, in dem ich lebe. Dann versteht man die Menschen und ihr Land besser. Aus diesem Grund lerne ich weiter Deutsch.»"},{"label":"Zeliha, 45, aus der Türkei","text":"«Ich bin nach Dortmund gekommen, als ich meinen Mann – einen Deutschtürken – geheiratet habe. Schnell kamen vier Kinder zur Welt. Das Geld war immer knapp bei uns, deswegen habe ich neben dem Haushalt und der Kindererziehung Schicht gearbeitet. Für einen Deutschkurs war nie Zeit und Geld da. Meine Kinder haben oft geschimpft, weil ich so schlecht Deutsch sprach. Jetzt lerne ich endlich richtig Deutsch, und meine Kinder helfen mir beim Lernen.»"}],"items":[{"label":"a","lead":"Wer gut Englisch kann, … ○ findet in Deutschland problemlos einen Job. ○ muss trotzdem gut Deutsch lernen.","text":"Wer gut Englisch kann, ___.","gaps":[["muss trotzdem gut Deutsch lernen","muss trotzdem"]],"solution":"Wer gut Englisch kann, **muss trotzdem gut Deutsch lernen**.","en":"Chi sa bene l'inglese deve comunque imparare bene il tedesco.","why":"A Brad, che è di madrelingua inglese, dicevano di continuo: *Lernen Sie erst einmal richtig Deutsch.*"},{"label":"b","lead":"Deutsche glauben offenbar, … ○ dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat. ○ dass man für eine Ausbildung Deutsch braucht.","text":"Deutsche glauben offenbar, ___.","gaps":[["dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat","dass man ohne perfektes Deutsch"]],"solution":"Deutsche glauben offenbar, **dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat**.","en":"A quanto pare i tedeschi credono che senza un tedesco perfetto non si abbiano competenze professionali.","why":"Brad: *… dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht.*"},{"label":"c","lead":"Alena hofft, dass sie mit dem Zertifikat Deutsch … ○ eine Arbeitsstelle in Österreich findet. ○ besser Bewerbungen schreiben kann.","text":"Alena hofft, dass sie mit dem Zertifikat Deutsch ___.","gaps":[["eine Arbeitsstelle in Österreich findet","eine Arbeitsstelle"]],"solution":"Alena hofft, dass sie mit dem Zertifikat Deutsch **eine Arbeitsstelle in Österreich findet**.","en":"Alena spera di trovare un lavoro in Austria con il certificato di tedesco.","why":"Alena si aspetta buone possibilità *bei österreichischen Firmen*."},{"label":"d","lead":"Als Polin will Ewa Deutsch können, denn … ○ Deutschland und Polen haben eine gemeinsame Geschichte. ○ sie hat viele Deutsche kennengelernt.","text":"Als Polin will Ewa Deutsch können, denn ___.","gaps":[["Deutschland und Polen haben eine gemeinsame Geschichte","Deutschland und Polen"]],"solution":"Als Polin will Ewa Deutsch können, denn **Deutschland und Polen haben eine gemeinsame Geschichte**.","en":"Da polacca, Ewa vuole sapere il tedesco, perché la Germania e la Polonia hanno una storia comune.","why":"Ewa: *Denn Polen und Deutschland verbindet eine lange Geschichte.*"},{"label":"e","lead":"Ewa findet es … ○ toll, dass so viel Deutsche Polnisch sprechen. ○ schade, dass sich nicht so viele Deutsche für Polnisch interessieren.","text":"Ewa findet es ___.","gaps":[["schade, dass sich nicht so viele Deutsche für Polnisch interessieren","schade"]],"solution":"Ewa findet es **schade, dass sich nicht so viele Deutsche für Polnisch interessieren**.","en":"Ewa trova un peccato che non molti tedeschi si interessino al polacco.","why":"Ewa vorrebbe che più tedeschi si interessassero al polacco."},{"label":"f","lead":"Sopha hat … ○ von ihrem Mann Deutsch gelernt. ○ hat einen Integrationskurs besucht.","text":"Sopha hat ___.","gaps":[["von ihrem Mann Deutsch gelernt","von ihrem Mann"]],"solution":"Sopha hat **von ihrem Mann Deutsch gelernt**.","en":"Sopha ha imparato il tedesco da suo marito.","why":"Sopha: *Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche.*"},{"label":"g","lead":"Sie … ○ muss ihren Söhnen bei den Deutschhausaufgaben helfen. ○ hat Probleme, weil sie die Lehrer nicht gut genug versteht.","text":"Sie ___.","gaps":[["hat Probleme, weil sie die Lehrer nicht gut genug versteht","hat Probleme"]],"solution":"Sie **hat Probleme, weil sie die Lehrer nicht gut genug versteht**.","en":"Ha dei problemi perché non capisce abbastanza bene gli insegnanti.","why":"Con il docente di classe e alle riunioni dei genitori ha *grosse Schwierigkeiten*."},{"label":"h","lead":"Für die Arbeitserlaubnis … ○ werden gute Deutschkenntnisse erwartet. ○ braucht man gar nicht so gute Deutschkenntnisse.","text":"Für die Arbeitserlaubnis ___.","gaps":[["werden gute Deutschkenntnisse erwartet","werden gute"]],"solution":"Für die Arbeitserlaubnis **werden gute Deutschkenntnisse erwartet**.","en":"Per il permesso di lavoro si richiedono buone conoscenze di tedesco.","why":"Abdullah: *Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen.*"},{"label":"i","lead":"Abdullah will gut Deutsch können, weil … ○ die Patienten nicht Englisch sprechen. ○ er in Deutschland lebt.","text":"Abdullah will gut Deutsch können, weil ___.","gaps":[["er in Deutschland lebt"]],"solution":"Abdullah will gut Deutsch können, weil **er in Deutschland lebt**.","en":"Abdullah vuole sapere bene il tedesco perché vive in Germania.","why":"Vuole sapere la lingua *des Landes …, in dem ich lebe*; per i pazienti il suo tedesco basta già."},{"label":"j","lead":"Zeliha lernt Deutsch … ○ , weil sie Geld verdienen muss. ○ wegen ihrer Kinder.","text":"Zeliha lernt Deutsch ___.","gaps":[["wegen ihrer Kinder"]],"solution":"Zeliha lernt Deutsch **wegen ihrer Kinder**.","en":"Zeliha impara il tedesco per via dei suoi figli.","why":"I suoi figli si lamentavano che il suo tedesco fosse così scarso, e ora la aiutano a imparare."}]}]},{"page":"Test L4 · 22","heading":"Sprechen","heading_en":"Parlare","exercises":[{"no":"7","instruction":"Welche Reaktion passt am besten? Verbinden Sie.","instruction_en":"Quale risposta è la più adatta? Scrivi dopo ogni frase il numero della risposta (1–6). (L'esercizio 6 di questa pagina è un ascolto ed è omesso.)","example":[{"label":"a","text":"Darf ich Sie kurz etwas fragen? → **2** Natürlich, gern."}],"items":[{"label":"b","text":"Mein Name ist Kranitzky-Krampe. → ___","gaps":[["5"]],"solution":"Mein Name ist Kranitzky-Krampe. → **5**","en":"Mi chiamo Kranitzky-Krampe. → 5 Scusi, come ha detto che si chiama?","why":"Un nome lungo e insolito: chiedi di ripetere."},{"label":"c","text":"Zu Kleidung kann man auch «Klamotten» sagen. → ___","gaps":[["4"]],"solution":"Zu Kleidung kann man auch «Klamotten» sagen. → **4**","en":"Per i vestiti si può dire anche “Klamotten”. → 4 Questa parola non l'ho mai sentita.","why":"Una parola nuova (colloquiale): *Das Wort habe ich noch nie gehört.*"},{"label":"d","text":"Was bedeutet dieses Wort? → ___","gaps":[["1"]],"solution":"Was bedeutet dieses Wort? → **1**","en":"Che cosa significa questa parola? → 1 Purtroppo non lo so neanch'io.","why":"Una risposta a una domanda a cui non sai rispondere."},{"label":"e","text":"Da habe ich echt Schwein gehabt. → ___","gaps":[["6"]],"solution":"Da habe ich echt Schwein gehabt. → **6**","en":"Lì ho avuto proprio fortuna. → 6 Ho capito bene: ha avuto fortuna?","why":"*Schwein haben* (colloquiale) = avere fortuna; verifichi di aver capito."},{"label":"f","text":"Könnten Sie bitte langsamer sprechen? → ___","gaps":[["3"]],"solution":"Könnten Sie bitte langsamer sprechen? → **3**","en":"Potrebbe parlare più lentamente, per favore? → 3 Va bene, ci provo.","why":"Una risposta a una richiesta."}],"phrases":["1 Das weiss ich leider auch nicht.","2 Natürlich, gern.","3 Okay, ich versuche es.","4 Das Wort habe ich noch nie gehört.","5 Wie war bitte Ihr Name?","6 Habe ich das richtig verstanden: Du hattest Glück?"]},{"no":"8","instruction":"Schreiben Sie die Fragen.","instruction_en":"Scrivi le domande indirette con le parole tra parentesi. Nella domanda indiretta il verbo va alla fine.","example":[{"label":"a","lead":"(Bild: Ein Mann und eine Frau lesen zusammen in einem Buch.) Weisst du vielleicht, … (Aufgabe – wie?)","text":"Weisst du vielleicht, **wie ich diese Aufgaben machen muss**?"}],"items":[{"label":"b","lead":"(Bild: Zwei Männer stehen mit ihren Mülltonnen auf der Strasse.) Können Sie mir sagen, … (Müll – wohin?)","text":"Können Sie mir sagen, ___?","gaps":[["wohin ich den Müll bringen muss","wohin ich den Müll bringen soll"]],"solution":"Können Sie mir sagen, **wohin ich den Müll bringen muss**?","en":"Può dirmi dove devo portare la spazzatura?","why":"*wohin* introduce la domanda indiretta; il verbo coniugato *muss* va alla fine."},{"label":"c","lead":"(Bild: Eine Frau sitzt beim Arzt.) Können Sie mir bitte sagen, … (Schmerzen – wo?)","text":"Können Sie mir bitte sagen, ___?","gaps":[["wo Sie Schmerzen haben"]],"solution":"Können Sie mir bitte sagen, **wo Sie Schmerzen haben**?","en":"Può dirmi, per favore, dove sente dolore?","why":"Il medico chiede: *wo* + soggetto + verbo alla fine (*haben*)."},{"label":"d","lead":"(Bild: Eine Frau fragt einen Mann im Zug.) Wissen Sie vielleicht, … (Zug nach Berlin – ob?)","text":"Wissen Sie vielleicht, ___?","gaps":[["ob der Zug nach Berlin fährt","ob dieser Zug nach Berlin fährt","ob das der Zug nach Berlin ist"]],"solution":"Wissen Sie vielleicht, **ob der Zug nach Berlin fährt**?","en":"Sa per caso se il treno va a Berlino?","why":"Una domanda sì/no diventa indiretta con *ob*; il verbo *fährt* va alla fine."}]}]},{"page":"Test L4 · 23","heading":"Schreiben","heading_en":"Scrittura","exercises":[{"no":"9","instruction":"Wählen Sie eine Sprache, die Sie gern lernen würden, und schreiben Sie eine Nachricht an die Sprachschule. – Schreiben Sie, für welche Sprache Sie sich interessieren. – Sagen Sie, wann und wie oft pro Woche Sie Zeit für den Kurs haben. – Fragen Sie, zu welchen Terminen/Zeiten die Sprachschule einen Kurs in Ihrer Wunschsprache anbietet. – Fragen Sie auch nach den Kursgebühren und der Kursdauer. – Bitten Sie um eine Antwort. – Denken Sie an die passende Anrede und den Gruss am Ende.","instruction_en":"Scegli una lingua che ti piacerebbe imparare e scrivi un messaggio alla scuola di lingue: quale lingua, quando e quante volte alla settimana hai tempo, quali date e orari offrono per il corso, il costo e la durata del corso; chiedi una risposta e usa un saluto iniziale e finale adatti. La risposta modello segue la soluzione ufficiale.","phrases":["… Damen und Herren,","ich würde gern …","Ich … und …","Bitte teilen Sie mir mit, …","Auch müsste ich wissen, …","Mit …","**LERNTIPP** Was sagt man in dieser Situation? Notieren und lernen Sie nicht nur einzelne neue Wörter. Wenn Sie sich zu verschiedenen Situationen passende Sätze und Ausdrücke aufschreiben, fühlen Sie sich in Gesprächen sicherer. Benutzen Sie zum Beispiel Karteikärtchen und schreiben Sie eine Situation oder ein Thema auf die Vorderseite: «nachfragen». Schreiben Sie Beispiele zum Thema auf die Rückseite und lernen Sie diese auswendig: «Was meinen Sie mit …?», «Was bedeutet …?» … Diese Methode eignet sich auch gut, wenn Sie sich auf ein Gespräch vorbereiten möchten. Überlegen Sie, was Sie sagen oder fragen möchten und was der Gesprächspartner sagen oder fragen könnte. Sicher können Sie während des Gesprächs einen Ihrer geübten Sätze anwenden."],"items":[{"label":"9","text":"","open":true,"solution":"**Sehr geehrte** Damen und Herren, ich würde gern **Neugriechisch lernen**. Ich **habe von Montag bis Donnerstag abends Zeit** und **könnte zweimal pro Woche kommen**. Bitte teilen Sie mir mit, **zu welchen Zeiten Sie einen Neugriechisch-Kurs anbieten**. Auch müsste ich wissen, **wie viel der Kurs kostet und wie lange er dauert**. **Ich bitte Sie um eine kurze Antwort.** Mit **freundlichen Grüssen** …","en":"Gentili signore e signori, vorrei imparare il greco moderno. Ho tempo dal lunedì al giovedì di sera e potrei venire due volte alla settimana. Vi prego di comunicarmi in quali orari offrite un corso di greco moderno. Avrei anche bisogno di sapere quanto costa il corso e quanto dura. Vi chiedo una breve risposta. Cordiali saluti …","why":"Lettera formale: *Sehr geehrte Damen und Herren* … *Mit freundlichen Grüssen*. Le domande sono indirette (*zu welchen Zeiten …, wie viel …, wie lange …*): verbo alla fine."}]}]}]},{"id":"04-zu-infinitiv-bewerbung","no":4,"title":"Infinitiv mit zu · Bewerbung · Test Lektion 5","title_en":"Infinito con zu, la lettera di candidatura, chiacchiere sul lavoro · Test della lezione 5","added":"2026-11-12","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 5","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (soluzioni ufficiali, Lektion 5)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g98","title":"grammis: Verben mit einem Infinitiv mit oder ohne zu (verbi modali senza zu; brauchen con zu)","url":"https://grammis.ids-mannheim.de/fragen/98"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (frasi infinitive con zu)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"g4069","title":"grammis: Verbflexion (zu tra la particella e il verbo: anzurufen)","url":"https://grammis.ids-mannheim.de/progr@mm/4069"},{"id":"g6393","title":"grammis: Alternation von zu- und dass-Komplementen (frase con dass o zu + infinito)","url":"https://grammis.ids-mannheim.de/korpusgrammatik/6393"},{"id":"g299310","title":"grammis: während (Präposition, con il genitivo)","url":"https://grammis.ids-mannheim.de/praepositionen/299310"},{"id":"prep","title":"grammis: Präpositionalphrase (le preposizioni e i casi che reggono)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"}],"pages":[{"page":"AB 140","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Comincia finalmente a scrivere candidature!","exercises":[{"no":"1","tag":"A1","instruction":"Ich habe leider keine Zeit …","instruction_en":"Purtroppo non ho tempo …","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Completa ogni frase con un verbo del riquadro. Ognuno si usa una volta; quello barrato è usato nell'esempio.","box":["mitzuarbeiten","auszuschalten","zu erklären","mitzukommen","zu sein","zu gehen"],"box_used":[5],"box_exact":true,"example":[{"label":"1","text":"Erlaubst du uns, ins Kino **zu gehen**?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd ___.","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, den Herd **auszuschalten**.","en":"Per favore non dimenticate di spegnere il fornello.","why":"*ausschalten* è separabile, quindi *zu* va tra la particella e il verbo: *aus**zu**schalten*.","source":"g4069"},{"label":"3","text":"Ich habe Angst, nachts allein ___.","gaps":[["zu sein"]],"solution":"Ich habe Angst, nachts allein **zu sein**.","en":"Ho paura di stare da solo di notte.","why":"*Angst haben* + *zu* + infinito; *sein* è un verbo semplice, quindi *zu* sta davanti.","source":"g6865"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein ___.","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein **mitzuarbeiten**.","en":"No, non è troppo stressante collaborare in un'associazione.","why":"*Es ist* + aggettivo + *zu* + infinito. *mitarbeiten* è separabile: *mit**zu**arbeiten*. (Qui il primo *zu* significa \"troppo\".)","source":"g4069"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg ___.","gaps":[["zu erklären"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg **zu erklären**.","en":"Purtroppo non ho tempo di spiegarLe la strada.","why":"*keine Zeit haben* + *zu* + infinito. *erklären* non è separabile (*er-* è un prefisso inseparabile), quindi *zu* sta davanti.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, ins Training ___.","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, ins Training **mitzukommen**.","en":"Oggi non ho voglia di venire all'allenamento.","why":"*keine Lust haben* + *zu* + infinito; *mitkommen* è separabile: *mit**zu**kommen*.","source":"g4069"}]},{"no":"1","part":"b","part_instruction":"Nach welchen Ausdrücken folgt *zu*? Markieren Sie in a wie im Beispiel.","part_instruction_en":"Quali espressioni sono seguite da *zu*? Scrivi l'espressione (il verbo o verbo + sostantivo/aggettivo) che richiede *zu* in ogni frase di a.","example":[{"label":"1","text":"**Erlaubst** du uns, ins Kino zu gehen?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd auszuschalten. → ___","gaps":[["Vergesst","Vergesst bitte nicht","vergessen","vergesst nicht"]],"solution":"Vergesst bitte nicht, den Herd auszuschalten. → **Vergesst**","en":"Per favore non dimenticate di spegnere il fornello. → dimenticare","why":"Il verbo *vergessen* (qui *Vergesst*) è seguito da *zu* + infinito.","source":"hueber"},{"label":"3","text":"Ich habe Angst, nachts allein zu sein. → ___","gaps":[["habe Angst","Angst haben","Ich habe Angst","Angst"]],"solution":"Ich habe Angst, nachts allein zu sein. → **habe Angst**","en":"Ho paura di stare da solo di notte. → avere paura","why":"*haben* + sostantivo (*Angst, Lust, Zeit, Interesse*) è seguito da *zu* + infinito.","source":"hueber"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → ___","gaps":[["ist nicht zu stressig","es ist nicht zu stressig","ist stressig","stressig sein","es ist stressig","stressig"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → **ist nicht zu stressig**","en":"No, non è troppo stressante collaborare in un'associazione. → è (non troppo) stressante","why":"*Es ist* + aggettivo è seguito da *zu* + infinito.","source":"hueber"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → ___","gaps":[["habe leider keine Zeit","habe keine Zeit","keine Zeit haben","Zeit haben","keine Zeit","Zeit"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → **habe leider keine Zeit**","en":"Purtroppo non ho tempo di spiegarLe la strada. → (non) avere tempo","why":"*Zeit haben* (qui *keine Zeit*) è seguito da *zu* + infinito.","source":"hueber"},{"label":"6","text":"Ich habe heute keine Lust, ins Training mitzukommen. → ___","gaps":[["habe heute keine Lust","habe keine Lust","keine Lust haben","Lust haben","keine Lust","Lust"]],"solution":"Ich habe heute keine Lust, ins Training mitzukommen. → **habe heute keine Lust**","en":"Oggi non ho voglia di venire all'allenamento. → (non) avere voglia","why":"*Lust haben* (qui *keine Lust*) è seguito da *zu* + infinito.","source":"hueber"}]},{"no":"1","part":"c","part_instruction":"Wo steht *zu*? Ergänzen Sie die Tabelle mit den Sätzen aus a.","part_instruction_en":"Dove va *zu*? La tabella ha tre colonne: l'inizio della frase, la parte centrale, poi il verbo con *zu*. Inserisci le frasi di a con un verbo separabile (2, 4, 6) e scrivi l'ultima colonna. Le parti del verbo sono tra parentesi.","example":[{"label":"1","text":"Erlaubst du uns, | ins Kino | **zu gehen**? (gehen)"}],"items":[{"label":"2","text":"Vergesst bitte nicht, | den Herd | ___. (aus·schalten)","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, | den Herd | **auszuschalten**. (aus·schalten)","en":"Per favore non dimenticate | il fornello | di spegnere.","why":"Verbo separabile: *zu* va tra *aus* e *schalten*, e si scrive tutto attaccato.","source":"g4069"},{"label":"4","text":"Nein, es ist nicht zu stressig, | in einem Verein | ___. (mit·arbeiten)","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, | in einem Verein | **mitzuarbeiten**. (mit·arbeiten)","en":"No, non è troppo stressante | in un'associazione | collaborare.","why":"Verbo separabile: *mit* + *zu* + *arbeiten*, scritto come una sola parola.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, | ins Training | ___. (mit·kommen)","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, | ins Training | **mitzukommen**. (mit·kommen)","en":"Oggi non ho voglia | all'allenamento | di venire.","why":"Verbo separabile: *mit* + *zu* + *kommen*, scritto come una sola parola.","source":"g4069"}]},{"no":"2","tag":"A1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Che cosa è giusto? Scrivi *zu* se la frase ha bisogno di *zu*, oppure *–* (un trattino) se non serve niente.","example":[{"label":"a","text":"Ich höre nicht auf, nach meinem Traumjob **zu** suchen."}],"items":[{"label":"b","text":"Möchten Sie nicht auch in Ihrem Traumberuf ___ arbeiten?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Möchten Sie nicht auch in Ihrem Traumberuf **–** arbeiten?","en":"Non Le piacerebbe lavorare anche Lei nella professione dei Suoi sogni?","why":"Dopo un verbo modale (*möchten*) l'infinito non prende mai *zu*.","source":"g98"},{"label":"c","text":"Ich könnte mir gut vorstellen, ein Handwerk ___ lernen.","gaps":[["zu"]],"solution":"Ich könnte mir gut vorstellen, ein Handwerk **zu** lernen.","en":"Potrei benissimo immaginare di imparare un mestiere.","why":"*sich vorstellen können* introduce una seconda frase dopo la virgola, con *zu* + infinito. *könnte* si riferisce solo a *vorstellen*.","source":"g6865"},{"label":"d","text":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz ___ finden.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz **–** finden.","en":"Con una formazione da artigiano si può trovare un buon posto di lavoro.","why":"Verbo modale *kann* + infinito senza *zu*.","source":"g98"},{"label":"e","text":"Könnten Sie mir bei der Berufswahl ___ helfen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Könnten Sie mir bei der Berufswahl **–** helfen?","en":"Potrebbe aiutarmi a scegliere una professione?","why":"*Könnten* è un verbo modale (Konjunktiv II di *können*): niente *zu*.","source":"g98"},{"label":"f","text":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten ___ informieren.","gaps":[["zu"]],"solution":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten **zu** informieren.","en":"È piuttosto stressante informarsi sulle possibilità professionali.","why":"*Es ist* + aggettivo (*stressig*) + *zu* + infinito.","source":"g6865"}]},{"no":"3","tag":"A1","marker":"◇","instruction":"Ergänzen Sie: *zu* oder *–*.","instruction_en":"Completa con *zu*, oppure scrivi *–* (un trattino) dove non manca niente.","example":[{"label":"a","text":"Ich habe schon einmal angefangen, das Bewerbungsgespräch vor**zu**bereiten."}],"items":[{"label":"b","text":"Wir dürfen den Geburtstag der Chefin nicht ___ vergessen!","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Wir dürfen den Geburtstag der Chefin nicht **–** vergessen!","en":"Non dobbiamo dimenticare il compleanno della capa!","why":"Verbo modale *dürfen* + infinito senza *zu*.","source":"g98"},{"label":"c","text":"Es ist nicht leicht, eine Stelle in seinem Traumjob ___ finden.","gaps":[["zu"]],"solution":"Es ist nicht leicht, eine Stelle in seinem Traumjob **zu** finden.","en":"Non è facile trovare un posto nel lavoro dei propri sogni.","why":"*Es ist nicht leicht* + *zu* + infinito.","source":"g6865"},{"label":"d","text":"Ich würde am liebsten in einem Team ___ arbeiten.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Ich würde am liebsten in einem Team **–** arbeiten.","en":"Più di tutto mi piacerebbe lavorare in un team.","why":"*würde* + infinito (Konjunktiv II) funziona come un verbo modale: niente *zu*.","source":"g98"},{"label":"e","text":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung ___ helfen?","gaps":[["zu"]],"solution":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung **zu** helfen?","en":"Hai un attimo di tempo per aiutarmi con la mia candidatura?","why":"*Zeit haben* + *zu* + infinito.","source":"g6865"},{"label":"f","text":"Kannst du dir eine Lehre im Büro vor ___ stellen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Kannst du dir eine Lehre im Büro vor **–** stellen?","en":"Riesci a immaginarti un apprendistato in ufficio?","why":"*Kannst* è un verbo modale, quindi non si inserisce niente: *vorstellen* si scrive come una sola parola.","source":"g98"}]}]},{"page":"AB 141","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Comincia finalmente a scrivere candidature!","exercises":[{"no":"4","instruction":"Schreiben Sie Sätze.","instruction_en":"Scrivi frasi sulla tua vita professionale: combina un'espressione del riquadro di sinistra con un'attività del riquadro di destra. Le parole barrate sono usate nell'esempio. La risposta modello è una possibilità.","box":["(keine) Lust haben","möchten","hoffen","Freude machen","können","sich vorstellen können","würde … gern","anstrengend sein","…","ein halbes Jahr um die Welt reisen","am Abend arbeiten","(nicht) immer dasselbe machen","sehr gut selbstständig arbeiten","mit netten Kollegen zusammenarbeiten","Neues lernen","wenig Freizeit haben"],"box_used":[0,1,10],"example":[{"label":"Beispiel","text":"Ich habe keine Lust, am Abend **zu arbeiten**. Ich möchte in meinem Berufsleben …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich möchte in meinem Berufsleben nicht immer dasselbe machen. Ich hoffe, mit netten Kollegen zusammenzuarbeiten. Es macht mir Freude, Neues zu lernen. Ich kann sehr gut selbstständig arbeiten. Es ist anstrengend, wenig Freizeit zu haben. Ich würde gern ein halbes Jahr um die Welt reisen.","en":"Nella mia vita professionale non voglio fare sempre la stessa cosa. Spero di lavorare con colleghi simpatici. Mi fa piacere imparare cose nuove. So lavorare molto bene in autonomia. È faticoso avere poco tempo libero. Mi piacerebbe viaggiare per il mondo per sei mesi.","why":"Dopo *hoffen, Freude machen, sich vorstellen können, anstrengend sein, Lust haben* usa *zu* + infinito (verbi separabili: *zusammen**zu**arbeiten*). Dopo *möchten, können, würde … gern* niente *zu*.","source":"g98"}]},{"no":"5","instruction":"Ordnen Sie zu und schreiben Sie Sätze mit *zu*.","instruction_en":"Abbina ogni affermazione a un verbo del riquadro e scrivi una frase con *zu* + infinito. Il verbo barrato è usato nell'esempio.","box":["sich vorstellen können","versuchen","aufhören","versprechen","vorhaben"],"box_used":[1],"example":[{"label":"a","lead":"Morgen will ich pünktlich sein. Vielleicht!","text":"versuchen: Morgen versuche ich, pünktlich **zu sein**."}],"items":[{"label":"b","lead":"Ich hole dich morgen ab. Ganz sicher.","text":"","accept":["Ich verspreche, dich morgen abzuholen.","Ich verspreche dir, dich morgen abzuholen.","versprechen: Ich verspreche, dich morgen abzuholen."],"solution":"**Ich verspreche, dich morgen abzuholen.**","en":"Prometto di venirti a prendere domani.","why":"\"Sicuramente\" = una promessa: *versprechen*. *abholen* è separabile: *ab**zu**holen*.","source":"hueber"},{"label":"c","lead":"Einen interessanten Job finden! Das ist mein Plan.","text":"","accept":["Ich habe vor, einen interessanten Job zu finden.","vorhaben: Ich habe vor, einen interessanten Job zu finden."],"solution":"**Ich habe vor, einen interessanten Job zu finden.**","en":"Ho intenzione di trovare un lavoro interessante.","why":"Un progetto = *vorhaben*: *Ich habe vor, … zu finden.* La particella *vor* va alla fine della frase principale.","source":"hueber"},{"label":"d","lead":"Ein Handwerk lernen? Ja, warum eigentlich nicht?","text":"","accept":["Ich kann mir vorstellen, ein Handwerk zu lernen.","Ich kann mir gut vorstellen, ein Handwerk zu lernen.","sich vorstellen können: Ich kann mir vorstellen, ein Handwerk zu lernen."],"solution":"**Ich kann mir vorstellen, ein Handwerk zu lernen.**","en":"Riesco a immaginarmi di imparare un mestiere.","why":"\"Perché no?\" = riesci a immaginarlo: *Ich kann mir vorstellen, … zu lernen.*","source":"hueber"},{"label":"e","lead":"Ich arbeite als Pflegefachmann. Aber nur noch bis Ende Monat.","text":"","accept":["Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.","Ende Monat höre ich auf, als Pflegefachmann zu arbeiten.","aufhören: Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten."],"solution":"**Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.**","en":"A fine mese smetto di lavorare come infermiere.","why":"\"Solo fino a fine mese\" = smettere: *aufhören*, con *auf* alla fine della frase principale, prima della virgola.","source":"hueber"}]},{"no":"6","instruction":"Markieren Sie noch neun Wörter und ordnen Sie zu.","instruction_en":"Trova altre nove parole nella griglia di lettere e inseriscile negli annunci di lavoro A–C. Le parole cerchiate (*Bewerbung, Tätigkeit*) sono gli esempi. Scrivi ogni parola nella forma richiesta dalla frase (iniziale maiuscola per i sostantivi).","reading":[{"label":"Buchstabengitter","text":"AUFGABENSGBESCHÄFTIGSTIBEWERBUNGTERWARTENZTÄTIGKEIT\nBEWERBUNGSUNTERLAGENZYTWHANDELUTPOÜKENNTNISSENKWAQ\nUNTERSTÜTZUNGMUSJÄMTILVORAUSSETZUNGDUQSCHRIFTLICHLW"},{"label":"A  Heimpflegedienst Bachmann","text":"Wir suchen für 15 Stunden pro Woche … (1) für den Patientenfahrdienst.\n… (2) für die Tätigkeit ist: + Führerausweis Kategorie B + … (3) in Erster Hilfe + Freude an der Arbeit mit Menschen\nEs … (4) Sie: + interessante … (5) + Weiterbildungsmöglichkeiten + ein angenehmes Betriebsklima\nBitte schicken Sie Ihre Bewerbung an personal@hpfd-bachmann.ch"},{"label":"B","text":"Detailhandelsassistent/in für unser kleines Modegeschäft gesucht!\nErfahrung im … (1) und Verkauf von Vorteil. Wenden Sie sich bei Fragen … (2) oder telefonisch an Frau Kleinert: kleinert@neuemode.ch / 031 330 110 10."},{"label":"C","text":"HAST DU HANDWERKLICHES TALENT?\n… (1) du dich gern mit Holz? Dann komm zu uns! Wir bieten dir eine Lehrstelle als Schreiner/in EFZ.\nSchick deine … (2) noch heute an: Clemens Meier (cl.meier@schreinerei-meier.ch)"}],"example":[{"label":"A","text":"… für die **Tätigkeit** ist: … Bitte schicken Sie Ihre **Bewerbung** an personal@hpfd-bachmann.ch"}],"items":[{"label":"A1","text":"Wir suchen für 15 Stunden pro Woche ___ für den Patientenfahrdienst.","gaps":[["Unterstützung"]],"solution":"Wir suchen für 15 Stunden pro Woche **Unterstützung** für den Patientenfahrdienst.","en":"Cerchiamo un aiuto per il servizio di trasporto pazienti, 15 ore alla settimana.","why":"*die Unterstützung* = sostegno, aiuto; qui indica una persona che aiuta.","source":"hueber"},{"label":"A2","text":"___ für die Tätigkeit ist: Führerausweis Kategorie B","gaps":[["Voraussetzung"]],"solution":"**Voraussetzung** für die Tätigkeit ist: Führerausweis Kategorie B","en":"Requisito per l'attività: patente di guida categoria B","why":"*die Voraussetzung* = requisito, condizione. *der Führerausweis* è la parola svizzera per patente di guida.","source":"hueber"},{"label":"A3","text":"+ ___ in Erster Hilfe","gaps":[["Kenntnisse"]],"solution":"+ **Kenntnisse** in Erster Hilfe","en":"+ conoscenze di primo soccorso","why":"*Kenntnisse in* + dativo = conoscenze di / competenze in.","source":"hueber"},{"label":"A4","text":"Es ___ Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","gaps":[["erwarten"]],"solution":"Es **erwarten** Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","en":"La attendono: compiti interessanti, possibilità di formazione continua, un piacevole clima aziendale","why":"*Es erwarten Sie …* = \"La attendono …\"; *es* occupa solo la posizione 1, il verbo concorda con il soggetto plurale che segue.","source":"hueber"},{"label":"A5","text":"+ interessante ___","gaps":[["Aufgaben"]],"solution":"+ interessante **Aufgaben**","en":"+ compiti interessanti","why":"*die Aufgabe, die Aufgaben* = compito, compiti; *interessante* indica un plurale.","source":"hueber"},{"label":"B1","text":"Erfahrung im ___ und Verkauf von Vorteil.","gaps":[["Handel"]],"solution":"Erfahrung im **Handel** und Verkauf von Vorteil.","en":"Esperienza nel commercio e nella vendita costituisce un vantaggio.","why":"*der Handel* = commercio; *im* = *in dem*. *von Vorteil* = un vantaggio.","source":"hueber"},{"label":"B2","text":"Wenden Sie sich bei Fragen ___ oder telefonisch an Frau Kleinert.","gaps":[["schriftlich"]],"solution":"Wenden Sie sich bei Fragen **schriftlich** oder telefonisch an Frau Kleinert.","en":"Per domande si rivolga per iscritto o per telefono alla signora Kleinert.","why":"*schriftlich oder telefonisch* = per iscritto o per telefono.","source":"hueber"},{"label":"C1","text":"___ du dich gern mit Holz?","gaps":[["Beschäftigst"]],"solution":"**Beschäftigst** du dich gern mit Holz?","en":"Ti piace lavorare con il legno?","why":"*sich beschäftigen mit* = occuparsi di; *du beschäftigst dich*. Apre la domanda sì/no, quindi ha l'iniziale maiuscola.","source":"hueber"},{"label":"C2","text":"Schick deine ___ noch heute an: Clemens Meier","gaps":[["Bewerbungsunterlagen"]],"solution":"Schick deine **Bewerbungsunterlagen** noch heute an: Clemens Meier","en":"Manda oggi stesso i tuoi documenti di candidatura a: Clemens Meier","why":"*die Bewerbungsunterlagen* (plurale) = curriculum, certificati e lettera insieme.","source":"hueber"}]}]},{"page":"AB 142","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Comincia finalmente a scrivere candidature!","exercises":[{"no":"7","tag":"A2","instruction":"Ergänzen Sie in der richtigen Form: *brauchen – müssen*.","instruction_en":"Completa con la forma giusta di *brauchen* o *müssen*. Consiglio: *brauchen* va con *zu* + infinito e con una negazione o *nur*; *müssen* non vuole mai *zu*.","example":[{"label":"a","text":"Ich **brauche** nur die neuen Wörter zu lernen, dann schaffe ich die Prüfung schon."}],"items":[{"label":"b","text":"Dein Zeugnis ist doch so gut. Du ___ dir wirklich keine Gedanken um einen Job zu machen.","gaps":[["brauchst"]],"solution":"Dein Zeugnis ist doch so gut. Du **brauchst** dir wirklich keine Gedanken um einen Job zu machen.","en":"La tua pagella è così buona. Non devi davvero preoccuparti per un lavoro.","why":"Negazione (*keine*) + *zu machen*: *brauchen … zu* = *nicht müssen*.","source":"g98"},{"label":"c","text":"Wenn sie nur Teilzeit arbeitet, dann ___ sie nicht den ganzen Tag am Computer sitzen.","gaps":[["muss"]],"solution":"Wenn sie nur Teilzeit arbeitet, dann **muss** sie nicht den ganzen Tag am Computer sitzen.","en":"Se lavora solo a tempo parziale, non deve stare seduta al computer tutto il giorno.","why":"L'infinito *sitzen* non ha *zu*, quindi il verbo è *müssen*: *sie muss … sitzen*.","source":"g98"},{"label":"d","text":"Wenn wir für drei Monate ins Ausland reisen wollen, dann ___ wir jetzt viel Geld sparen.","gaps":[["müssen"]],"solution":"Wenn wir für drei Monate ins Ausland reisen wollen, dann **müssen** wir jetzt viel Geld sparen.","en":"Se vogliamo viaggiare all'estero per tre mesi, adesso dobbiamo risparmiare molti soldi.","why":"Niente *zu* e nessuna negazione: è un obbligo, quindi *müssen*.","source":"g98"}]},{"no":"8","tag":"A2","instruction":"Mein Traumjob. Schreiben Sie Sätze mit *brauchen … zu*.","instruction_en":"Il lavoro dei miei sogni. Scrivi frasi con *brauchen … zu* + infinito (= non dover / dover solo).","example":[{"label":"a","lead":"(nicht früh aufstehen)","text":"In meinem Traumjob **brauche ich nicht früh aufzustehen**."}],"items":[{"label":"b","lead":"(keine langweiligen Aufgaben übernehmen)","text":"","accept":["Ich brauche keine langweiligen Aufgaben zu übernehmen.","In meinem Traumjob brauche ich keine langweiligen Aufgaben zu übernehmen."],"solution":"**Ich brauche keine langweiligen Aufgaben zu übernehmen.**","en":"Non devo assumermi compiti noiosi.","why":"*brauchen* in seconda posizione, *zu übernehmen* alla fine. Qui *übernehmen* non è separabile, quindi *zu* sta davanti.","source":"g98"},{"label":"c","lead":"(keine Überstunden machen)","text":"","accept":["Ich brauche keine Überstunden zu machen.","In meinem Traumjob brauche ich keine Überstunden zu machen."],"solution":"**Ich brauche keine Überstunden zu machen.**","en":"Non devo fare straordinari.","why":"*keine* + *brauchen … zu* = nessun obbligo.","source":"g98"},{"label":"d","lead":"(nur arbeiten, wenn ich Lust dazu habe)","text":"","accept":["Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.","In meinem Traumjob brauche ich nur zu arbeiten, wenn ich Lust dazu habe."],"solution":"**Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.**","en":"Devo lavorare solo quando ne ho voglia.","why":"*nur brauchen … zu* = dover solo. *zu arbeiten* chiude la frase principale prima della frase con *wenn*.","source":"g98"},{"label":"e","lead":"(nicht mit unfreundlichen Kollegen zusammenarbeiten)","text":"","accept":["Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.","In meinem Traumjob brauche ich nicht mit unfreundlichen Kollegen zusammenzuarbeiten."],"solution":"**Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.**","en":"Non devo lavorare con colleghi antipatici.","why":"*zusammenarbeiten* è separabile: *zusammen**zu**arbeiten*, una sola parola.","source":"g4069"}]},{"no":"9","tag":"A4","instruction":"Ein Bewerbungsschreiben","instruction_en":"Una lettera di candidatura","part":"a","part_instruction":"Lesen Sie und ordnen Sie.","part_instruction_en":"Leggi le parti della lettera e mettile nell'ordine giusto: scrivi il numero (1–8) di ogni parte. Qui le parti sono contrassegnate con le lettere A–H nell'ordine in cui le stampa il libro; B è l'esempio.","example":[{"label":"B","text":"Bewerbung als Verkäufer von E-Bikes → **1**"}],"items":[{"label":"A","text":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → ___","gaps":[["5"]],"solution":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → **5**","en":"Imparo facilmente cose nuove. Inoltre mi piace consigliare i clienti. Per questo mi piacerebbe lavorare come venditore nella Sua azienda. → 5","why":"Il motivo per cui vuoi il posto viene dopo la tua esperienza (4) e prima della richiesta finale (6).","source":"hueber"},{"label":"C","text":"Freundliche Grüsse / Tibor Kelemen → ___","gaps":[["7"]],"solution":"Freundliche Grüsse / Tibor Kelemen → **7**","en":"Cordiali saluti / Tibor Kelemen → 7","why":"Il saluto finale e il tuo nome vengono dopo l'ultima frase.","source":"hueber"},{"label":"D","text":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → ___","gaps":[["3"]],"solution":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → **3**","en":"Ho letto con grande interesse il Suo annuncio e mi candido per il posto vacante di venditore di e-bike. → 3","why":"La prima frase dopo il saluto iniziale dice per quale posto ti candidi.","source":"hueber"},{"label":"E","text":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → ___","gaps":[["6"]],"solution":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → **6**","en":"Sarei lieto di essere invitato a un colloquio personale. → 6","why":"La frase finale classica di una lettera di candidatura.","source":"hueber"},{"label":"F","text":"Beilagen: Lebenslauf, Arbeitszeugnisse → ___","gaps":[["8"]],"solution":"Beilagen: Lebenslauf, Arbeitszeugnisse → **8**","en":"Allegati: curriculum vitae, certificati di lavoro → 8","why":"Gli allegati (*Beilagen*) vengono proprio alla fine, sotto il nome.","source":"hueber"},{"label":"G","text":"Sehr geehrte Damen und Herren → ___","gaps":[["2"]],"solution":"Sehr geehrte Damen und Herren → **2**","en":"Gentili signore e signori → 2","why":"Il saluto iniziale segue la riga dell'oggetto. In Svizzera dopo il saluto non si mette la virgola.","source":"hueber"},{"label":"H","text":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → ___","gaps":[["4"]],"solution":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → **4**","en":"Come può vedere dai miei documenti, dopo il diploma di scuola secondaria ho fatto la formazione da meccanico di biciclette presso la ditta «Velo-XL». Poi ho lavorato per due anni come dipendente in un negozio di bici e ho potuto fare anche le prime esperienze nella vendita. → 4","why":"La tua formazione e la tua esperienza vengono dopo la frase d'apertura.","source":"hueber"}]}]},{"page":"AB 143","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Comincia finalmente a scrivere candidature!","exercises":[{"no":"9","part":"b","part_instruction":"Ergänzen Sie das Bewerbungsschreiben. Hilfe finden Sie in a.","part_instruction_en":"Completa la lettera di candidatura. Trovi un aiuto in a.","reading":[{"label":"Lerntipp","text":"Ein Bewerbungsschreiben muss fehlerfrei sein! Notieren Sie zuerst Ihre typischen Fehler. Überprüfen Sie dann Ihren Text pro Fehlertyp einmal. Lassen Sie Ihre Bewerbung am Ende noch einmal von einem Muttersprachler Korrektur lesen."}],"example":[{"label":"1","text":"Bewerbung **als** Physiotherapeutin im Altersheim"}],"items":[{"label":"2","text":"Sehr ___ Frau Zerlich","gaps":[["geehrte"]],"solution":"Sehr **geehrte** Frau Zerlich","en":"Gentile signora Zerlich","why":"*Sehr geehrte Frau …*, *Sehr geehrter Herr …*: la desinenza dipende dalla persona.","source":"hueber"},{"label":"3","text":"___ habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","gaps":[["Mit grossem Interesse"]],"solution":"**Mit grossem Interesse** habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","en":"Ho letto con grande interesse il Suo annuncio di lavoro e mi candido per il posto di fisioterapista.","why":"Frase d'apertura fissa di a; occupa la posizione 1, quindi segue il verbo *habe*.","source":"hueber"},{"label":"4","text":"Wie Sie ___ entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","gaps":[["meinen Unterlagen"]],"solution":"Wie Sie **meinen Unterlagen** entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","en":"Come può vedere dai miei documenti, in Polonia, dopo la mia formazione da fisioterapista, ho lavorato quattro anni in un ospedale di Lodz.","why":"*etwas (Dativ) entnehmen* = ricavare da qualcosa: *meinen Unterlagen* è dativo plurale.","source":"hueber"},{"label":"5","text":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch ___ im Bereich der Sportmedizin sammeln.","gaps":[["Erfahrungen","erste Erfahrungen"]],"solution":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch **Erfahrungen** im Bereich der Sportmedizin sammeln.","en":"Poi ho lavorato due anni nello studio Kunz & Rosenthal. Lì ho potuto fare esperienza anche nel campo della medicina dello sport.","why":"*Erfahrungen sammeln* = fare esperienza.","source":"hueber"},{"label":"6","text":"___ ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","gaps":[["Meine Muttersprache"]],"solution":"**Meine Muttersprache** ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","en":"La mia lingua madre è il polacco. Ma parlo anche molto bene tedesco e inglese.","why":"*die Muttersprache* = lingua madre; *meine* perché è femminile.","source":"hueber"},{"label":"7","text":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es ___ grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","gaps":[["macht mir"]],"solution":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es **macht mir** grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","en":"Il posto in una casa per anziani è per me qualcosa di completamente nuovo. Mi fa molto piacere imparare cose nuove. Inoltre mi prendo volentieri cura degli altri e non vedo l'ora di entrare in contatto con i residenti.","why":"*Es macht mir Freude, … zu* + infinito, come in a.","source":"hueber"},{"label":"8","text":"Über eine Einladung ___ würde ich mich freuen.","gaps":[["zu einem persönlichen Gespräch"]],"solution":"Über eine Einladung **zu einem persönlichen Gespräch** würde ich mich freuen.","en":"Sarei lieta di essere invitata a un colloquio personale.","why":"Frase finale fissa: *eine Einladung zu* + dativo.","source":"hueber"},{"label":"9","text":"___ Alina Jankowska","gaps":[["Freundliche Grüsse"]],"solution":"**Freundliche Grüsse** Alina Jankowska","en":"Cordiali saluti, Alina Jankowska","why":"Saluto finale; ortografia svizzera *Grüsse*.","source":"hueber"}]},{"no":"9","part":"c","part_instruction":"Wählen Sie ein Stelleninserat und schreiben Sie eine Bewerbung.","part_instruction_en":"Scegli uno dei tre annunci di lavoro dello Zirkus Tortellini e scrivi una lettera di candidatura. Usa le parti di a e b. La risposta modello è una possibilità.","reading":[{"label":"1","text":"Zirkus Tortellini sucht Dompteur/-in\nWir erwarten: + Ausbildung als Tierpfleger/-in + Erfahrung mit wilden Tieren (Tiger, …)\nInfos und Bewerbung bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"2","text":"Sind Sie ein fröhlicher, positiver Mensch? Dann arbeiten Sie bei uns als Clown/-in\nSie haben Berufserfahrung als Kleinkinderzieher/-in oder als Schauspieler/-in? Sie können gut mit Kindern umgehen und haben viele lustige Ideen? Dann sind Sie die Richtige oder der Richtige für uns!\nGleich bewerben bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"3","text":"Wir suchen zwei Artisten für unseren Zirkus.\nSie haben: + eine Ausbildung als Tänzer/-in + erste Berufserfahrung an einem Theater gesammelt oder schon als Artist/-in in einem Zirkus gearbeitet\nSenden Sie Ihre Bewerbung an Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"}],"example":[{"label":"Beispiel","text":"Sehr geehrter Herr Tortellini / Mit grossem Interesse …"}],"items":[{"label":"1","lead":"Inserat 3: Artist/-in","text":"","open":true,"solution":"Bewerbung als Artistin / Sehr geehrter Herr Tortellini / Mit grossem Interesse habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Artistin in Ihrem Zirkus. Wie Sie meinen Unterlagen entnehmen können, habe ich eine Ausbildung als Tänzerin gemacht. Danach habe ich drei Jahre an einem Theater in Bern getanzt und dort erste Erfahrungen auf der Bühne gesammelt. Es macht mir grosse Freude, vor Publikum aufzutreten. Ich kann mir gut vorstellen, mit Ihrem Zirkus durch die Schweiz zu reisen. Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. / Freundliche Grüsse / Lara Steiner / Beilagen: Lebenslauf, Arbeitszeugnis","en":"Candidatura come acrobata / Egregio signor Tortellini / Ho letto con grande interesse il Suo annuncio di lavoro e mi candido per il posto di acrobata nel Suo circo. Come può vedere dai miei documenti, ho fatto una formazione da ballerina. Poi ho ballato per tre anni in un teatro di Berna e lì ho fatto le prime esperienze sul palco. Mi fa molto piacere esibirmi davanti al pubblico. Riesco benissimo a immaginarmi di viaggiare per la Svizzera con il Suo circo. Sarei lieta di essere invitata a un colloquio personale. / Cordiali saluti / Lara Steiner / Allegati: curriculum vitae, certificato di lavoro","why":"Le stesse otto parti di a; ognuna risponde a un punto dell'annuncio (formazione da ballerina, prime esperienze in un teatro). *auf**zu**treten*: *auftreten* è separabile.","source":"g4069"}]}]},{"page":"AB 144","heading":"B  Während seines letzten Schuljahres …","heading_en":"Durante il suo ultimo anno di scuola …","exercises":[{"no":"10","tag":"B1","instruction":"Ergänzen Sie in der richtigen Form: *während – innerhalb – ausserhalb*.","instruction_en":"Completa con *während* (durante), *innerhalb* (entro) o *ausserhalb* (fuori da), più la parola tra parentesi nella forma giusta. Tutte e tre reggono il genitivo.","example":[{"label":"a","text":"Man sollte schon **während der** (die) Schulzeit Schnupperlehren machen."}],"items":[{"label":"b","lead":"(wenige)","text":"Vielen Dank für Ihre Bewerbung. Sie erhalten ___ Wochen unsere Antwort.","gaps":[["innerhalb weniger"]],"solution":"Vielen Dank für Ihre Bewerbung. Sie erhalten **innerhalb weniger** Wochen unsere Antwort.","en":"Grazie mille per la Sua candidatura. Riceverà la nostra risposta entro poche settimane.","why":"Un limite di tempo = *innerhalb*; genitivo plurale senza articolo: *weniger Wochen*.","source":"prep"},{"label":"c","lead":"(unsere)","text":"Sie rufen ___ Geschäftszeiten an. Diese sind von …","gaps":[["ausserhalb unserer"]],"solution":"Sie rufen **ausserhalb unserer** Geschäftszeiten an. Diese sind von …","en":"Sta chiamando fuori dai nostri orari di apertura. Sono dalle …","why":"Fuori da un periodo di tempo = *ausserhalb*; genitivo plurale *unserer Geschäftszeiten*.","source":"prep"},{"label":"d","lead":"(die)","text":"Sie können sich ___ Wartezeit gern einen Kaffee nehmen.","gaps":[["während der"]],"solution":"Sie können sich **während der** Wartezeit gern einen Kaffee nehmen.","en":"Durante l'attesa si serva pure di un caffè.","why":"Nello stesso momento di = *während*; genitivo femminile *der Wartezeit*.","source":"g299310"},{"label":"e","lead":"(die)","text":"Die Firma möchte ihre Ergebnisse ___ nächsten zwei Jahre um 20 % verbessern.","gaps":[["innerhalb der"]],"solution":"Die Firma möchte ihre Ergebnisse **innerhalb der** nächsten zwei Jahre um 20 % verbessern.","en":"L'azienda vuole migliorare i suoi risultati del 20 % entro i prossimi due anni.","why":"Un limite di tempo = *innerhalb*; genitivo plurale *der nächsten zwei Jahre*.","source":"prep"}]},{"no":"11","tag":"B2","instruction":"Ordnen Sie zu.","instruction_en":"Completa l'intervista con le preposizioni di tempo del riquadro. Ognuna si usa una volta; *während* è nel riquadro due volte. Il *von … an* barrato è usato nell'esempio.","phrases":["ausserhalb","bei","von … bis","nach","von … an (Beispiel)","Vor","während","während"],"reading":[{"label":"Karrierestart","text":"Technikerin HF Maschinenbau – ein Beruf auch für Mädchen? Interview mit Samira\nKarrierestart: Warum machst du eine Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie lange dauert die Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie sieht dein Arbeitstag aus?\nKarrierestart: Welche Erfahrungen hast du als Frau … deiner Arbeit gemacht?"}],"example":[{"label":"d","text":"Ich durfte **von** Anfang **an** selbstständig Probleme lösen."}],"items":[{"label":"a","text":"Technik hat mich schon immer interessiert. Schon ___ meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","gaps":[["während"]],"solution":"Technik hat mich schon immer interessiert. Schon **während** meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","en":"La tecnica mi ha sempre interessato. Già durante gli anni di scuola ho lavorato presso un elettricista.","why":"*während* + genitivo (*meiner Schulzeit*) = durante.","source":"g299310"},{"label":"b","text":"Gleich ___ der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","gaps":[["nach"]],"solution":"Gleich **nach** der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","en":"Subito dopo la scuola ho fatto uno stage presso una grande azienda energetica.","why":"*nach* + dativo (*der Schule*) = dopo.","source":"prep"},{"label":"c","text":"Aber schon ___ des ersten Jahres lernt man die wichtigsten Dinge kennen.","gaps":[["während"]],"solution":"Aber schon **während** des ersten Jahres lernt man die wichtigsten Dinge kennen.","en":"Ma già durante il primo anno si imparano le cose più importanti.","why":"*während* + genitivo *des ersten Jahres*.","source":"g299310"},{"label":"e","text":"___ der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","gaps":[["Vor"]],"solution":"**Vor** der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","en":"Prima dell'esame finale devo comunque studiare ancora molto.","why":"*vor* + dativo (*der Abschlussprüfung*) = prima di; maiuscola all'inizio della frase.","source":"prep"},{"label":"f","text":"Ich bin ___ morgens ___ zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","gaps":[["von"],["bis"]],"solution":"Ich bin **von** morgens **bis** zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","en":"Dalla mattina fino alla fine della giornata lavorativa giro per l'area della nostra azienda e riparo impianti.","why":"*von … bis* = da … fino a; *bis zum Feierabend* (*zum* = *zu dem*).","source":"prep"},{"label":"g","text":"Welche Erfahrungen hast du als Frau ___ deiner Arbeit gemacht?","gaps":[["bei"]],"solution":"Welche Erfahrungen hast du als Frau **bei** deiner Arbeit gemacht?","en":"Che esperienze hai fatto come donna nel tuo lavoro?","why":"*bei* + dativo (*deiner Arbeit*) = nel corso di, durante.","source":"prep"},{"label":"h","text":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also ___ der Arbeitszeit.","gaps":[["ausserhalb"]],"solution":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also **ausserhalb** der Arbeitszeit.","en":"Solo positive! I miei colleghi e io ci troviamo spesso la sera, quindi fuori dall'orario di lavoro.","why":"*ausserhalb* + genitivo (*der Arbeitszeit*) = fuori da.","source":"prep"}]},{"no":"12","tag":"B2","instruction":"Lesen Sie den Text und schliessen Sie die Lücken 1–6. Welche Lösung (a, b oder c) passt am besten?","instruction_en":"Preparazione all'esame: leggi l'e-mail e completa gli spazi 1–6. Quale opzione (a, b o c) è la più adatta? Scrivi la parola (o la sua lettera).","reading":[{"label":"E-Mail senden","text":"Sehr (0) Herr Nemati\nVielen Dank (1) Ihre Bewerbung als Automobil-Mechatroniker. Wir freuen uns über Ihr (2) an unserer Firma und laden Sie zu einem Vorstellungsgespräch am 25. Mai um 11.30 Uhr ein. Bitte geben Sie uns (3) der nächsten Tage Bescheid, (4) Sie zu diesem Termin kommen können. Bringen Sie noch folgende (5) mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat. Für Fragen und weitere Informationen (6) wir Ihnen gern zur Verfügung.\nFreundliche Grüsse\nFranziska Leumann – Garage Leumann"}],"example":[{"label":"0","lead":"a geehrter · b lieber · c freundlicher","text":"Sehr **geehrter** Herr Nemati"}],"items":[{"label":"1","lead":"a um · b für · c bei","text":"Vielen Dank ___ Ihre Bewerbung als Automobil-Mechatroniker.","gaps":[["für","b","b für"]],"solution":"Vielen Dank **für** Ihre Bewerbung als Automobil-Mechatroniker.","en":"Grazie mille per la Sua candidatura come meccatronico d'automobili.","why":"*Vielen Dank für* + accusativo.","source":"hueber"},{"label":"2","lead":"a Bewerbung · b Interesse · c Mitarbeit","text":"Wir freuen uns über Ihr ___ an unserer Firma …","gaps":[["Interesse","b","b Interesse"]],"solution":"Wir freuen uns über Ihr **Interesse** an unserer Firma …","en":"Siamo lieti del Suo interesse per la nostra azienda …","why":"*Interesse an* + dativo = interesse per; *Ihr* si accorda con il neutro *das Interesse*.","source":"hueber"},{"label":"3","lead":"a innerhalb · b ausserhalb · c bis","text":"Bitte geben Sie uns ___ der nächsten Tage Bescheid, …","gaps":[["innerhalb","a","a innerhalb"]],"solution":"Bitte geben Sie uns **innerhalb** der nächsten Tage Bescheid, …","en":"Ci faccia sapere entro i prossimi giorni …","why":"Un limite di tempo con il genitivo (*der nächsten Tage*) = *innerhalb*. *bis* richiederebbe *bis zum …*.","source":"prep"},{"label":"4","lead":"a wenn · b wann · c ob","text":"…, ___ Sie zu diesem Termin kommen können.","gaps":[["ob","c","c ob"]],"solution":"…, **ob** Sie zu diesem Termin kommen können.","en":"… se può venire a questo appuntamento.","why":"Una domanda indiretta sì/no richiede *ob* (se).","source":"hueber"},{"label":"5","lead":"a Zeugnisse · b Sachen · c Dokumente","text":"Bringen Sie noch folgende ___ mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","gaps":[["Dokumente","c","c Dokumente"]],"solution":"Bringen Sie noch folgende **Dokumente** mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","en":"Porti anche i seguenti documenti: il diploma della scuola professionale in originale e il Suo certificato B2.","why":"Un certificato e un diploma sono *Dokumente*; *Zeugnisse* non comprenderebbe anche il certificato B2, e *Sachen* è troppo vago per una lettera formale.","source":"hueber"},{"label":"6","lead":"a stellen · b stehen · c haben","text":"Für Fragen und weitere Informationen ___ wir Ihnen gern zur Verfügung.","gaps":[["stehen","b","b stehen"]],"solution":"Für Fragen und weitere Informationen **stehen** wir Ihnen gern zur Verfügung.","en":"Restiamo volentieri a Sua disposizione per domande e ulteriori informazioni.","why":"Espressione fissa: *jemandem zur Verfügung stehen* = essere a disposizione di qualcuno.","source":"hueber"}]}]},{"page":"AB 145","heading":"B  Während seines letzten Schuljahres …","heading_en":"Durante il suo ultimo anno di scuola …","exercises":[{"no":"14","tag":"B3","instruction":"Verbinden Sie.","instruction_en":"Abbina ogni domanda od osservazione di un colloquio di lavoro alla risposta giusta (1–7). Scrivi il numero. (L'esercizio 13 è un ascolto ed è omesso.)","phrases":["1 Ich war zuständig für die Kontrolle von Haushalts-, Garten- und Freizeitartikeln.","2 Ich beherrsche die üblichen Programme und habe mich letztes Jahr im Bereich Lagerdatenbank weitergebildet.","3 Ja, ich würde gern wissen, wie gross das Lager hier ist.","4 Vielen Dank auch Ihnen.","5 Vielen Dank.","6 Ja, ich spreche drei Sprachen.","7 Also, ich bin Baumaschinenmechaniker und mache gerade den Führerausweis Kategorie BE."],"example":[{"label":"a","text":"Guten Tag, Herr Trantow. Nehmen Sie doch bitte Platz. → **5** Vielen Dank."}],"items":[{"label":"b","text":"Erzählen Sie doch bitte etwas über sich. → ___","gaps":[["7"]],"solution":"Erzählen Sie doch bitte etwas über sich. → **7**","en":"Mi racconti qualcosa di sé, per favore. → 7 Allora, sono meccanico di macchine edili e sto prendendo la patente di categoria BE.","why":"Ti presenti: il tuo lavoro e che cosa stai facendo adesso.","source":"hueber"},{"label":"c","text":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → ___","gaps":[["1"]],"solution":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → **1**","en":"Quali compiti aveva presso il Suo ultimo datore di lavoro? → 1 Ero responsabile del controllo degli articoli per la casa, il giardino e il tempo libero.","why":"*zuständig sein für* = essere responsabile di (i tuoi compiti).","source":"hueber"},{"label":"d","text":"Haben Sie noch andere Fähigkeiten? → ___","gaps":[["6"]],"solution":"Haben Sie noch andere Fähigkeiten? → **6**","en":"Ha anche altre competenze? → 6 Sì, parlo tre lingue.","why":"Una domanda sì/no sulle competenze: *Ja, …*","source":"hueber"},{"label":"e","text":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → ___","gaps":[["2"]],"solution":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → **2**","en":"Può dirmi di più sulle Sue conoscenze informatiche? → 2 Conosco i programmi più comuni e l'anno scorso ho fatto una formazione continua sui database di magazzino.","why":"*beherrschen* = padroneggiare; *sich weiterbilden* = fare una formazione continua.","source":"hueber"},{"label":"f","text":"Haben Sie noch eine Frage? → ___","gaps":[["3"]],"solution":"Haben Sie noch eine Frage? → **3**","en":"Ha ancora qualche domanda? → 3 Sì, vorrei sapere quanto è grande il magazzino qui.","why":"Una domanda indiretta: *wie gross das Lager hier ist* (verbo alla fine).","source":"hueber"},{"label":"g","text":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → ___","gaps":[["4"]],"solution":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → **4**","en":"Grazie mille di essere venuto da noi, signor Trantow. → 4 Grazie anche a Lei.","why":"Ricambi il ringraziamento: *Vielen Dank auch Ihnen.*","source":"hueber"}]},{"no":"15","tag":"B3","instruction":"Das kann ich! Ergänzen Sie Informationen über sich.","instruction_en":"Lo so fare! Completa le frasi con informazioni su di te. Le risposte modello sono una possibilità.","items":[{"label":"a","lead":"Ich habe schon während der Schulzeit/des Studiums …","text":"","open":true,"solution":"Ich habe schon während der Schulzeit in einem Café gejobbt.","en":"Già durante gli anni di scuola facevo un lavoretto in un caffè.","why":"*während* + genitivo; Perfekt con il participio alla fine.","source":"g299310"},{"label":"b","lead":"Ich bin/war zuständig für …","text":"","open":true,"solution":"Ich war zuständig für die Buchhaltung in einem kleinen Büro.","en":"Ero responsabile della contabilità in un piccolo ufficio.","why":"*zuständig für* + accusativo.","source":"hueber"},{"label":"c","lead":"Ich beherrsche …","text":"","open":true,"solution":"Ich beherrsche Excel und die üblichen Office-Programme.","en":"Padroneggio Excel e i comuni programmi da ufficio.","why":"*beherrschen* + accusativo = padroneggiare una competenza o una lingua.","source":"hueber"},{"label":"d","lead":"Ich habe auch (sehr) gute Kenntnisse in …","text":"","open":true,"solution":"Ich habe auch sehr gute Kenntnisse in Englisch und Italienisch.","en":"Ho anche ottime conoscenze di inglese e italiano.","why":"*Kenntnisse in* + dativo.","source":"hueber"},{"label":"e","lead":"Es fällt mir leicht, …","text":"","open":true,"solution":"Es fällt mir leicht, im Team zu arbeiten und auf neue Kunden zuzugehen.","en":"Mi riesce facile lavorare in team e avvicinare nuovi clienti.","why":"*Es fällt mir leicht* + *zu* + infinito; *zugehen* è separabile: *zu**zu**gehen*.","source":"g4069"}]}]},{"page":"AB 146","heading":"C  Berufsberatung","heading_en":"Orientamento professionale","exercises":[{"no":"16","tag":"C2","instruction":"Was ist richtig? Lesen Sie und kreuzen Sie an.","instruction_en":"Che cosa è giusto? Leggi i testi. Scrivi *richtig* (giusto) o *falsch* (sbagliato) dopo ogni frase; nel libro segni solo quelle giuste.","reading":[{"label":"Was wollt ihr werden? – Jacqueline","text":"Ich gehe noch zur Schule. Nächstes Jahr mache ich die Matura. Ein Studium ist aber nichts für mich. Das dauert zu lange. Planung und Organisation sind kein Problem für mich. Deshalb möchte ich einen kaufmännischen Beruf ergreifen. Kommenden Montag habe ich einen Termin bei der Berufsberatung."},{"label":"Konstantinos","text":"In der Schule war ich gut in Mathematik und Kunst. Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte. Und ich wollte auch künstlerisch tätig sein. Aber ich wusste nicht, wie ich das zusammenbringen sollte. Deshalb bin ich zur Berufsberatung gegangen. Der Berater hat mir eine Lehre als Zeichner Landschaftsarchitektur empfohlen. Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt."}],"items":[{"label":"a","text":"Jacqueline hat keine Lust zu studieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Jacqueline hat keine Lust zu studieren. → **richtig**","en":"Jacqueline non ha voglia di studiare all'università. → giusto","why":"*Ein Studium ist aber nichts für mich. Das dauert zu lange.*","source":"hueber"},{"label":"b","text":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → ___","gaps":[["falsch","f","nein"]],"solution":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → **falsch**","en":"Trova difficile pianificare o organizzare qualcosa. → sbagliato","why":"Il contrario: *Planung und Organisation sind kein Problem für mich.*","source":"hueber"},{"label":"c","text":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → **richtig**","en":"La settimana prossima vuole informarsi sulle formazioni commerciali. → giusto","why":"*Kommenden Montag habe ich einen Termin bei der Berufsberatung*, per un lavoro commerciale.","source":"hueber"},{"label":"d","text":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → ___","gaps":[["richtig","r","ja"]],"solution":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → **richtig**","en":"Konstantinos aveva intenzione di lavorare nel campo della tecnica dopo la scuola. → giusto","why":"*Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte.*","source":"hueber"},{"label":"e","text":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → ___","gaps":[["richtig","r","ja"]],"solution":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → **richtig**","en":"All'inizio trovava difficile conciliare i suoi campi di interesse. → giusto","why":"*Aber ich wusste nicht, wie ich das zusammenbringen sollte.*","source":"hueber"},{"label":"f","text":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → ___","gaps":[["falsch","f","nein"]],"solution":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → **falsch**","en":"Si aspettava che l'apprendistato come disegnatore in architettura del paesaggio gli sarebbe piaciuto. → sbagliato","why":"*Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt* = non se lo aspettava.","source":"hueber"}]},{"no":"17","tag":"C2","instruction":"Schreiben Sie Sätze (a–e). Ordnen Sie dann den passenden Ratschlag (1–5) zu.","instruction_en":"Scrivi una frase con *zu* + infinito per ogni spunto (a–e). Poi trova il consiglio adatto (1–5); la soluzione indica il suo numero.","phrases":["1 Du könntest Busfahrer werden.","2 Dann werde doch Schreiner.","3 Hm, schwierig. Vielleicht Modedesigner?","4 Wie wäre es mit einer Tätigkeit als Bäcker?","5 An deiner Stelle würde ich Köchin werden."],"example":[{"label":"a","lead":"sich gut vorstellen können – im handwerklichen Bereich arbeiten","text":"**Ich kann mir gut vorstellen, im handwerklichen Bereich zu arbeiten.** → 2"}],"items":[{"label":"b","lead":"es nicht schwer finden – früh aufstehen","text":"","accept":["Ich finde es nicht schwer, früh aufzustehen.","Es fällt mir nicht schwer, früh aufzustehen."],"solution":"**Ich finde es nicht schwer, früh aufzustehen.** → 4","en":"Non trovo difficile alzarmi presto. → 4 Che ne dici di un lavoro come panettiere?","why":"*Ich finde es* + aggettivo + *zu* + infinito; *aufstehen* è separabile: *auf**zu**stehen*. I panettieri cominciano a lavorare molto presto.","source":"g4069","check":"La soluzione ufficiale scrive *Es fällt mir nicht schwer, früh aufzustehen*, che significa la stessa cosa; lo spunto *es nicht schwer finden* dà *Ich finde es nicht schwer, …*. Entrambe sono corrette."},{"label":"c","lead":"Lust haben – viel unterwegs sein","text":"","accept":["Ich habe Lust, viel unterwegs zu sein."],"solution":"**Ich habe Lust, viel unterwegs zu sein.** → 1","en":"Ho voglia di essere spesso in giro. → 1 Potresti diventare autista di autobus.","why":"*Lust haben* + *zu* + infinito.","source":"g6865"},{"label":"d","lead":"Freude machen – für andere kochen","text":"","accept":["Es macht mir Freude, für andere zu kochen.","Mir macht es Freude, für andere zu kochen."],"solution":"**Es macht mir Freude, für andere zu kochen.** → 5","en":"Mi piace cucinare per gli altri. → 5 Se fossi in te, diventerei cuoco.","why":"*Es macht mir Freude* + *zu* + infinito.","source":"g6865"},{"label":"e","lead":"Interesse haben – Neues entwickeln","text":"","accept":["Ich habe Interesse daran, Neues zu entwickeln.","Ich habe Interesse, Neues zu entwickeln."],"solution":"**Ich habe Interesse daran, Neues zu entwickeln.** → 3","en":"Mi interessa sviluppare cose nuove. → 3 Mmh, difficile. Forse stilista?","why":"*Interesse haben (daran)* + *zu* + infinito; *daran* rimanda alla frase con *zu* che segue.","source":"g6865"}]},{"no":"18","tag":"C2","instruction":"Wörter mit -ng","instruction_en":"Parole con -ng","part":"a","part_instruction":"Bilden Sie Wörter mit *-ung*.","part_instruction_en":"Forma dei sostantivi in *-ung* a partire dai verbi, con l'articolo. (Le parti b–d sono ascolti e sono omesse.)","example":[{"label":"1","text":"beraten → **die Beratung**"},{"label":"4","text":"entwickeln → **die Entwicklung**"}],"items":[{"label":"2","text":"erfahren → ___","gaps":[["die Erfahrung","Erfahrung"]],"solution":"erfahren → **die Erfahrung**","en":"sperimentare → esperienza","why":"Radice del verbo + *-ung*; i sostantivi in *-ung* sono sempre femminili: *die*.","source":"hueber"},{"label":"3","text":"verantworten → ___","gaps":[["die Verantwortung","Verantwortung"]],"solution":"verantworten → **die Verantwortung**","en":"essere responsabile di → responsabilità","why":"Radice *verantwort-* + *-ung*: *die Verantwortung*.","source":"hueber"},{"label":"5","text":"beschäftigen → ___","gaps":[["die Beschäftigung","Beschäftigung"]],"solution":"beschäftigen → **die Beschäftigung**","en":"occupare / impiegare → impiego, occupazione","why":"Radice *beschäftig-* + *-ung*.","source":"hueber"},{"label":"6","text":"unterstützen → ___","gaps":[["die Unterstützung","Unterstützung"]],"solution":"unterstützen → **die Unterstützung**","en":"sostenere → sostegno","why":"Radice *unterstütz-* + *-ung*.","source":"hueber"}]}]},{"page":"AB 147","heading":"D  Small Talk: Von der Arbeit erzählen","heading_en":"Small talk: parlare di lavoro","exercises":[{"no":"19","tag":"D2","instruction":"Ordnen Sie zu.","instruction_en":"Completa il dialogo di small talk tra Bettina (○) e un amico (◆) con le espressioni dei due riquadri (qui riunite in uno solo). Ogni espressione si usa una volta; quella barrata è usata nell'esempio.","box":["es ist total stressig","Hast du noch nie daran gedacht","muss zwei Kollegen vertreten","Hast du immer noch so viel Arbeit","schon mehrere Bewerbungen geschrieben","suche immer noch eine Stelle","Wie läuft's denn so","Ist das nicht anstrengend","machst du jetzt eigentlich genau","habe kein Interesse","komme gut mit den Kunden und den Kollegen zurecht","muss jetzt leider gehen"],"box_used":[6],"box_exact":true,"example":[{"label":"a","text":"◆ Hoi, Bettina. Das ist aber schön, dich zu sehen. **Wie läuft's denn so** mit der Jobsuche?"}],"items":[{"label":"b","text":"○ Schwierig. Ich ___ als Übersetzerin.","gaps":[["suche immer noch eine Stelle"]],"solution":"○ Schwierig. Ich **suche immer noch eine Stelle** als Übersetzerin.","en":"○ Difficile. Sto ancora cercando un posto come traduttrice.","why":"Dopo *Ich* segue il verbo *suche*.","source":"hueber"},{"label":"c","text":"○ Ich habe ___, aber nur Absagen erhalten.","gaps":[["schon mehrere Bewerbungen geschrieben"]],"solution":"○ Ich habe **schon mehrere Bewerbungen geschrieben**, aber nur Absagen erhalten.","en":"○ Ho già scritto diverse candidature, ma ho ricevuto solo risposte negative.","why":"Perfekt: *habe … geschrieben*, in parallelo con *erhalten*.","source":"hueber"},{"label":"d","text":"◆ ___, dich selbstständig zu machen? Das machen doch viele Übersetzer.","gaps":[["Hast du noch nie daran gedacht"]],"solution":"◆ **Hast du noch nie daran gedacht**, dich selbstständig zu machen? Das machen doch viele Übersetzer.","en":"◆ Non hai mai pensato di metterti in proprio? Lo fanno molti traduttori.","why":"*daran denken* + *zu* + infinito; *daran* rimanda alla frase con *zu*.","source":"hueber"},{"label":"e","text":"○ Ja, das stimmt. Aber ___, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","gaps":[["es ist total stressig"]],"solution":"○ Ja, das stimmt. Aber **es ist total stressig**, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","en":"○ Sì, è vero. Ma è davvero stressante cercare sempre incarichi. E poi c'è molta concorrenza.","why":"*Es ist* + aggettivo + *zu* + infinito.","source":"hueber"},{"label":"f","text":"○ Aber wie geht es dir denn? ___?","gaps":[["Hast du immer noch so viel Arbeit"]],"solution":"○ Aber wie geht es dir denn? **Hast du immer noch so viel Arbeit**?","en":"○ Ma tu come stai? Hai ancora così tanto lavoro?","why":"La risposta *Ja, leider* richiede una domanda sì/no.","source":"hueber"},{"label":"g","text":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich ___. Und das jetzt, wo wir so viele Aufträge haben!","gaps":[["muss zwei Kollegen vertreten"]],"solution":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich **muss zwei Kollegen vertreten**. Und das jetzt, wo wir so viele Aufträge haben!","en":"◆ Sì, purtroppo. Nella nostra ditta al momento diverse persone sono malate. Devo sostituire due colleghi. E proprio adesso che abbiamo così tanti ordini!","why":"*vertreten* = sostituire qualcuno.","source":"hueber"},{"label":"h","text":"○ Was ___?","gaps":[["machst du jetzt eigentlich genau"]],"solution":"○ Was **machst du jetzt eigentlich genau**?","en":"○ Ma tu che cosa fai esattamente adesso?","why":"Una domanda con parola interrogativa: *Was* + verbo *machst* + *du*.","source":"hueber"},{"label":"i","lead":"◆ Ich bin als Heizungsinstallateur tätig. Ich habe die Verantwortung für zwei Baustellen und soll nebenbei die Baustellen meiner Kollegen betreuen.","text":"○ ___, immer von Baustelle zu Baustelle zu fahren?","gaps":[["Ist das nicht anstrengend"]],"solution":"○ **Ist das nicht anstrengend**, immer von Baustelle zu Baustelle zu fahren?","en":"○ Non è faticoso andare sempre da un cantiere all'altro?","why":"*Ist das nicht anstrengend, … zu* + infinito?","source":"hueber"},{"label":"j","text":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich ___. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","gaps":[["komme gut mit den Kunden und den Kollegen zurecht"]],"solution":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich **komme gut mit den Kunden und den Kollegen zurecht**. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","en":"◆ A volte sì, ma per lo più il lavoro mi piace. Vado d'accordo con i clienti e con i colleghi. A proposito, la mia ditta sta cercando qualcuno per l'ufficio. Non vuoi candidarti?","why":"*mit jemandem gut zurechtkommen* = andare d'accordo con qualcuno (separabile).","source":"hueber"},{"label":"k","text":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich ___ an einer Tätigkeit als Sekretärin.","gaps":[["habe kein Interesse"]],"solution":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich **habe kein Interesse** an einer Tätigkeit als Sekretärin.","en":"○ Ma che dici! Sono traduttrice. Non mi interessa un lavoro come segretaria.","why":"*Interesse an* + dativo (*an einer Tätigkeit*).","source":"hueber"},{"label":"l","lead":"◆ Warum nicht? Als Übersetzerin sitzt du doch auch am Computer, schreibst und telefonierst. Der Job ist sicher und unsere Firma zahlt nicht schlecht. Überleg es dir doch einmal.","text":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich ___.","gaps":[["muss jetzt leider gehen"]],"solution":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich **muss jetzt leider gehen**.","en":"○ Va bene, lo faccio. Grazie del consiglio. Oh, purtroppo adesso devo andare.","why":"Un modo tipico per chiudere uno small talk.","source":"hueber"}]},{"no":"20","tag":"D2","instruction":"Ergänzen Sie.","instruction_en":"Completa i brevi annunci. Il libro dà alcune lettere di ogni parola; scrivi la parola intera.","example":[{"label":"Beispiel","text":"In den Semesterferien **jobben** – …"}],"items":[{"label":"A","lead":"Ü _ _ _ s _ tz _ _ /in","text":"In den Semesterferien jobben – wir suchen dich als ___/in von kurzen Werbetexten.","gaps":[["Übersetzer"]],"solution":"In den Semesterferien jobben – wir suchen dich als **Übersetzer**/in von kurzen Werbetexten.","en":"Lavoretti durante le vacanze semestrali: cerchiamo te come traduttore/traduttrice di brevi testi pubblicitari.","why":"*der Übersetzer / die Übersetzerin* = traduttore, traduttrice.","source":"hueber"},{"label":"B","lead":"A _ f _ _ ä _ _ n","text":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach ___ suchen.","gaps":[["Aufträgen"]],"solution":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach **Aufträgen** suchen.","en":"Lavorare in proprio come addetto/a alle pulizie: su Putzfee.net può offrire il Suo servizio e cercare incarichi.","why":"*der Auftrag, die Aufträge* = ordine, incarico; *nach* + dativo plurale aggiunge *-n*: *Aufträgen*.","source":"hueber"},{"label":"C1","lead":"F _ _ _ b _ _ _ _ g","text":"Machen Sie eine ___. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","gaps":[["Fortbildung"]],"solution":"Machen Sie eine **Fortbildung**. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","en":"Faccia un corso di aggiornamento. Offriamo seminari interessanti nei settori tecnica e commercio.","why":"*eine Fortbildung machen* = fare un corso di aggiornamento.","source":"hueber"},{"label":"C2","lead":"K _ _ k _ _ _ e _ z","text":"Denn die ___ schläft nicht!","gaps":[["Konkurrenz"]],"solution":"Denn die **Konkurrenz** schläft nicht!","en":"Perché la concorrenza non dorme!","why":"*die Konkurrenz* = la concorrenza (i rivali).","source":"hueber"},{"label":"D","lead":"v _ _ tr _ _ _ n","text":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter ___ können.","gaps":[["vertreten"]],"solution":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter **vertreten** können.","en":"Flessibile e motivato/a? Cerchiamo persone che possano sostituire a ore i nostri magazzinieri.","why":"Verbo modale *können* + infinito *vertreten* (senza *zu*).","source":"hueber"}]}]},{"page":"AB 148","heading":"Test Lektion 5","heading_en":"Test della lezione 5","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Completa le frasi. Il libro dà alcune lettere di ogni parola; scrivi la parola intera.","example":[{"label":"d","text":"Frau Angst will bald **aufhören** zu arbeiten und in Pension gehen."}],"items":[{"label":"a","lead":"A _ _ t _ ä _ e","text":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele ___.","gaps":[["Aufträge"]],"solution":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele **Aufträge**.","en":"La ditta Müller & Müller è molto valida e per questo ha molti ordini.","why":"*der Auftrag, die Aufträge* = ordine, ordini; *viele* richiede il plurale."},{"label":"b","lead":"V _ r _ n _ w _ _ t _ _ g","text":"Frau Brügger hat die ___ für 200 Mitarbeiter.","gaps":[["Verantwortung"]],"solution":"Frau Brügger hat die **Verantwortung** für 200 Mitarbeiter.","en":"La signora Brügger ha la responsabilità di 200 collaboratori.","why":"*die Verantwortung für* + accusativo = responsabilità di."},{"label":"c","lead":"_ t _ _ _ _ … h _ _","text":"Die Firma ___ die Möbel aus Schweizer Holz ___.","gaps":[["stellt"],["her"]],"solution":"Die Firma **stellt** die Möbel aus Schweizer Holz **her**.","en":"La ditta produce i mobili con legno svizzero.","why":"*herstellen* = produrre, fabbricare; separabile: *stellt … her*."},{"label":"e","lead":"S _ _ v _ _ _ a _ g _ _ _ _ _ _ _ _ r","text":"Mario ist als ___ in einem Restaurant tätig.","gaps":[["Serviceangestellter"]],"solution":"Mario ist als **Serviceangestellter** in einem Restaurant tätig.","en":"Mario lavora come cameriere in un ristorante.","why":"*der Serviceangestellte* = cameriere (uso svizzero); dopo *als* senza articolo la desinenza è *-er*: *als Serviceangestellter*."},{"label":"f","lead":"z _ st _ _ _ _ g","text":"Peter ist ___ für die Kontrolle und Reparatur der Werkzeugmaschinen.","gaps":[["zuständig"]],"solution":"Peter ist **zuständig** für die Kontrolle und Reparatur der Werkzeugmaschinen.","en":"Peter è responsabile del controllo e della riparazione delle macchine utensili.","why":"*zuständig sein für* = essere responsabile di."},{"label":"g","lead":"F _ _ _ b _ _ d _ _ g _ n","text":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele ___ an.","gaps":[["Fortbildungen"]],"solution":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele **Fortbildungen** an.","en":"La ditta Müller & Müller offre ai suoi collaboratori molti corsi di aggiornamento.","why":"*die Fortbildung, die Fortbildungen*; *viele* richiede il plurale."}]},{"no":"2","instruction":"Schreiben Sie die Sätze neu.","instruction_en":"Riscrivi ogni frase con l'inizio dato, usando *zu* + infinito. Scrivi solo la parte dopo la virgola.","example":[{"label":"a","lead":"Fortbildungen interessieren mich nicht!","text":"Ich habe kein Interesse, **Fortbildungen zu machen**."}],"items":[{"label":"b","lead":"Die Zusammenarbeit mit meinen Kollegen macht mir Freude.","text":"Es macht mir Freude, ___.","gaps":[["mit meinen Kollegen zusammenzuarbeiten"]],"solution":"Es macht mir Freude, **mit meinen Kollegen zusammenzuarbeiten**.","en":"Mi piace lavorare insieme ai miei colleghi.","why":"*die Zusammenarbeit* → il verbo *zusammenarbeiten*, separabile: *zusammen**zu**arbeiten*.","source":"g4069"},{"label":"c","lead":"Ich könnte mir eine Arbeit als Pflegefachmann gut vorstellen.","text":"Ich könnte mir gut vorstellen, ___.","gaps":[["als Pflegefachmann zu arbeiten"]],"solution":"Ich könnte mir gut vorstellen, **als Pflegefachmann zu arbeiten**.","en":"Potrei benissimo immaginare di lavorare come infermiere.","why":"*eine Arbeit als …* → *als … zu arbeiten*.","source":"g6865"},{"label":"d","lead":"Der Berufsberater verspricht Hilfe bei der Berufswahl.","text":"Der Berufsberater verspricht, ___.","gaps":[["bei der Berufswahl zu helfen","mir bei der Berufswahl zu helfen","uns bei der Berufswahl zu helfen","bei der Berufswahl zu unterstützen"]],"solution":"Der Berufsberater verspricht, **bei der Berufswahl zu helfen**.","en":"Il consulente di orientamento professionale promette di aiutare nella scelta della professione.","why":"*die Hilfe* → il verbo *helfen*: *zu helfen* alla fine.","source":"g6865"}]},{"no":"3","instruction":"Ergänzen Sie: *während – innerhalb – ausserhalb* und *der – ein – …* in der richtigen Form.","instruction_en":"Completa con *während*, *innerhalb* o *ausserhalb* più l'articolo nella forma giusta (genitivo). Il libro dà la prima lettera dell'articolo.","example":[{"label":"a","text":"Sehr geehrter Herr Safak, vielen Dank für Ihre Bewerbung. Wir melden uns **innerhalb der** nächsten Tage bei Ihnen."}],"items":[{"label":"b1","lead":"Sehr geehrter Herr Safak, wir laden Sie zu einem Vorstellungsgespräch am 2.8. um 10 Uhr ein.","text":"___ Gesprächs können Sie natürlich gern Fragen stellen.","gaps":[["Während des"]],"solution":"**Während des** Gesprächs können Sie natürlich gern Fragen stellen.","en":"Durante il colloquio può naturalmente fare domande.","why":"*während* + genitivo neutro: *des Gesprächs*.","source":"g299310"},{"label":"b2","text":"Bitte geben Sie ___ Woche Bescheid, ob Sie kommen.","gaps":[["innerhalb einer"]],"solution":"Bitte geben Sie **innerhalb einer** Woche Bescheid, ob Sie kommen.","en":"Ci faccia sapere entro una settimana se viene.","why":"*innerhalb* + genitivo femminile: *einer Woche*.","source":"prep"},{"label":"b3","text":"Sie erreichen mich per Telefon oder ___ Bürozeiten per E-Mail.","gaps":[["ausserhalb der"]],"solution":"Sie erreichen mich per Telefon oder **ausserhalb der** Bürozeiten per E-Mail.","en":"Può raggiungermi per telefono oppure, fuori dagli orari d'ufficio, per e-mail.","why":"*ausserhalb* + genitivo plurale: *der Bürozeiten*.","source":"prep"}]},{"no":"4","instruction":"Verbinden Sie.","instruction_en":"Abbina ogni domanda alla risposta giusta (1–5). Scrivi il numero.","phrases":["1 Nein, das kann ich mir nicht vorstellen.","2 Nein, das finde ich nicht.","3 Ja, ich muss eine Kollegin vertreten.","4 Ich beende gerade meine Lehre als Maler.","5 Danke, recht gut. Wir haben viel Arbeit."],"example":[{"label":"a","text":"Wie läuft's denn so in der Firma? → **5** Danke, recht gut. Wir haben viel Arbeit."}],"items":[{"label":"b","text":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → ___","gaps":[["1"]],"solution":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → **1**","en":"Non hai mai pensato di cambiare lavoro? → 1 No, non riesco a immaginarlo.","why":"Una domanda su un'idea: *Nein, das kann ich mir nicht vorstellen.*"},{"label":"c","text":"Was machst du jetzt eigentlich genau? → ___","gaps":[["4"]],"solution":"Was machst du jetzt eigentlich genau? → **4**","en":"Che cosa fai esattamente adesso? → 4 Sto finendo l'apprendistato da imbianchino.","why":"Una domanda con parola interrogativa sul tuo lavoro richiede un fatto come risposta."},{"label":"d","text":"Ist es nicht stressig, nachts zu arbeiten? → ___","gaps":[["2"]],"solution":"Ist es nicht stressig, nachts zu arbeiten? → **2**","en":"Non è stressante lavorare di notte? → 2 No, non credo.","why":"*Ist es nicht stressig …?* chiede un'opinione: *Nein, das finde ich nicht.*"},{"label":"e","text":"Hast du immer noch so viel Arbeit? → ___","gaps":[["3"]],"solution":"Hast du immer noch so viel Arbeit? → **3**","en":"Hai ancora così tanto lavoro? → 3 Sì, devo sostituire una collega.","why":"Domanda sì/no; il motivo del tanto lavoro: *eine Kollegin vertreten*."}]}]},{"page":"AB 149","heading":"Fokus Beruf: Etwas verhandeln","heading_en":"Focus lavoro: negoziare","exercises":[{"no":"1","instruction":"Vier gute Tipps","instruction_en":"Quattro buoni consigli","part":"a","part_instruction":"Wofür bekommt man hier Tipps? Überfliegen Sie den Text und kreuzen Sie an.","part_instruction_en":"A che cosa servono questi consigli? Leggi il testo velocemente e scrivi la risposta giusta. (Gli esercizi 2 e 3 di questa pagina sono ascolti e sono omessi.)","reading":[{"label":"So kommen Sie weiter!","text":"Ist das Bewerbungsgespräch gut gelaufen? Herzlichen Glückwunsch! Jetzt haben Sie es fast geschafft. Aber wenn es im Bewerbungsgespräch zum Thema Geld kommt, machen viele Bewerber Fehler: Sie fordern zu viel Lohn – oder zu wenig. Unsere Tipps helfen Ihnen bei diesem schwierigen Thema.\n1  Sprechen Sie das Thema Geld nicht selbst an. Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.\n2  Nennen Sie Ihre Gehaltsvorstellung. Wenn Sie vorher in anderen Unternehmen gearbeitet haben, ist Ihr letztes Gehalt die Grundlage.\n3  Natürlich können Sie an einem neuen Arbeitsplatz mehr Lohn verlangen, aber bleiben Sie realistisch und begründen Sie Ihre Gehaltsvorstellung: Haben Sie mehr Verantwortung? Können Sie mit besonderen Kenntnissen, Fähigkeiten oder Erfahrungen punkten? War der alte Arbeitgeber besonders zufrieden mit Ihnen?\n4  Was ist, wenn die Personalchefin oder der Personalchef negativ auf Ihre Gehaltsvorstellung reagiert? Dann müssen Sie flexibel sein und andere Vorschläge machen. Erklären Sie zum Beispiel, dass Sie mit weniger Lohn einverstanden sind, wenn die Firma Ihnen eine Weiter- oder Fortbildung bezahlt. Oder wenn Sie nach sechs Monaten mehr Lohn bekommen."}],"items":[{"label":"1","lead":"○ Für Gespräche mit der Bank   ○ Für Gespräche mit dem Arbeitgeber","text":"___","gaps":[["Für Gespräche mit dem Arbeitgeber","mit dem Arbeitgeber","Arbeitgeber","dem Arbeitgeber"]],"solution":"**Für Gespräche mit dem Arbeitgeber**","en":"Per i colloqui con il datore di lavoro","why":"I consigli riguardano come parlare di soldi nel colloquio di lavoro, con la o il responsabile del personale.","source":"hueber"}]},{"no":"1","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Che cosa è giusto? Rileggi. Scrivi *richtig* (giusto) o *falsch* (sbagliato) dopo ogni frase; nel libro segni solo quelle giuste.","items":[{"label":"1","text":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → ___","gaps":[["richtig","r","ja"]],"solution":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → **richtig**","en":"È compito della o del responsabile del personale affrontare il tema dello stipendio. → giusto","why":"Consiglio 1: *Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.*","source":"hueber"},{"label":"2","text":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → ___","gaps":[["falsch","f","nein"]],"solution":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → **falsch**","en":"Nel nuovo posto di lavoro all'inizio riceve lo stesso stipendio che nella vecchia ditta. → sbagliato","why":"Consigli 2 e 3: il tuo ultimo stipendio è solo la base; puoi chiedere di più.","source":"hueber"},{"label":"3","text":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → ___","gaps":[["richtig","r","ja"]],"solution":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → **richtig**","en":"Se vuole uno stipendio più alto, dovrebbe dare buoni argomenti. → giusto","why":"Consiglio 3: *begründen Sie Ihre Gehaltsvorstellung*.","source":"hueber"},{"label":"4","text":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → ___","gaps":[["falsch","f","nein"]],"solution":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → **falsch**","en":"Se la o il responsabile del personale non è d'accordo con la Sua proposta, non può fare più niente. → sbagliato","why":"Consiglio 4: sii flessibile e fai altre proposte (formazione pagata, più stipendio dopo sei mesi).","source":"hueber"}]}]}]},{"id":"05-um-zu-damit-statt-ohne-reklamation","no":5,"title":"Lektion 6","title_en":"Lo scopo con um … zu e damit, invece di / senza, verbi con es, conversazioni di vendita e reclami · Test della Lektion 6","added":"2026-11-18","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 6","pages":[{"page":"AB 150","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"Non è facile, ma ne vale la pena.","exercises":[{"no":"1","tag":"A2","instruction":"Ordnen Sie zu.","instruction_en":"Completa l'e-mail di Anna con le espressioni con *es* del riquadro. Ognuna si usa una volta; *geht es* è usata nell'esempio. Dove un'espressione ha *…*, in mezzo vanno altre parole: scrivi le due parti nei due spazi.","phrases":["geht es (Beispiel)","Es war","Es gibt","ist es … gelaufen","es … dunkel ist","wird es … schwierig","schwer es mir fällt","Es ist Sommer","regnet es","hat es … gefallen","es ist … kalt","ist es … ein Uhr","lohnt es sich"],"example":[{"label":"a","text":"Hallo Tim / Wie **geht es** Dir? Bei mir ist alles bestens."}],"items":[{"label":"b","text":"___, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","gaps":[["Es ist Sommer"]],"solution":"**Es ist Sommer**, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","en":"È estate, ovunque si vedono fiori e sto molto all'aperto. Adoro questa stagione!","why":"*es* + *sein* + una stagione o un momento della giornata: *Es ist Sommer / Nacht / vier Uhr*.","source":"platzhalter"},{"label":"c","text":"Seit ein paar Tagen ___ zwar, aber schlechtes Wetter stört mich ja nicht.","gaps":[["regnet es"]],"solution":"Seit ein paar Tagen **regnet es** zwar, aber schlechtes Wetter stört mich ja nicht.","en":"Da qualche giorno piove, è vero, ma il brutto tempo non mi dà fastidio.","why":"I verbi del tempo atmosferico hanno sempre *es* come soggetto. *Seit ein paar Tagen* è in posizione 1, quindi *es* viene dopo il verbo: *regnet es*.","source":"platzhalter"},{"label":"d","text":"Hauptsache, ___ nicht ___.","gaps":[["es ist"],["kalt"]],"solution":"Hauptsache, **es ist** nicht **kalt**.","en":"L'importante è che non faccia freddo.","why":"Tempo atmosferico con un aggettivo: *es ist kalt / heiss*. *nicht* va prima di *kalt*.","source":"platzhalter"},{"label":"e","text":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! ___ wirklich aufregend, …","gaps":[["Es war"]],"solution":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! **Es war** wirklich aufregend, …","en":"Senti, stamattina ho avuto un colloquio di lavoro! È stato davvero emozionante, …","why":"*es* generale + *sein* + aggettivo, qui al Präteritum: *Es war aufregend*.","source":"korrelat"},{"label":"f","text":"… aber eigentlich ___ ziemlich gut ___. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","gaps":[["ist es"],["gelaufen"]],"solution":"… aber eigentlich **ist es** ziemlich gut **gelaufen**. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","en":"… ma in realtà è andato piuttosto bene. Le persone sono molto simpatiche e il lavoro è vario.","why":"*Es ist gut gelaufen* = è andata bene (Perfekt con *sein*). *eigentlich* è in posizione 1, quindi *ist es*.","source":"platzhalter"},{"label":"g","text":"___ nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","gaps":[["Es gibt"]],"solution":"**Es gibt** nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","en":"Purtroppo c'è solo un problema: dovrei cominciare a lavorare alle 7 (!) del mattino. Che brutto!","why":"*es gibt* + accusativo = c'è / ci sono: *Es gibt ein Problem*.","source":"platzhalter"},{"label":"h","text":"Du weisst doch, wie ___, früh aufzustehen.","gaps":[["schwer es mir fällt"]],"solution":"Du weisst doch, wie **schwer es mir fällt**, früh aufzustehen.","en":"Sai bene quanto mi costi alzarmi presto.","why":"*Es fällt mir schwer, … zu …* = mi costa fatica … Nella frase con *wie* il verbo va alla fine: *wie schwer es mir fällt*.","source":"korrelat"},{"label":"i","text":"Vor allem im Winter, wenn ___ noch ___, …","gaps":[["es"],["dunkel ist"]],"solution":"Vor allem im Winter, wenn **es** noch **dunkel ist**, …","en":"Soprattutto d'inverno, quando è ancora buio, …","why":"*Es ist dunkel* (momento della giornata, luce). Nella frase con *wenn* il verbo va alla fine: *wenn es noch dunkel ist*.","source":"platzhalter"},{"label":"j","text":"… dann ___ wirklich ___ für mich.","gaps":[["wird es"],["schwierig"]],"solution":"… dann **wird es** wirklich **schwierig** für mich.","en":"… allora per me diventa davvero difficile.","why":"*Es wird schwierig* = diventa difficile. *dann* è in posizione 1, quindi *wird es*.","source":"korrelat"},{"label":"k","text":"Mir ___ in der Firma zwar sehr gut ___, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","gaps":[["hat es"],["gefallen"]],"solution":"Mir **hat es** in der Firma zwar sehr gut **gefallen**, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","en":"In ditta mi è piaciuto molto, ma non so se ce la faccio con la sveglia presto. Che cosa mi consigli?","why":"*Es gefällt mir* = mi piace; Perfekt: *Es hat mir gefallen*. Qui *Mir* è in posizione 1.","source":"korrelat"},{"label":"l","text":"P.S.: Oh je, jetzt ___ schon wieder ___ nachts.","gaps":[["ist es"],["ein Uhr"]],"solution":"P.S.: Oh je, jetzt **ist es** schon wieder **ein Uhr** nachts.","en":"P.S.: Oh no, è di nuovo già l'una di notte.","why":"L'ora: *Es ist ein Uhr*. *jetzt* è in posizione 1, quindi *ist es*.","source":"platzhalter"},{"label":"m","text":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht ___ und ich bin dann am Morgen plötzlich immer topfit?","gaps":[["lohnt es sich"]],"solution":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht **lohnt es sich** und ich bin dann am Morgen plötzlich immer topfit?","en":"Forse dovrei semplicemente andare a letto prima? Chissà, forse ne vale la pena e poi la mattina sono all'improvviso sempre in gran forma?","why":"*Es lohnt sich* = ne vale la pena. *vielleicht* è in posizione 1, quindi *lohnt es sich*.","source":"platzhalter"}]},{"no":"2","tag":"A2","instruction":"Machen Sie eine Tabelle und ergänzen Sie die Ausdrücke mit *es* aus 1.","instruction_en":"Ordina le espressioni con *es* dell'esercizio 1 in quattro gruppi. Scrivi il gruppo: *Allgemein* (in generale), *Tages-/Jahreszeiten* (momenti della giornata e stagioni), *Wetter* (tempo atmosferico) o *Befinden* (come sta qualcuno).","example":[{"label":"Befinden","text":"Wie geht es Dir? → **Befinden**"}],"items":[{"label":"1","text":"Es ist Sommer. → ___","gaps":[["Tages-/Jahreszeiten","Jahreszeiten","Tageszeiten","Jahreszeit","Tages- und Jahreszeiten"]],"solution":"Es ist Sommer. → **Tages-/Jahreszeiten**","en":"È estate. → momenti della giornata e stagioni","why":"Una stagione.","source":"hueber"},{"label":"2","text":"regnet es → ___","gaps":[["Wetter"]],"solution":"regnet es → **Wetter**","en":"piove → tempo atmosferico","why":"Verbo del tempo atmosferico.","source":"hueber"},{"label":"3","text":"es ist kalt → ___","gaps":[["Wetter"]],"solution":"es ist kalt → **Wetter**","en":"fa freddo → tempo atmosferico","why":"La temperatura fa parte del tempo atmosferico.","source":"hueber"},{"label":"4","text":"Es war (aufregend) → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es war (aufregend) → **Allgemein**","en":"È stato (emozionante) → in generale","why":"*es* + *sein* + aggettivo su una situazione.","source":"hueber"},{"label":"5","text":"es ist gelaufen → ___","gaps":[["Allgemein","allgemein"]],"solution":"es ist gelaufen → **Allgemein**","en":"è andato (bene) → in generale","why":"Com'è andata una cosa: un'espressione generale.","source":"hueber"},{"label":"6","text":"Es gibt → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es gibt → **Allgemein**","en":"C'è → in generale","why":"*es gibt* = c'è / ci sono.","source":"hueber"},{"label":"7","text":"schwer es mir fällt → ___","gaps":[["Allgemein","allgemein"]],"solution":"schwer es mir fällt → **Allgemein**","en":"quanto mi costa → in generale","why":"*es fällt mir schwer* = mi costa fatica.","source":"hueber"},{"label":"8","text":"es dunkel ist → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"es dunkel ist → **Tages-/Jahreszeiten**","en":"è buio → momenti della giornata","why":"Buio = momento della giornata.","source":"hueber","check":"La soluzione ufficiale mette *es ist dunkel* con i momenti della giornata. Lo potresti vedere anche come tempo atmosferico; chiedi al tuo insegnante se in classe l'avete ordinato diversamente."},{"label":"9","text":"wird es schwierig → ___","gaps":[["Allgemein","allgemein"]],"solution":"wird es schwierig → **Allgemein**","en":"diventa difficile → in generale","why":"*es* + *werden* + aggettivo su una situazione.","source":"hueber"},{"label":"10","text":"hat es gefallen → ___","gaps":[["Allgemein","allgemein"]],"solution":"hat es gefallen → **Allgemein**","en":"mi è piaciuto → in generale","why":"*es gefällt mir* = mi piace.","source":"hueber"},{"label":"11","text":"ist es ein Uhr → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"ist es ein Uhr → **Tages-/Jahreszeiten**","en":"è l'una → momenti della giornata","why":"L'ora.","source":"hueber"},{"label":"12","text":"lohnt es sich → ___","gaps":[["Allgemein","allgemein"]],"solution":"lohnt es sich → **Allgemein**","en":"ne vale la pena → in generale","why":"*es lohnt sich* = ne vale la pena.","source":"hueber"}]},{"no":"3","tag":"A2","instruction":"Wo fehlt *es*? Ergänzen Sie wie im Beispiel.","instruction_en":"Dove manca *es*? Leggi l'e-mail di Fatima. Riscrivi ogni frase qui sotto con *es* al posto giusto. Una frase è già corretta così: allora scrivila senza cambiarla.","reading":[{"label":"E-Mail","text":"Liebe Saskia\nist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe. Ich hoffe, dass euch gut geht. Seit wir in Gossau leben, ist viel passiert. Jetzt läuft ganz gut, aber am Anfang gab viele Probleme. Für unsere Kinder war besonders schwer. Sie haben ihre Freunde sehr vermisst und hatten Probleme mit der Sprache. Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt. Sie gehen ja jetzt auch zur Schule und haben andere Kinder kennengelernt. Übrigens gehe ich jetzt auch wieder in eine Schule – in eine Sprachschule. Ich besuche einen B1-Kurs. Das macht mir grosse Freude. So, jetzt ist gleich 9 Uhr. Ich muss Schluss machen. Mein Kurs fängt in einer halben Stunde an.\nBis bald, Deine Fatima"}],"example":[{"label":"Beispiel","text":"**Es** ist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe."}],"items":[{"label":"1","lead":"Ich hoffe, dass euch gut geht.","text":"","accept":["Ich hoffe, dass es euch gut geht."],"solution":"**Ich hoffe, dass es euch gut geht.**","en":"Spero che stiate tutti bene.","why":"*Wie geht es euch?* → *dass es euch gut geht*: *es* è il soggetto di *gehen* in questo senso e non si può togliere.","source":"platzhalter"},{"label":"2","lead":"Seit wir in Gossau leben, ist viel passiert.","text":"","accept":["Seit wir in Gossau leben, ist viel passiert."],"solution":"**Seit wir in Gossau leben, ist viel passiert.**","en":"Da quando viviamo a Gossau sono successe tante cose.","why":"Niente *es*: *viel* è il soggetto e la frase con *seit* occupa la posizione 1.","source":"platzhalter"},{"label":"3","lead":"Jetzt läuft ganz gut, aber am Anfang gab viele Probleme.","text":"","accept":["Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme."],"solution":"**Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme.**","en":"Adesso va abbastanza bene, ma all'inizio c'erano molti problemi.","why":"Due spazi: *es läuft gut* (le cose vanno bene) ed *es gab* (c'erano, Präteritum di *es gibt*). Con *jetzt* / *am Anfang* in posizione 1, *es* segue il verbo.","source":"platzhalter"},{"label":"4","lead":"Für unsere Kinder war besonders schwer.","text":"","accept":["Für unsere Kinder war es besonders schwer."],"solution":"**Für unsere Kinder war es besonders schwer.**","en":"Per i nostri figli è stato particolarmente difficile.","why":"*es* + *sein* + aggettivo: *es war schwer*.","source":"platzhalter"},{"label":"5","lead":"Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt.","text":"","accept":["Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt."],"solution":"**Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt.**","en":"Ma adesso va già molto meglio e si sono abituati alla vita qui.","why":"*es ist besser*: la situazione non ha un altro soggetto, quindi serve *es*.","source":"platzhalter"},{"label":"6","lead":"So, jetzt ist gleich 9 Uhr.","text":"","accept":["So, jetzt ist es gleich 9 Uhr."],"solution":"**So, jetzt ist es gleich 9 Uhr.**","en":"Bene, adesso sono quasi le 9.","why":"L'ora: *es ist 9 Uhr*.","source":"platzhalter"}]}]},{"page":"AB 151","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"Non è facile, ma ne vale la pena.","exercises":[{"no":"4","tag":"A3","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Che cosa è giusto? Leggi il testo su un ritrovo di paese e scrivi la parola che va in ogni spazio. Le due possibilità sono indicate sopra ogni frase.","reading":[{"label":"Stammtisch der Kulturen","text":"In unserem Dorf gibt es seit einiger Zeit am ersten Freitag im Monat einen Stammtisch der Kulturen. Dahin kommen alle, die Interesse an einem (a) Treffen mit Menschen aus aller Welt haben. Der Stammtisch ist ein grosser Erfolg geworden. Das war nicht immer so. Am Anfang war es eigentlich ein (b) und es kamen nur sehr wenige Teilnehmer. Es waren (c) fünf bis zehn da. Es war einfach so, dass die Leute aus der Region zuerst dachten, dass das Treffen nur für Migranten ist. Inzwischen kommen aber auch immer mehr Schweizer, (d) sind es oft sogar über 30 Leute pro Treffen. Alle helfen gratis mit und so funktioniert der Stammtisch ohne (e) Unterstützung."}],"example":[{"label":"a","text":"Dahin kommen alle, die Interesse an einem **interkulturellen** Treffen mit Menschen aus aller Welt haben."}],"items":[{"label":"b","lead":"Heimweh / Experiment","text":"Am Anfang war es eigentlich ein ___ und es kamen nur sehr wenige Teilnehmer.","gaps":[["Experiment"]],"solution":"Am Anfang war es eigentlich ein **Experiment** und es kamen nur sehr wenige Teilnehmer.","en":"All'inizio era in realtà un esperimento e venivano pochissimi partecipanti.","why":"*Heimweh* (nostalgia di casa) qui non ha senso; un'idea nuova che può funzionare o no è un *Experiment*.","source":"hueber"},{"label":"c","lead":"mindestens / höchstens","text":"Es waren ___ fünf bis zehn da.","gaps":[["höchstens"]],"solution":"Es waren **höchstens** fünf bis zehn da.","en":"C'erano al massimo cinque-dieci persone.","why":"*nur sehr wenige* → *höchstens* (al massimo), non *mindestens* (almeno).","source":"hueber"},{"label":"d","lead":"mindestens / mittlerweile","text":"Inzwischen kommen aber auch immer mehr Schweizer, ___ sind es oft sogar über 30 Leute pro Treffen.","gaps":[["mittlerweile"]],"solution":"Inzwischen kommen aber auch immer mehr Schweizer, **mittlerweile** sind es oft sogar über 30 Leute pro Treffen.","en":"Nel frattempo però vengono anche sempre più svizzeri; ormai sono spesso perfino più di 30 persone per incontro.","why":"*mittlerweile* = ormai, nel frattempo (come *inzwischen*).","source":"hueber"},{"label":"e","lead":"finanzielle / spezielle","text":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne ___ Unterstützung.","gaps":[["finanzielle"]],"solution":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne **finanzielle** Unterstützung.","en":"Tutti aiutano gratis e così il ritrovo funziona senza sostegno finanziario.","why":"*gratis* (gratuitamente) → non servono soldi: *finanzielle Unterstützung*.","source":"hueber"}]},{"no":"5","tag":"A3","instruction":"Ergänzen Sie.","instruction_en":"Completa le frasi. Il libro dà alcune lettere di ogni parola (indicate sopra la frase); scrivi la parola intera.","example":[{"label":"c","text":"Ich mag den Frühling und den Sommer. Aber der Winter ist für mich die schönste **Jahreszeit**."}],"items":[{"label":"a","lead":"H _ _ _ _ h","text":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe ___.","gaps":[["Heimweh"]],"solution":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe **Heimweh**.","en":"Sono triste perché non sono a casa. Ho nostalgia di casa.","why":"*das Heimweh* = nostalgia di casa; *Heimweh haben*.","source":"hueber"},{"label":"b","lead":"G _ _ _ r _ _","text":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen ___.","gaps":[["Gewürze"]],"solution":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen **Gewürze**.","en":"La cosa più importante quando si cucinano piatti indiani sono le spezie giuste.","why":"*das Gewürz, die Gewürze* = spezia, spezie; plurale per via di *sind*.","source":"hueber"},{"label":"d","lead":"G _ _ _ _ ä _ _ _ _ _ _ _ e","text":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche ___.","gaps":[["Geschäftsleute"]],"solution":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche **Geschäftsleute**.","en":"I miei nonni avevano diversi negozi. Erano commercianti di successo.","why":"*die Geschäftsleute* = plurale di *der Geschäftsmann / die Geschäftsfrau*.","source":"hueber"},{"label":"e","lead":"R _ _ _ _ c _ _ _","text":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine ___.","gaps":[["Rücksicht"]],"solution":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine **Rücksicht**.","en":"Il nostro vicino ascolta musica ad alto volume a ogni ora del giorno. Disturba tutti noi, ma lui non ha nessun riguardo.","why":"*Rücksicht nehmen (auf)* = avere riguardo (per).","source":"hueber"},{"label":"f","lead":"f _ _ _ _ z _ _ _ _ _ _  R _ _ _ _ _","text":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein ___ ___.","gaps":[["finanzielles"],["Risiko"]],"solution":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein **finanzielles** **Risiko**.","en":"Quando ci si mette in proprio con un'attività, spesso è un rischio finanziario.","why":"*das Risiko* è neutro, quindi *ein finanzielles Risiko*.","source":"hueber"},{"label":"g","lead":"l _ _ _","text":"Mein Onkel hat viele gute Ideen. Er ___ fast jedes Problem.","gaps":[["löst"]],"solution":"Mein Onkel hat viele gute Ideen. Er **löst** fast jedes Problem.","en":"Mio zio ha tante buone idee. Risolve quasi ogni problema.","why":"*ein Problem lösen* = risolvere un problema; *er löst*.","source":"hueber"}]},{"no":"6","tag":"A4","instruction":"Buchstaben und Laute: *b – p, g – k, d – t*","instruction_en":"Lettere e suoni: *b – p, g – k, d – t*. (Le parti a e b sono ascolti e sono omesse.)","part":"c","part_instruction":"Ergänzen Sie die Regel.","part_instruction_en":"Completa la regola: come si pronunciano *b, d, g* alla fine di una parola? Guarda *halb, Geld, Tag*.","items":[{"label":"c","text":"Am Wortende spricht man *b, d, g* wie ___.","gaps":[["p, t, k","p t k","p, t und k","p,t,k"]],"solution":"Am Wortende spricht man *b, d, g* wie **p, t, k**.","en":"Alla fine di una parola *b, d, g* si pronunciano come *p, t, k*.","why":"*halb* suona come \"halp\", *Geld* come \"Gelt\", *Tag* come \"Tak\". Lo stesso succede prima di un'altra consonante: *Erfolg*, *Auftrag*, *ab und zu*.","source":"hueber"}]}]},{"page":"AB 152","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Voglio essere al negozio per poter aspettare lì.","exercises":[{"no":"7","tag":"B1","instruction":"Margaretas Ziele. Ergänzen Sie.","instruction_en":"Gli obiettivi di Margareta. Ogni riga mostra un desiderio (a sinistra) e la stessa idea come scopo con *um … zu* (a destra). Riempi gli spazi dal lato in cui mancano.","example":[{"label":"a","lead":"Wozu ist Margareta in die Schweiz gekommen?","text":"Sie möchte ihr Deutsch verbessern. → Margareta ist in die Schweiz gekommen, **um** ihr Deutsch **zu verbessern**."}],"items":[{"label":"b","text":"Sie ___ eine Ausbildung ___. → um eine Ausbildung zu machen.","gaps":[["möchte"],["machen"]],"solution":"Sie **möchte** eine Ausbildung **machen**. → um eine Ausbildung zu machen.","en":"Vorrebbe fare una formazione professionale. → per fare una formazione professionale.","why":"Il desiderio: *möchte* + infinito alla fine. *um … zu* toglie il verbo modale.","source":"g6865"},{"label":"c","text":"Sie möchte selbstständiger werden. → ___ selbstständiger ___.","gaps":[["um"],["zu werden"]],"solution":"Sie möchte selbstständiger werden. → **um** selbstständiger **zu werden**.","en":"Vorrebbe diventare più indipendente. → per diventare più indipendente.","why":"*um* apre il gruppo, *zu* + infinito lo chiude. *möchte* sparisce.","source":"g6865"},{"label":"d","text":"Sie ___ Geld ___. → um Geld zu verdienen.","gaps":[["möchte"],["verdienen"]],"solution":"Sie **möchte** Geld **verdienen**. → um Geld zu verdienen.","en":"Vorrebbe guadagnare soldi. → per guadagnare soldi.","why":"Ritorno al desiderio: *Sie möchte Geld verdienen.*","source":"g6865"},{"label":"e","text":"Sie möchte in der Nähe ihres Freundes sein. → ___ in der Nähe ihres Freundes ___.","gaps":[["um"],["zu sein"]],"solution":"Sie möchte in der Nähe ihres Freundes sein. → **um** in der Nähe ihres Freundes **zu sein**.","en":"Vorrebbe essere vicina al suo ragazzo. → per essere vicina al suo ragazzo.","why":"*um … zu sein*; *ihres Freundes* è genitivo dopo *in der Nähe*.","source":"g6865"}]},{"no":"8","tag":"B1","instruction":"Wozu machen die Leute das? Ordnen Sie zu und ergänzen Sie die Sätze mit *um … zu*.","instruction_en":"Perché le persone fanno questo? Scegli dal riquadro lo scopo adatto a ogni frase e aggiungilo come *um … zu* + infinito. *gesund bleiben* è usato nell'esempio.","phrases":["frische Zutaten und Gewürze kaufen","als Erster im Büro sein","gesund bleiben (Beispiel)","einen wichtigen Kunden treffen","bessere Chancen auf dem Arbeitsmarkt haben"],"example":[{"label":"a","text":"Miguel geht dreimal pro Woche ins Fitnessstudio, **um gesund zu bleiben**."}],"items":[{"label":"b","text":"Peter steht von Montag bis Freitag sehr früh auf, ___.","gaps":[["um als Erster im Büro zu sein"]],"solution":"Peter steht von Montag bis Freitag sehr früh auf, **um als Erster im Büro zu sein**.","en":"Peter si alza molto presto dal lunedì al venerdì per essere il primo in ufficio.","why":"Stessa persona (Peter), quindi *um … zu*; *sein* va per ultimo con *zu*.","source":"g6865"},{"label":"c","text":"Am Wochenende gehe ich immer auf den Markt, ___.","gaps":[["um frische Zutaten und Gewürze zu kaufen"]],"solution":"Am Wochenende gehe ich immer auf den Markt, **um frische Zutaten und Gewürze zu kaufen**.","en":"Il fine settimana vado sempre al mercato per comprare ingredienti e spezie freschi.","why":"Tutto ciò che appartiene a *kaufen* viene prima di *zu kaufen*.","source":"g6865"},{"label":"d","text":"Herr Aryan fährt morgen nach Genf, ___.","gaps":[["um einen wichtigen Kunden zu treffen"]],"solution":"Herr Aryan fährt morgen nach Genf, **um einen wichtigen Kunden zu treffen**.","en":"Domani il signor Aryan va a Ginevra per incontrare un cliente importante.","why":"*um … zu treffen*; il complemento oggetto *einen wichtigen Kunden* va in mezzo.","source":"g6865"},{"label":"e","text":"Sabina macht eine berufliche Weiterbildung, ___.","gaps":[["um bessere Chancen auf dem Arbeitsmarkt zu haben"]],"solution":"Sabina macht eine berufliche Weiterbildung, **um bessere Chancen auf dem Arbeitsmarkt zu haben**.","en":"Sabina fa un corso di perfezionamento professionale per avere migliori possibilità sul mercato del lavoro.","why":"Stessa persona (Sabina): *um … zu haben*.","source":"g6865"}]},{"no":"9","tag":"B1","instruction":"Wozu ist Yaroslav in die Schweiz gekommen?","instruction_en":"Perché Yaroslav è venuto in Svizzera?","part":"a","part_instruction":"Lesen Sie den Text und ergänzen Sie die Gründe.","part_instruction_en":"Leggi il testo e completa i motivi con parole del testo.","reading":[{"label":"Abenteuer Ausland: Wozu sind Sie in die Schweiz gekommen? – Yaroslav Ivanenko, 38","text":"Meine Frau und ich wollten schon lange eine neue Perspektive im Leben finden. Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben. Bei mir war das anders. Ich bin IT-Spezialist und habe jahrelang als Programmierer in einer Softwarefirma gearbeitet. In unserem Land gibt es aber weniger Entwicklungsmöglichkeiten für meine Berufsbranche. Auch für unsere Kinder habe ich mir gewünscht, dass sie einmal eine gute Schule besuchen können. Aber die sind in unserer Heimat teuer. In einem internationalen Job-Portal im Internet habe ich dann gesehen, dass in der Schweiz Programmierer gesucht werden. Ich habe mich bei mehreren Firmen beworben und hatte grosses Glück. Gleich eins der ersten Vorstellungsgespräche, das ich über Skype geführt habe, war so positiv, dass ich von der Firma sofort ein Jobangebot erhalten habe. Die erste Zeit habe ich noch von der Ukraine aus gearbeitet, aber nach meiner Probezeit habe ich über die Firma eine offizielle Arbeitsbewilligung für die Schweiz bekommen. Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist. So haben wir uns entschlossen, mit den Kindern in die Schweiz zu ziehen. Es war nicht immer leicht für uns, aber jetzt sind wir einfach nur dankbar, dass wir diese Chance bekommen haben."}],"example":[{"label":"1","text":"Yaroslav und seine Frau können **eine neue Perspektive** finden."}],"items":[{"label":"2","text":"Seine Frau kann ___ leben.","gaps":[["in einer Stadt im Ausland"]],"solution":"Seine Frau kann **in einer Stadt im Ausland** leben.","en":"Sua moglie può vivere in una città all'estero.","why":"*Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben.*","source":"hueber"},{"label":"3","text":"Seine Kinder können ___ besuchen.","gaps":[["eine gute Schule"]],"solution":"Seine Kinder können **eine gute Schule** besuchen.","en":"I suoi figli possono frequentare una buona scuola.","why":"*… dass sie einmal eine gute Schule besuchen können.*","source":"hueber"},{"label":"4","text":"Das ganze Programmiererteam ist ___.","gaps":[["in Zug"]],"solution":"Das ganze Programmiererteam ist **in Zug**.","en":"Tutto il team di programmatori è a Zugo.","why":"*Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist.*","source":"hueber"}]}]},{"page":"AB 153","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Voglio essere al negozio per poter aspettare lì.","exercises":[{"no":"9","part":"b","part_instruction":"Schreiben Sie die Sätze neu mit *damit*.","part_instruction_en":"Riscrivi i motivi di a come frasi con *damit*: *Yaroslav ist in die Schweiz gekommen, damit …* Il verbo va alla fine.","example":[{"label":"1","text":"Yaroslav ist in die Schweiz gekommen, **damit er und seine Frau eine neue Perspektive finden können**."}],"items":[{"label":"2","lead":"Seine Frau kann in einer Stadt im Ausland leben.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.**","en":"Yaroslav è venuto in Svizzera affinché sua moglie possa vivere in una città all'estero.","why":"Persona diversa (sua moglie), quindi solo *damit*; *kann* va proprio alla fine.","source":"damit"},{"label":"3","lead":"Seine Kinder können eine gute Schule besuchen.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.**","en":"Yaroslav è venuto in Svizzera affinché i suoi figli possano frequentare una buona scuola.","why":"Persona diversa (i suoi figli): *damit … besuchen können*.","source":"damit"},{"label":"4","lead":"Das ganze Programmiererteam ist in Zug.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.**","en":"Yaroslav è venuto in Svizzera affinché tutto il team di programmatori sia a Zugo.","why":"Soggetto diverso (il team): *damit … ist*.","source":"damit"}]},{"no":"10","tag":"B1","instruction":"Warum steht Yaroslav früh auf? Lesen Sie und markieren Sie wie im Beispiel. Ergänzen Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"Perché Yaroslav si alza presto? Guarda chi fa la seconda azione. Stessa persona: scrivi sia *damit* sia *um … zu*. Persona diversa: funziona solo *damit*.","example":[{"label":"A","lead":"Yaroslav steht früh auf. Er will vor der Arbeit joggen.","text":"Yaroslav steht früh auf, **damit er vor der Arbeit joggen kann**. / Yaroslav steht früh auf, **um vor der Arbeit zu joggen**."},{"label":"B","lead":"Yaroslav steht früh auf. Seine Kinder sollen pünktlich aus dem Haus gehen.","text":"Yaroslav steht früh auf, **damit seine Kinder pünktlich aus dem Haus gehen**."}],"items":[{"label":"A2","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, damit ___.","gaps":[["er in Ruhe seinen Kaffee trinken kann","er seinen Kaffee in Ruhe trinken kann"]],"solution":"Yaroslav steht früh auf, damit **er in Ruhe seinen Kaffee trinken kann**.","en":"Yaroslav si alza presto per poter bere il caffè in pace.","why":"Stessa persona (*er*). *will* diventa *kann* nella frase con *damit*; il verbo va alla fine.","source":"damit"},{"label":"A3","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, ___.","gaps":[["um in Ruhe seinen Kaffee zu trinken","um seinen Kaffee in Ruhe zu trinken"]],"solution":"Yaroslav steht früh auf, **um in Ruhe seinen Kaffee zu trinken**.","en":"Yaroslav si alza presto per bere il caffè in pace.","why":"Stessa persona, quindi funziona anche *um … zu*: niente soggetto, niente *will*.","source":"g6865"},{"label":"B2","lead":"Yaroslav steht früh auf. Das Badezimmer soll dann für die Familie frei sein.","text":"Yaroslav steht früh auf, ___.","gaps":[["damit das Badezimmer dann für die Familie frei ist","damit das Badezimmer für die Familie frei ist"]],"solution":"Yaroslav steht früh auf, **damit das Badezimmer dann für die Familie frei ist**.","en":"Yaroslav si alza presto perché poi il bagno sia libero per la famiglia.","why":"Soggetto diverso (*das Badezimmer*): solo *damit*. *soll* cade: *damit … frei ist*.","source":"damit"}]},{"no":"11","tag":"B1","instruction":"Eine typische Woche von Marcello und seiner Familie. Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"Una settimana tipo di Marcello (A), di sua moglie (B) e dei loro figli (C). Unisci ogni coppia in una sola frase. Usa *um … zu* quando la persona è la stessa, altrimenti *damit*. Dove vanno bene tutti e due, è accettato l'uno o l'altro.","example":[{"label":"A1","lead":"Ich gehe am Morgen früh zur Arbeit. Ich möchte am Abend nicht so spät nach Hause kommen.","text":"Ich gehe am Morgen früh zur Arbeit, **damit ich am Abend nicht so spät nach Hause komme**. / Ich gehe am Morgen früh zur Arbeit, **um am Abend nicht so spät nach Hause zu kommen**."}],"items":[{"label":"A2","lead":"Marcello: Ich fahre einmal pro Woche zum Supermarkt. Meine Frau muss die schweren Einkäufe nicht machen.","text":"","accept":["Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss."],"solution":"**Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss.**","en":"Vado al supermercato una volta alla settimana perché mia moglie non debba fare la spesa pesante.","why":"Persona diversa (*meine Frau*): solo *damit*. Qui *muss* resta, perché porta il significato (*nicht machen muss* = non deve).","source":"damit"},{"label":"B1","lead":"Frau: Ich koche am Mittag zu Hause. Die Kinder sollen etwas Warmes zu essen haben, wenn sie von der Schule kommen.","text":"","accept":["Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen."],"solution":"**Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen.**","en":"A mezzogiorno cucino a casa perché i bambini abbiano qualcosa di caldo da mangiare quando tornano da scuola.","why":"Persona diversa (*die Kinder*): *damit*; *sollen* cade.","source":"damit"},{"label":"B2","lead":"Frau: Ich verbessere mein Deutsch in einem Sprachkurs. Ich will im Alltag gut zurechtkommen.","text":"","accept":["Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.","Ich verbessere mein Deutsch in einem Sprachkurs, damit ich im Alltag gut zurechtkomme."],"solution":"**Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.**","en":"Miglioro il mio tedesco in un corso di lingua per cavarmela bene nella vita di tutti i giorni.","why":"Stessa persona: vanno bene tutti e due. *zurechtkommen* è separabile: *zurecht**zu**kommen*. *will* cade.","source":"g6865"},{"label":"C1","lead":"Kinder: Wir lernen nach der Schule viel am Nachmittag. Wir wollen gute Noten haben und einen guten Abschluss machen.","text":"","accept":["Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.","Wir lernen nach der Schule viel am Nachmittag, damit wir gute Noten haben und einen guten Abschluss machen."],"solution":"**Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.**","en":"Il pomeriggio dopo la scuola studiamo molto per avere bei voti e fare un buon diploma.","why":"Stessa persona (*wir*): vanno bene tutti e due. Con due verbi, ognuno ha il suo *zu*.","source":"g6865"},{"label":"C2","lead":"Kinder: Wir helfen im Haushalt. Mama soll nicht alles allein machen.","text":"","accept":["Wir helfen im Haushalt, damit Mama nicht alles allein macht.","Wir helfen im Haushalt, damit Mama nicht alles allein machen muss."],"solution":"**Wir helfen im Haushalt, damit Mama nicht alles allein macht.**","en":"Aiutiamo nelle faccende di casa perché la mamma non faccia tutto da sola.","why":"Persona diversa (*Mama*): solo *damit*; *soll* cade.","source":"damit"}]}]},{"page":"AB 154","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Voglio essere al negozio per poter aspettare lì.","exercises":[{"no":"12","tag":"B1","marker":"◇","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Che cosa è giusto? Scrivi *um* o *damit*. Guarda la fine della frase: *zu* + infinito vuole *um*; un verbo coniugato alla fine vuole *damit*.","example":[{"label":"a","text":"Frau Alt betreut ihre Enkel zu Hause, **damit** ihre Tochter berufstätig sein kann."}],"items":[{"label":"b","text":"Jaime lernt und arbeitet viel, ___ sich bald selbstständig zu machen.","gaps":[["um"]],"solution":"Jaime lernt und arbeitet viel, **um** sich bald selbstständig zu machen.","en":"Jaime studia e lavora molto per mettersi presto in proprio.","why":"*zu machen* alla fine → *um*.","source":"g6865"},{"label":"c","text":"Said lernt neben Deutsch auch Englisch, ___ bessere Chancen auf dem Arbeitsmarkt zu haben.","gaps":[["um"]],"solution":"Said lernt neben Deutsch auch Englisch, **um** bessere Chancen auf dem Arbeitsmarkt zu haben.","en":"Oltre al tedesco Said impara anche l'inglese per avere migliori possibilità sul mercato del lavoro.","why":"*zu haben* alla fine → *um*.","source":"g6865"},{"label":"d","text":"Irina arbeitet jetzt Vollzeit, ___ ihr Mann eine teure Weiterbildung machen kann.","gaps":[["damit"]],"solution":"Irina arbeitet jetzt Vollzeit, **damit** ihr Mann eine teure Weiterbildung machen kann.","en":"Adesso Irina lavora a tempo pieno affinché suo marito possa fare un corso di perfezionamento costoso.","why":"Nuovo soggetto *ihr Mann* e *kann* alla fine → *damit*.","source":"damit"},{"label":"e","text":"Herr Pfister bezahlt viel Geld, ___ seine Eltern von einer privaten Pflegehelferin gepflegt werden.","gaps":[["damit"]],"solution":"Herr Pfister bezahlt viel Geld, **damit** seine Eltern von einer privaten Pflegehelferin gepflegt werden.","en":"Il signor Pfister paga molti soldi affinché i suoi genitori siano assistiti da un'aiutante di cura privata.","why":"Nuovo soggetto *seine Eltern*, passivo *gepflegt werden* alla fine → *damit*.","source":"damit"}]},{"no":"13","tag":"B1","marker":"◆","instruction":"Wozu macht Marcello das?","instruction_en":"Perché Marcello fa questo?","part":"a","part_instruction":"Verbinden Sie.","part_instruction_en":"Abbina ogni cosa che fa Marcello (1–6) alla persona che ne trae vantaggio (*Er, Seine Frau, Sein Team*) e allo scopo (a–f). Scrivi la persona, poi la lettera.","phrases":["Er","Seine Frau","Sein Team","a soll abends etwas Ruhe haben.","b kann das gemeinsame Projekt pünktlich abschliessen.","c will wochentags früher gehen.","d kann tagsüber die Einkäufe mit dem Auto erledigen.","e kann ungestört seinen Arbeitstag planen.","f will fit bleiben."],"example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen. → **Er**, **f**"}],"items":[{"label":"2","text":"Er ist als Erster im Büro. → ___, ___","gaps":[["Er"],["e"]],"solution":"Er ist als Erster im Büro. → **Er**, **e**","en":"È il primo in ufficio. → Lui, e (può pianificare la sua giornata di lavoro senza essere disturbato).","why":"Un ufficio vuoto significa nessuna interruzione.","source":"hueber"},{"label":"3","text":"Er lässt das Auto zu Hause. → ___, ___","gaps":[["Seine Frau"],["d"]],"solution":"Er lässt das Auto zu Hause. → **Seine Frau**, **d**","en":"Lascia l'auto a casa. → Sua moglie, d (può fare la spesa in auto durante il giorno).","why":"Se lui non prende l'auto, sua moglie può usarla.","source":"hueber"},{"label":"4","text":"Er macht manchmal Überstunden. → ___, ___","gaps":[["Sein Team"],["b"]],"solution":"Er macht manchmal Überstunden. → **Sein Team**, **b**","en":"A volte fa gli straordinari. → Il suo team, b (può finire in tempo il progetto comune).","why":"Gli straordinari aiutano il progetto comune.","source":"hueber"},{"label":"5","text":"Er arbeitet auch mal am Samstag. → ___, ___","gaps":[["Er"],["c"]],"solution":"Er arbeitet auch mal am Samstag. → **Er**, **c**","en":"A volte lavora anche il sabato. → Lui, c (vuole uscire prima nei giorni feriali).","why":"Lavorando il sabato si guadagna giornate feriali più corte.","source":"hueber"},{"label":"6","text":"Er bringt die Kinder ins Bett. → ___, ___","gaps":[["Seine Frau"],["a"]],"solution":"Er bringt die Kinder ins Bett. → **Seine Frau**, **a**","en":"Mette a letto i bambini. → Sua moglie, a (deve avere un po' di pace la sera).","why":"La sera per lei è tranquilla.","source":"hueber"}]},{"no":"13","part":"b","part_instruction":"Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","part_instruction_en":"Scrivi frasi con le tue risposte di a. Stessa persona (*Er*): *um … zu* o *damit*. Un'altra persona: solo *damit*. Togli *will* e *soll*.","example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen, **damit er fit bleibt**. / Marcello geht dreimal pro Woche joggen, **um fit zu bleiben**."}],"items":[{"label":"2","lead":"Er ist als Erster im Büro. / Er kann ungestört seinen Arbeitstag planen.","text":"","accept":["Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.","Er ist als Erster im Büro, damit er ungestört seinen Arbeitstag planen kann.","Marcello ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen."],"solution":"**Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.**","en":"È il primo in ufficio per pianificare la sua giornata di lavoro senza essere disturbato.","why":"Stessa persona: vanno bene tutti e due.","source":"g6865"},{"label":"3","lead":"Er lässt das Auto zu Hause. / Seine Frau kann tagsüber die Einkäufe mit dem Auto erledigen.","text":"","accept":["Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann."],"solution":"**Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann.**","en":"Lascia l'auto a casa affinché sua moglie possa fare la spesa in auto durante il giorno.","why":"Altra persona: solo *damit*.","source":"damit"},{"label":"4","lead":"Er macht manchmal Überstunden. / Sein Team kann das gemeinsame Projekt pünktlich abschliessen.","text":"","accept":["Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann."],"solution":"**Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann.**","en":"A volte fa gli straordinari affinché il suo team possa finire in tempo il progetto comune.","why":"Altro soggetto: solo *damit*.","source":"damit"},{"label":"5","lead":"Er arbeitet auch mal am Samstag. / Er will wochentags früher gehen.","text":"","accept":["Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.","Er arbeitet auch mal am Samstag, damit er wochentags früher gehen kann."],"solution":"**Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.**","en":"A volte lavora anche il sabato per uscire prima nei giorni feriali.","why":"Stessa persona: vanno bene tutti e due; *will* cade.","source":"g6865"},{"label":"6","lead":"Er bringt die Kinder ins Bett. / Seine Frau soll abends etwas Ruhe haben.","text":"","accept":["Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat."],"solution":"**Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat.**","en":"Mette a letto i bambini perché sua moglie abbia un po' di pace la sera.","why":"Altra persona: *damit*; *soll* cade.","source":"damit"}]},{"no":"14","tag":"B3","instruction":"Beruf und Karriere – was ist wichtig, um Erfolg im Job zu haben? Markieren Sie noch fünf Wörter und ordnen Sie zu.","instruction_en":"Lavoro e carriera: che cosa conta per avere successo sul lavoro? Trova altre cinque parole nella griglia di lettere e completa le frasi. *Kompetenzen* è l'esempio. Scrivi gli aggettivi in minuscolo.","reading":[{"label":"Buchstabengitter","text":"DLKJLDGDKJLKDLGKOMPETENZENLLSKOMMUNIKATIVEDJG\nLSKDENGAGEMENTJGKDÖLGÖGLLKGLKONFLIKTFÄHIGLÖFJA\nFLAGJSTEAMFÄHIGJGSLGJSLMOTIVATIONSLGSLKGDJAFJFLA"}],"example":[{"label":"a","text":"Personalfachleute sagen: Man braucht nicht nur fachliche, sondern auch soziale **Kompetenzen**, wenn man im Beruf erfolgreich sein will."}],"items":[{"label":"b","text":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie ___.","gaps":[["teamfähig"]],"solution":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie **teamfähig**.","en":"Per esempio è importante che una persona sappia lavorare bene in squadra e scenda anche a compromessi. Allora sa lavorare in team.","why":"*teamfähig* = capace di lavorare in team.","source":"hueber"},{"label":"c","text":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie ___.","gaps":[["konfliktfähig"]],"solution":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie **konfliktfähig**.","en":"Se dei colleghi litigano ma alla fine trovano insieme una buona soluzione al loro problema, allora sanno gestire i conflitti.","why":"*konfliktfähig* = capace di gestire i conflitti.","source":"hueber"},{"label":"d","text":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute ___ Kompetenzen.","gaps":[["kommunikative"]],"solution":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute **kommunikative** Kompetenzen.","en":"Chi è aperto, sa conversare bene con le persone ma sa anche ascoltare bene, ha buone competenze comunicative.","why":"Aggettivo prima di un sostantivo plurale dopo *gute*: *kommunikative Kompetenzen*.","source":"hueber"},{"label":"e","text":"Auf jeden Fall muss ein Mitarbeiter ___ und ___ zeigen, um im Beruf erfolgreich zu sein.","gaps":[["Motivation","Engagement"],["Engagement","Motivation"]],"solution":"Auf jeden Fall muss ein Mitarbeiter **Motivation** und **Engagement** zeigen, um im Beruf erfolgreich zu sein.","en":"In ogni caso un collaboratore deve mostrare motivazione e impegno per avere successo sul lavoro.","why":"*die Motivation* e *das Engagement* (impegno); in qualsiasi ordine.","source":"hueber"}]}]},{"page":"AB 155","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"Fare qualcosa invece di sognare soltanto","exercises":[{"no":"15","tag":"C1","instruction":"Unzufrieden im Job","instruction_en":"Scontento al lavoro","part":"a","part_instruction":"In welchem Satz steht *nicht/kein*? Markieren Sie.","part_instruction_en":"Confronta le due frasi brevi con quella lunga. Quale parola per \"non / nessuno\" sparisce nella versione con *statt … zu* o *ohne … zu*? Scrivila.","example":[{"label":"1","text":"Ich bringe lieber meinen eigenen Laptop mit. Ich benütze **nicht** den alten Computer in der Firma. / Ich bringe lieber meinen eigenen Laptop mit, statt den alten Computer in der Firma zu benützen."}],"items":[{"label":"2","text":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → ___","gaps":[["keinen","kein"]],"solution":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → **keinen**","en":"Il capo è sempre di cattivo umore. Non ha nessun motivo. / Il capo è sempre di cattivo umore senza avere un motivo. → keinen","why":"*ohne* significa già \"non\": *keinen Grund* diventa *einen Grund* dopo *ohne*.","source":"komma"}]},{"no":"15","part":"b","part_instruction":"Welche Sätze sind richtig? Vergleichen Sie mit a und kreuzen Sie an.","part_instruction_en":"Quale finale è giusto? Le due possibilità sono indicate sopra ogni frase. Scrivi il finale giusto.","items":[{"label":"1","lead":"statt mich weiter über die Arbeit zu ärgern / statt mich nicht weiter über die Arbeit zu ärgern","text":"Ich wechsle den Job, ___.","gaps":[["statt mich weiter über die Arbeit zu ärgern"]],"solution":"Ich wechsle den Job, **statt mich weiter über die Arbeit zu ärgern**.","en":"Cambio lavoro invece di continuare ad arrabbiarmi per il lavoro.","why":"Niente *nicht* dopo *statt*: *statt* dice già \"non questo\".","source":"komma"},{"label":"2","lead":"ohne den Chef nicht zu informieren / ohne den Chef zu informieren","text":"Ich suche eine neue Stelle, ___.","gaps":[["ohne den Chef zu informieren"]],"solution":"Ich suche eine neue Stelle, **ohne den Chef zu informieren**.","en":"Cerco un nuovo posto senza informare il capo.","why":"Niente *nicht* dopo *ohne*: *ohne den Chef nicht zu informieren* significherebbe il contrario.","source":"komma"}]},{"no":"16","tag":"C1","instruction":"Homeoffice. Ergänzen Sie die Sätze mit *statt … zu*.","instruction_en":"Lavorare da casa. Trasforma la seconda parte (la cosa che non fai) in *statt … zu* + infinito. Togli *nicht / keine*.","example":[{"label":"a","lead":"Sie können bei der Arbeit eine bequeme Sporthose tragen und müssen keine unbequeme Berufskleidung anziehen.","text":"Sie können bei der Arbeit eine bequeme Sporthose tragen, **statt unbequeme Berufskleidung anzuziehen**."}],"items":[{"label":"b","lead":"Sie haben flexible Arbeitszeiten und arbeiten nicht von 9 bis 17 Uhr.","text":"Sie haben flexible Arbeitszeiten, ___.","gaps":[["statt von 9 bis 17 Uhr zu arbeiten"]],"solution":"Sie haben flexible Arbeitszeiten, **statt von 9 bis 17 Uhr zu arbeiten**.","en":"Hai orari di lavoro flessibili invece di lavorare dalle 9 alle 17.","why":"*nicht* sparisce; *zu arbeiten* va per ultimo.","source":"komma"},{"label":"c","lead":"Sie haben keine Fahrtkosten und geben nicht viel Geld für Benzin aus.","text":"Sie haben keine Fahrtkosten, ___.","gaps":[["statt viel Geld für Benzin auszugeben"]],"solution":"Sie haben keine Fahrtkosten, **statt viel Geld für Benzin auszugeben**.","en":"Non hai spese di viaggio invece di spendere molti soldi per la benzina.","why":"*ausgeben* è separabile: *aus**zu**geben*.","source":"komma"},{"label":"d","lead":"Sie räumen die Wohnung auf und arbeiten nicht.","text":"Sie räumen die Wohnung auf, ___.","gaps":[["statt zu arbeiten"]],"solution":"Sie räumen die Wohnung auf, **statt zu arbeiten**.","en":"Metti in ordine l'appartamento invece di lavorare.","why":"Ad *arbeiten* non appartiene nient'altro, quindi il gruppo è solo *statt zu arbeiten*.","source":"komma"},{"label":"e","lead":"Sie müssen viele Probleme allein lösen und besprechen sie nicht mit Kollegen.","text":"Sie müssen viele Probleme allein lösen, ___.","gaps":[["statt sie mit Kollegen zu besprechen"]],"solution":"Sie müssen viele Probleme allein lösen, **statt sie mit Kollegen zu besprechen**.","en":"Devi risolvere molti problemi da solo invece di discuterne con i colleghi.","why":"*sie* = i problemi; resta dentro il gruppo.","source":"komma"}]},{"no":"17","tag":"C2","instruction":"Meine fleissige Arbeitskollegin Olga. Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"La mia collega instancabile Olga. Unisci le due frasi. Qualcosa che fa *invece di* qualcos'altro → *statt … zu*. Qualcosa che non succede *nello stesso momento* → *ohne … zu*. Togli *nicht / kein*.","example":[{"label":"a","lead":"Sie steht jeden Tag um fünf Uhr auf. Sie beschwert sich nicht.","text":"Sie steht jeden Tag um fünf Uhr auf, **ohne sich zu beschweren**."}],"items":[{"label":"b","lead":"Sie kommt schon um 7 Uhr ins Büro. Sie fängt nicht erst um 9 Uhr an.","text":"","accept":["Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen."],"solution":"**Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen.**","en":"Arriva in ufficio già alle 7 invece di cominciare solo alle 9.","why":"Le 7 sostituiscono le 9 → *statt*. *anfangen*: *an**zu**fangen*.","source":"komma"},{"label":"c","lead":"Sie fährt immer mit dem Velo zur Arbeit. Sie nimmt nicht das Auto.","text":"","accept":["Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen."],"solution":"**Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen.**","en":"Va sempre al lavoro in bicicletta invece di prendere l'auto.","why":"La bici sostituisce l'auto → *statt*. (*das Velo* = parola svizzera per bicicletta.)","source":"komma"},{"label":"d","lead":"Sie geht in der Mittagszeit joggen. Sie isst nicht.","text":"","accept":["Sie geht in der Mittagszeit joggen, statt etwas zu essen.","Sie geht in der Mittagszeit joggen, statt zu essen.","Sie geht in der Mittagszeit joggen, ohne etwas zu essen.","Sie geht in der Mittagszeit joggen, ohne zu essen."],"solution":"**Sie geht in der Mittagszeit joggen, statt etwas zu essen.**","en":"Nella pausa di mezzogiorno va a fare jogging invece di mangiare qualcosa.","why":"Il jogging sostituisce il pranzo → *statt*.","source":"komma","check":"La soluzione ufficiale ha *statt etwas zu essen*. Anche *ohne etwas zu essen* (fa jogging e non mangia niente) è tedesco corretto e qui significa quasi lo stesso."},{"label":"e","lead":"Sie arbeitet viele Stunden am Stück. Sie macht keine Pause.","text":"","accept":["Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.","Sie arbeitet viele Stunden am Stück, ohne Pause zu machen."],"solution":"**Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.**","en":"Lavora per molte ore di fila senza fare una pausa.","why":"Mentre lavora non c'è nessuna pausa → *ohne*. *keine Pause* diventa *eine Pause*.","source":"komma"},{"label":"f","lead":"Sie sollte sich mehr um sich selbst kümmern. Sie arbeitet so viel.","text":"","accept":["Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten."],"solution":"**Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten.**","en":"Dovrebbe occuparsi di più di sé stessa invece di lavorare così tanto.","why":"Prendersi cura di sé dovrebbe sostituire il lavorare così tanto → *statt*.","source":"komma"}]}]},{"page":"AB 156","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"Fare qualcosa invece di sognare soltanto","exercises":[{"no":"18","tag":"C2","marker":"◇","instruction":"Morgengewohnheiten. Was ist richtig? Kreuzen Sie an.","instruction_en":"Abitudini del mattino. Scrivi *ohne* o *statt*. *statt* = invece di (una cosa ne sostituisce un'altra); *ohne* = senza (qualcosa non succede nello stesso momento).","example":[{"label":"a","text":"Ich fahre zu jeder Jahreszeit mit dem Velo zur Arbeit, **statt** das Auto zu nehmen."}],"items":[{"label":"b","text":"Ich dusche am Morgen immer kalt, ___ warm zu baden.","gaps":[["statt"]],"solution":"Ich dusche am Morgen immer kalt, **statt** warm zu baden.","en":"La mattina faccio sempre la doccia fredda invece di fare un bagno caldo.","why":"Una doccia fredda sostituisce un bagno caldo.","source":"komma"},{"label":"c","text":"Ich trinke nie Kaffee, ___ Zeitung zu lesen.","gaps":[["ohne"]],"solution":"Ich trinke nie Kaffee, **ohne** Zeitung zu lesen.","en":"Non bevo mai il caffè senza leggere il giornale.","why":"*nie … ohne* = ogni volta che bevo il caffè, leggo il giornale.","source":"komma"},{"label":"d","text":"Ich gehe nie aus dem Haus, ___ meinen Regenschirm mitzunehmen.","gaps":[["ohne"]],"solution":"Ich gehe nie aus dem Haus, **ohne** meinen Regenschirm mitzunehmen.","en":"Non esco mai di casa senza prendere l'ombrello.","why":"*nie … ohne* = lo prendo sempre.","source":"komma"},{"label":"e","text":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, ___ sofort aufzustehen.","gaps":[["statt"]],"solution":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, **statt** sofort aufzustehen.","en":"La mattina, dopo essermi svegliato, resto sempre a letto ancora mezz'ora invece di alzarmi subito.","why":"Restare a letto sostituisce l'alzarsi.","source":"komma"}]},{"no":"19","tag":"C2","marker":"◆","instruction":"Was würden Sie in Ihrem Leben gern machen? Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"Che cosa ti piacerebbe fare nella vita? Combina un desiderio della parte sinistra del riquadro con qualcosa della parte destra, usando *ohne … zu* o *statt … zu*. Le parole cancellate sono usate nell'esempio. La risposta modello è una delle possibilità.","box":["beruflich selbstständig sein","mehr Geld verdienen","kaputte Sachen reparieren","eine Wohnung kaufen","mit meiner Familie in der Heimat telefonieren","gut Deutsch sprechen","mit dem Velo fahren","mit meiner Familie zusammenwohnen","…","viele Sprachkurse machen","immer zu Fuss gehen","allein leben","viel Geld ausgeben","sie in den Abfall werfen","Heimweh haben","jeden Franken sparen müssen","ein finanzielles Risiko eingehen","…"],"box_used":[0,16],"example":[{"label":"Beispiel","text":"Ich wäre gern beruflich selbstständig, **ohne ein finanzielles Risiko einzugehen**. Ich würde gern …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gern mehr Geld verdienen, statt jeden Franken sparen zu müssen. Ich würde gern kaputte Sachen reparieren, statt sie in den Abfall zu werfen. Ich würde gern mit meiner Familie in der Heimat telefonieren, ohne Heimweh zu haben. Ich würde gern mit dem Velo fahren, statt immer zu Fuss zu gehen. Ich würde gern gut Deutsch sprechen, ohne viele Sprachkurse zu machen. Ich würde gern mit meiner Familie zusammenwohnen, statt allein zu leben.","en":"Mi piacerebbe guadagnare di più invece di dover risparmiare ogni franco. Mi piacerebbe riparare le cose rotte invece di buttarle nella spazzatura. Mi piacerebbe telefonare alla mia famiglia nel mio paese senza avere nostalgia. Mi piacerebbe andare in bicicletta invece di andare sempre a piedi. Mi piacerebbe parlare bene il tedesco senza fare tanti corsi di lingua. Mi piacerebbe vivere con la mia famiglia invece di vivere da solo.","why":"Desiderio con *würde gern* / *wäre gern*, poi *statt … zu* (sostituzione) o *ohne … zu* (non succede). Con un modale: *sparen **zu müssen***.","source":"hueber"}]},{"no":"20","tag":"C3","instruction":"Unglücklich im neuen Job – Ratschläge für eine Freundin","instruction_en":"Scontenta nel nuovo lavoro: consigli per un'amica","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Completa i consigli con le espressioni del riquadro. Ognuna si usa una volta; *Wie wäre es, wenn* è usata nell'esempio.","box":["An deiner Stelle","Du könntest zum Beispiel","Ich kann dir nur raten","Wie wäre es, wenn","Wie findest du die Idee","solltest du vielleicht"],"box_used":[3],"box_exact":true,"example":[{"label":"1","text":"**Wie wäre es, wenn** du mit deinen Kollegen zusammen Mittagspause machen würdest, statt allein zu essen?"}],"items":[{"label":"2","text":"Wenn du Kollegen besser kennenlernen möchtest, ___ öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","gaps":[["solltest du vielleicht"]],"solution":"Wenn du Kollegen besser kennenlernen möchtest, **solltest du vielleicht** öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","en":"Se vuoi conoscere meglio i colleghi, forse dovresti passare più spesso durante il giorno nella cucina del caffè. Lì puoi chiacchierare in modo rilassato con tutti senza disturbarli al lavoro.","why":"Dopo la frase con *wenn* il verbo viene per primo: *…, solltest du vielleicht …*; *gehen* va alla fine.","source":"hueber"},{"label":"3","text":"___, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","gaps":[["Wie findest du die Idee"]],"solution":"**Wie findest du die Idee**, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","en":"Che ne pensi dell'idea di portare un giorno una torta per i colleghi del tuo reparto e festeggiare il tuo primo mese nella nuova ditta? Una torta fa piacere a tutti.","why":"*Wie findest du die Idee, … zu …?* è una domanda con *zu* + infinito.","source":"g6865"},{"label":"4","text":"___ würde ich überallhin gehen, wo man Kollegen treffen kann. ___ am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","gaps":[["An deiner Stelle"],["Du könntest zum Beispiel"]],"solution":"**An deiner Stelle** würde ich überallhin gehen, wo man Kollegen treffen kann. **Du könntest zum Beispiel** am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","en":"Al posto tuo andrei ovunque si possano incontrare i colleghi. Potresti per esempio partecipare al programma sportivo aziendale. Lì conosci anche persone di altri reparti.","why":"*An deiner Stelle würde ich …* (se fossi in te); *Du könntest zum Beispiel …* + infinito alla fine.","source":"hueber"},{"label":"5","text":"___, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","gaps":[["Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten**, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","en":"Posso solo consigliarti di essere aperta e di pensare positivo. Vedrai, tra qualche settimana starai già meglio.","why":"*Ich kann dir nur raten, … zu …*: il consiglio arriva come *zu* + infinito.","source":"g6865"}]},{"no":"20","part":"b","part_instruction":"Schreiben Sie zwei weitere Ratschläge.","part_instruction_en":"Scrivi altri due consigli per l'amica. La risposta modello è una delle possibilità.","example":[{"label":"Beispiel","text":"Ich kann dir nur raten, …"}],"items":[{"label":"1","lead":"Ihre Ratschläge","text":"","open":true,"solution":"Ich kann dir nur raten, mit deiner Chefin zu sprechen. Wie findest du die Idee, dich nach der Arbeit mit deinen Kollegen zu verabreden?","en":"Posso solo consigliarti di parlare con la tua capa. Che ne pensi dell'idea di darti appuntamento con i colleghi dopo il lavoro?","why":"Entrambe le espressioni vogliono *zu* + infinito alla fine; con un verbo riflessivo il pronome resta dentro: *dich … zu verabreden*.","source":"g6865"}]}]},{"page":"AB 157","heading":"D  Verkaufsgespräche","heading_en":"Conversazioni di vendita","exercises":[{"no":"21","tag":"D3","instruction":"Ich hätte gern …","instruction_en":"Vorrei …","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie: Kundin (K), Verkäuferin (V).","part_instruction_en":"Chi dice che cosa? Scrivi *K* per la cliente (*Kundin*) o *V* per la commessa (*Verkäuferin*).","example":[{"label":"4 / c","text":"Vielen Dank für Ihre Hilfe. → **K** / Vielen Dank für Ihre Beratung. → **K**"}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … empfehlen? → **V**","en":"Posso consigliarle …? → commessa","why":"Consigliare è il compito di chi vende.","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["K","Kundin"]],"solution":"Das muss ich mir noch überlegen. → **K**","en":"Ci devo ancora pensare. → cliente","why":"La cliente non ha ancora deciso.","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["V","Verkäuferin"]],"solution":"Brauchen Sie Hilfe? → **V**","en":"Ha bisogno di aiuto? → commessa","why":"Offrire aiuto.","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["V","Verkäuferin"]],"solution":"Was wünschen Sie? → **V**","en":"Che cosa desidera? → commessa","why":"La commessa chiede che cosa vuoi.","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["K","Kundin"]],"solution":"Entschuldigung, ist es möglich, …? → **K**","en":"Scusi, è possibile …? → cliente","why":"La cliente chiede qualcosa.","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie noch einen Wunsch? → **V**","en":"Desidera ancora qualcosa? → commessa","why":"Si chiede verso la fine di una vendita.","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["K","Kundin"]],"solution":"Ich bin auf der Suche nach … → **K**","en":"Sto cercando … → cliente","why":"La cliente dice di che cosa ha bisogno.","source":"hueber"},{"label":"a","text":"Ich hätte gern … → ___","gaps":[["K","Kundin"]],"solution":"Ich hätte gern … → **K**","en":"Vorrei … → cliente","why":"Modo cortese per chiedere qualcosa (Konjunktiv II).","source":"hueber"},{"label":"b","text":"Wie kann ich Ihnen helfen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Wie kann ich Ihnen helfen? → **V**","en":"Come posso aiutarla? → commessa","why":"Offrire aiuto.","source":"hueber"},{"label":"d","text":"Haben Sie einen bestimmten Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie einen bestimmten Wunsch? → **V**","en":"Cerca qualcosa in particolare? → commessa","why":"La commessa chiede che cosa vuoi.","source":"hueber"},{"label":"e","text":"Darf ich Ihnen … anbieten? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … anbieten? → **V**","en":"Posso offrirle …? → commessa","why":"Offrire qualcosa.","source":"hueber"},{"label":"f","text":"Ich kann mich noch nicht entscheiden. → ___","gaps":[["K","Kundin"]],"solution":"Ich kann mich noch nicht entscheiden. → **K**","en":"Non riesco ancora a decidermi. → cliente","why":"La cliente non ha deciso.","source":"hueber"},{"label":"g","text":"Dürfte ich Sie etwas fragen? Kann man … → ___","gaps":[["K","Kundin"]],"solution":"Dürfte ich Sie etwas fragen? Kann man … → **K**","en":"Potrei chiederle una cosa? Si può …? → cliente","why":"Domanda cortese (Konjunktiv II *dürfte*).","source":"hueber"},{"label":"h","text":"Möchten Sie sonst noch etwas? → ___","gaps":[["V","Verkäuferin"]],"solution":"Möchten Sie sonst noch etwas? → **V**","en":"Desidera qualcos'altro? → commessa","why":"Si chiede verso la fine di una vendita.","source":"hueber"}]},{"no":"21","part":"b","part_instruction":"Wie kann man auch sagen? Verbinden Sie die Sätze in a.","part_instruction_en":"Quale frase a destra (a–h) significa lo stesso di ogni frase a sinistra? Scrivi la lettera.","phrases":["a Ich hätte gern …","b Wie kann ich Ihnen helfen?","c Vielen Dank für Ihre Beratung.","d Haben Sie einen bestimmten Wunsch?","e Darf ich Ihnen … anbieten?","f Ich kann mich noch nicht entscheiden.","g Dürfte ich Sie etwas fragen? Kann man …","h Möchten Sie sonst noch etwas?"],"example":[{"label":"4","text":"Vielen Dank für Ihre Hilfe. → **c** Vielen Dank für Ihre Beratung."}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["e"]],"solution":"Darf ich Ihnen … empfehlen? → **e**","en":"Posso consigliarle …? → e Posso offrirle …?","why":"Entrambe propongono qualcosa alla cliente.","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["f"]],"solution":"Das muss ich mir noch überlegen. → **f**","en":"Ci devo ancora pensare. → f Non riesco ancora a decidermi.","why":"Entrambe dicono: non ho ancora deciso.","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["b"]],"solution":"Brauchen Sie Hilfe? → **b**","en":"Ha bisogno di aiuto? → b Come posso aiutarla?","why":"Entrambe offrono aiuto.","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["d"]],"solution":"Was wünschen Sie? → **d**","en":"Che cosa desidera? → d Cerca qualcosa in particolare?","why":"Entrambe chiedono che cosa vuole la cliente.","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["g"]],"solution":"Entschuldigung, ist es möglich, …? → **g**","en":"Scusi, è possibile …? → g Potrei chiederle una cosa? Si può …?","why":"Entrambe sono domande cortesi della cliente.","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["h"]],"solution":"Haben Sie noch einen Wunsch? → **h**","en":"Desidera ancora qualcosa? → h Desidera qualcos'altro?","why":"Entrambe chiedono se la cliente vuole altro.","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["a"]],"solution":"Ich bin auf der Suche nach … → **a**","en":"Sto cercando … → a Vorrei …","why":"Entrambe dicono che cosa vuole la cliente.","source":"hueber"}]}]},{"page":"AB 158","heading":"E  Reklamation","heading_en":"Reclami","exercises":[{"no":"23","tag":"E2","instruction":"Ergänzen Sie.","instruction_en":"Completa le frasi tratte da lettere di reclamo. Il libro dà alcune lettere di ogni parola (indicate sopra la frase); scrivi la parola intera. (L'esercizio 22 è un ascolto ed è omesso.)","items":[{"label":"a","lead":"f _ _ _ _ _ _  …  _ _ _","text":"Ich ___ Sie jetzt zum letzten Mal ___, mir bis 31.03. zu antworten.","gaps":[["fordere"],["auf"]],"solution":"Ich **fordere** Sie jetzt zum letzten Mal **auf**, mir bis 31.03. zu antworten.","en":"Vi invito per l'ultima volta a rispondermi entro il 31.03.","why":"*jemanden auffordern, … zu …* = invitare / intimare a qualcuno di …; separabile: *ich fordere … auf*.","source":"hueber"},{"label":"b","lead":"S _ _ _ _ _ _ _  /  E _ _ _ _ _  /  A _ s p _ _ _ _","text":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. ___ Sie mir bitte einen ___. Ich habe ___ auf eine neue Uhr.","gaps":[["Schicken"],["Ersatz"],["Anspruch"]],"solution":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. **Schicken** Sie mir bitte einen **Ersatz**. Ich habe **Anspruch** auf eine neue Uhr.","en":"Purtroppo l'orologio che ho comprato ieri non funziona. Vi prego di mandarmi un sostituto. Ho diritto a un orologio nuovo.","why":"*der Ersatz* = sostituto; *Anspruch haben auf* + accusativo = avere diritto a.","source":"hueber"},{"label":"c","lead":"b _ _ _ _ ä _ _ _ t","text":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … ___ ist.","gaps":[["beschädigt"]],"solution":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … **beschädigt** ist.","en":"Quando ho aperto il pacco, purtroppo ho constatato che il/la … è danneggiato/a.","why":"*beschädigt* = danneggiato.","source":"hueber"},{"label":"d","lead":"ä _ g _ _ l _ _ _","text":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr ___.","gaps":[["ärgerlich"]],"solution":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr **ärgerlich**.","en":"Vi ho già scritto due volte senza ricevere una risposta. È davvero molto fastidioso.","why":"*ärgerlich* = fastidioso.","source":"hueber"},{"label":"e","lead":"u _ _ a _ _ _ _ _ _","text":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser ___.","gaps":[["umtauschen"]],"solution":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser **umtauschen**.","en":"Il maglione è bello, però purtroppo a mio marito non va bene. Vorrei quindi cambiarlo con una taglia più grande.","why":"*umtauschen* = cambiare (in negozio).","source":"hueber"},{"label":"f","lead":"A _ _ _ o _ _","text":"Leider habe ich immer noch keine ___ erhalten.","gaps":[["Antwort"]],"solution":"Leider habe ich immer noch keine **Antwort** erhalten.","en":"Purtroppo non ho ancora ricevuto nessuna risposta.","why":"*die Antwort* = risposta.","source":"hueber"},{"label":"g","lead":"B _ _ t _ _ _ _ e _","text":"___ Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","gaps":[["Bestätigen"]],"solution":"**Bestätigen** Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","en":"Vi prego di confermarmi per iscritto di aver ricevuto il mio reclamo.","why":"*bestätigen* = confermare.","source":"hueber"},{"label":"h","lead":"v _ _ ä _ _ _ r _  /  e _ _ t _ _ _ _ _ _","text":"Ich bin sehr ___ und von Ihrem Service sehr ___.","gaps":[["verärgert"],["enttäuscht"]],"solution":"Ich bin sehr **verärgert** und von Ihrem Service sehr **enttäuscht**.","en":"Sono molto irritata e molto delusa dal vostro servizio.","why":"*verärgert* = irritato; *enttäuscht von* = deluso da.","source":"hueber"}]},{"no":"24","tag":"E2","instruction":"Eine schriftliche Reklamation","instruction_en":"Un reclamo scritto","part":"a","part_instruction":"Was bedeuten die Sätze? Ordnen Sie zu.","part_instruction_en":"Le frasi a sinistra sono come si scrive in una lettera di reclamo; il riquadro mostra come lo si direbbe nella lingua di tutti i giorni. Scrivi la lettera (a–g) con lo stesso significato.","phrases":["a Wenn ich bis … nichts gehört habe, dann will ich den/die … nicht mehr haben.","b Ich habe Ihnen schon zweimal geschrieben und gesagt, dass ich eine(n) neue(n) … möchte.","c Schade. Der/Die … ist kaputt.","d Ich sage es Ihnen jetzt noch ein letztes Mal: Bitte schicken Sie mir spätestens am … eine(n) neue(n) …","e Ich habe wirklich gedacht, dass Ihr Service viel besser ist.","f Ich bin enttäuscht, dass ich immer noch nichts von Ihnen gehört habe.","g Ich habe am 16. Februar von Ihnen … bekommen."],"example":[{"label":"2","text":"Leider ist … defekt. → **c** Schade. Der/Die … ist kaputt."}],"items":[{"label":"1","text":"Am 16.2. haben Sie mir … geliefert. → ___","gaps":[["g"]],"solution":"Am 16.2. haben Sie mir … geliefert. → **g**","en":"Il 16.2 mi avete consegnato … → g","why":"Entrambe dicono che cosa hai ricevuto e quando.","source":"hueber"},{"label":"3","text":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → ___","gaps":[["b"]],"solution":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → **b**","en":"Vi ho già scritto due volte un'e-mail chiedendovi di mandarmi un sostituto. → b","why":"*bereits* = *schon*; *Ersatz* = uno nuovo. (*das E-Mail* è l'uso svizzero.)","source":"hueber"},{"label":"4","text":"Leider habe ich immer noch keine Antwort erhalten. → ___","gaps":[["f"]],"solution":"Leider habe ich immer noch keine Antwort erhalten. → **f**","en":"Purtroppo non ho ancora ricevuto nessuna risposta. → f","why":"Ancora nessuna risposta → delusa.","source":"hueber"},{"label":"5","text":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → ___","gaps":[["e"]],"solution":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → **e**","en":"Devo dire che il vostro servizio mi ha deluso molto. → e","why":"Ti aspettavi un servizio migliore.","source":"hueber"},{"label":"6","text":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → ___","gaps":[["d"]],"solution":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → **d**","en":"Vi invito per l'ultima volta a mandarmi un sostituto entro il … → d","why":"*zum letzten Mal* = *ein letztes Mal*.","source":"hueber"},{"label":"7","text":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → ___","gaps":[["a"]],"solution":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → **a**","en":"Se entro il … non ricevo vostre notizie, rinuncio all'ordine. → a","why":"*auf etwas verzichten* = fare a meno di / rinunciare a qualcosa.","source":"hueber"}]},{"no":"24","tag":"Schreibtraining","part":"b","part_instruction":"Wählen Sie eine Situation und schreiben Sie eine Reklamation wie in a. Die Sätze 1–7 helfen Ihnen.","part_instruction_en":"Scegli una situazione e scrivi un reclamo come in a. Le frasi 1–7 ti aiutano. Le risposte modello sono ognuna una delle possibilità.","reading":[{"label":"1","text":"Kopfhörer bestellt – funktioniert nicht – schon einmal geschrieben, aber keine Antwort erhalten – bitte Ersatz bis … senden – wenn wieder keine Antwort, auf Bestellung verzichten"},{"label":"2","text":"Laptoptasche bestellt – Trageriemen nach einer Woche gerissen – zurückschicken – umtauschen oder Ersatz – bitte Reklamation bestätigen"}],"example":[{"label":"Beispiel","text":"Sehr geehrte Damen und Herren / Am 12.3. … / Freundliche Grüsse"}],"items":[{"label":"1","lead":"Situation 1: Kopfhörer","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 12.3. haben Sie mir Kopfhörer geliefert. Leider funktionieren sie nicht. Ich habe Ihnen schon einmal geschrieben, aber keine Antwort erhalten. Ich fordere Sie zum letzten Mal auf, mir bis 12.4. einen Ersatz zu schicken. Wenn ich wieder keine Antwort von Ihnen erhalte, dann verzichte ich auf die Bestellung. / Freundliche Grüsse / Luca Carelli","en":"Gentili signore e signori / Il 12.3 mi avete consegnato delle cuffie. Purtroppo non funzionano. Vi ho già scritto una volta, ma non ho ricevuto risposta. Vi invito per l'ultima volta a mandarmi un sostituto entro il 12.4. Se di nuovo non ricevo una vostra risposta, rinuncio all'ordine. / Cordiali saluti / Luca Carelli","why":"I punti chiave in ordine: che cosa hai ricevuto e quando, che cosa non va, che cosa hai fatto, che cosa deve fare la ditta (*auffordern, … zu …*), che cosa farai altrimenti.","source":"hueber"},{"label":"2","lead":"Situation 2: Laptoptasche","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 3.5. haben Sie mir eine Laptoptasche geliefert. Leider ist der Trageriemen schon nach einer Woche gerissen. Das ist sehr ärgerlich. Ich schicke Ihnen die Tasche heute zurück und bitte Sie, sie umzutauschen oder mir einen Ersatz zu schicken. Im Anhang finden Sie eine Kopie der Rechnung. Bestätigen Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben. / Freundliche Grüsse / Maria Keller","en":"Gentili signore e signori / Il 3.5 mi avete consegnato una borsa per portatile. Purtroppo la tracolla si è strappata già dopo una settimana. È molto fastidioso. Oggi vi rispedisco la borsa e vi chiedo di cambiarla o di mandarmi un sostituto. In allegato trovate una copia della fattura. Vi prego di confermarmi per iscritto di aver ricevuto il mio reclamo. / Cordiali saluti / Maria Keller","why":"Un nostro modello (la soluzione non ne ha uno per la situazione 2). *bitten, … zu …*: *umzutauschen* (separabile).","source":"g6865"}]}]},{"page":"AB 159","heading":"Test Lektion 6","heading_en":"Test della Lektion 6","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Completa il testo. Il libro dà alcune lettere di ogni parola (indicate sopra la frase); scrivi la parola intera.","example":[{"label":"a","text":"Ich war **jahrelang** angestellt, …"}],"items":[{"label":"b","lead":"b: e _ t _ _ _ _ l _ s _ _ n  /  c: K _ _ _ _ a _ _","text":"… aber irgendwann war ich unzufrieden und habe mich ___: Ich mache mich als ___ selbstständig und gründe eine Firma.","gaps":[["entschlossen"],["Kaufmann","Kauffrau"]],"solution":"… aber irgendwann war ich unzufrieden und habe mich **entschlossen**: Ich mache mich als **Kaufmann** selbstständig und gründe eine Firma.","en":"… ma a un certo punto ero scontento e ho deciso: mi metto in proprio come commerciante e fondo una ditta.","why":"*sich entschliessen* (Perfekt: *hat sich entschlossen*) = decidere. *der Kaufmann* = commerciante.","source":"g6865","check":"Le lettere date indicano *Kaufmann*; una donna scriverebbe *Kauffrau*, che ha uno schema diverso. Sono accettate tutte e due. Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."},{"label":"d","lead":"G _ _ _ _ ä _ _ _ l _ _ _ e","text":"Ein paar Freunde, die gute ___ sind, helfen mir dabei.","gaps":[["Geschäftsleute"]],"solution":"Ein paar Freunde, die gute **Geschäftsleute** sind, helfen mir dabei.","en":"Mi aiutano alcuni amici che sono bravi commercianti.","why":"*die Geschäftsleute* = commercianti, uomini d'affari (plurale).","source":"g6865","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."},{"label":"e","lead":"e: f _ _ _ _ z _ _ _ _ _ s  /  f: l _ _ _ t","text":"Ich glaube nicht, dass es ein ___ Risiko ist. Im Gegenteil, ich denke es ___ sich.","gaps":[["finanzielles"],["lohnt"]],"solution":"Ich glaube nicht, dass es ein **finanzielles** Risiko ist. Im Gegenteil, ich denke es **lohnt** sich.","en":"Non credo che sia un rischio finanziario. Al contrario, penso che ne valga la pena.","why":"*ein finanzielles Risiko* (neutro); *es lohnt sich* = ne vale la pena.","source":"platzhalter","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit *damit* oder – wenn möglich – *um … zu*.","instruction_en":"Unisci le due frasi. Usa *um … zu* quando la persona è la stessa; altrimenti usa *damit*.","example":[{"label":"a","lead":"Erika lernt Englisch. Sie möchte ausländische Kunden besser verstehen.","text":"Erika lernt Englisch, **um ausländische Kunden besser zu verstehen**."}],"items":[{"label":"b","lead":"Tomás macht eine Weiterbildung. Er möchte seine kommunikativen Kompetenzen verbessern.","text":"","accept":["Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern."],"solution":"**Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern.**","en":"Tomás fa un corso di perfezionamento per migliorare le sue competenze comunicative.","why":"Stessa persona (Tomás) → *um … zu*; *möchte* cade.","source":"g6865","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."},{"label":"c","lead":"Frau Seil arbeitet nur halbtags. Die Kinder sollen nicht allein sein, wenn sie aus der Schule kommen.","text":"","accept":["Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen."],"solution":"**Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen.**","en":"La signora Seil lavora solo mezza giornata perché i bambini non siano soli quando tornano da scuola.","why":"Altra persona (i bambini) → *damit*; *sollen* cade.","source":"damit","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."},{"label":"d","lead":"Rodolfo kümmert sich diese Woche um die Kinder. Seine Frau kann ihre kranke Mutter besuchen.","text":"","accept":["Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann."],"solution":"**Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann.**","en":"Questa settimana Rodolfo si occupa dei bambini affinché sua moglie possa andare a trovare sua madre malata.","why":"Altra persona (sua moglie) → *damit*; *kann* va per ultimo.","source":"damit","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."}]},{"no":"3","instruction":"Ergänzen Sie: *ohne … zu* oder *statt … zu*.","instruction_en":"Scrivi *ohne* o *statt* nel primo spazio e *zu* nel secondo.","example":[{"label":"a","text":"Wenn man streiten kann, **ohne** alles persönlich **zu** nehmen, dann ist man konfliktfähig."}],"items":[{"label":"b","text":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, ___ ergebnislos ___ streiten.","gaps":[["statt"],["zu"]],"solution":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, **statt** ergebnislos **zu** streiten.","en":"Si sa scendere a compromessi quando, nelle questioni controverse, ci si mette d'accordo con qualcuno invece di litigare senza risultato.","why":"Mettersi d'accordo sostituisce il litigare → *statt*.","source":"komma","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."},{"label":"c","text":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, ___ sich selbst zu wichtig ___ nehmen.","gaps":[["ohne"],["zu"]],"solution":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, **ohne** sich selbst zu wichtig **zu** nehmen.","en":"Un buon capo è qualcuno che guida i suoi collaboratori senza prendersi troppo sul serio.","why":"Guida e nello stesso tempo non si prende troppo sul serio → *ohne*. Il primo *zu* significa \"troppo\".","source":"komma","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."},{"label":"d","text":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, ___ immer nur alles allein ___ machen.","gaps":[["statt"],["zu"]],"solution":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, **statt** immer nur alles allein **zu** machen.","en":"Chi sa lavorare in team lavora volentieri con i colleghi invece di fare sempre tutto da solo.","why":"Il lavoro di squadra sostituisce il lavorare da soli → *statt*.","source":"komma","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."},{"label":"e","text":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, ___ gestresst ___ sein.","gaps":[["ohne"],["zu"]],"solution":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, **ohne** gestresst **zu** sein.","en":"Flessibile è qualcuno che sa abituarsi in fretta e senza problemi a situazioni nuove, senza essere stressato.","why":"Lo stress non c'è → *ohne*.","source":"komma","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."}]},{"no":"4","instruction":"Vor dem Bewerbungsgespräch. Was ist richtig? Kreuzen Sie an.","instruction_en":"Prima del colloquio di lavoro: consigli per un'amica. Scrivi l'espressione che si adatta al resto della frase. Le due possibilità sono indicate sopra ogni frase.","example":[{"label":"a","text":"**An deiner Stelle würde** ich heute noch ein bisschen über die Firma im Internet recherchieren."}],"items":[{"label":"b","lead":"Wie wäre es, wenn / Ich kann dir nur raten,","text":"___ du dir ein paar Fragen überlegst, die du morgen stellen kannst?","gaps":[["Wie wäre es, wenn","Wie wäre es wenn"]],"solution":"**Wie wäre es, wenn** du dir ein paar Fragen überlegst, die du morgen stellen kannst?","en":"Che ne diresti di pensare a un paio di domande da fare domani?","why":"*du … überlegst* con il verbo alla fine vuole *wenn*: *Wie wäre es, wenn …?*","source":"g6865","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."},{"label":"c","lead":"Was hältst du davon, / Du könntest zum Beispiel","text":"___ fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","gaps":[["Du könntest zum Beispiel"]],"solution":"**Du könntest zum Beispiel** fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","en":"Potresti per esempio chiedere quanto è grande il team o quali saranno i tuoi compiti.","why":"Dopo un verbo modale viene un infinito semplice (*fragen*): *Du könntest … fragen*.","source":"g6865","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."},{"label":"d","lead":"An deiner Stelle würde ich / Ich kann dir nur raten,","text":"___ du selbst zu sein. Das ist das Allerwichtigste.","gaps":[["Ich kann dir nur raten,","Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten,** du selbst zu sein. Das ist das Allerwichtigste.","en":"Posso solo consigliarti di essere te stessa. È la cosa più importante di tutte.","why":"*zu sein* vuole un'espressione che regge *zu* + infinito: *Ich kann dir nur raten, …*","source":"g6865","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."},{"label":"e","lead":"Wie wäre es, wenn / Was hältst du davon,","text":"___ heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","gaps":[["Was hältst du davon,","Was hältst du davon"]],"solution":"**Was hältst du davon,** heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","en":"Che ne dici di andare a mangiare fuori stasera? Così pensi ad altro.","why":"*essen zu gehen* (zu + infinito) si adatta a *Was hältst du davon, … zu …?*","source":"g6865","check":"Le soluzioni ufficiali dell'Arbeitsbuch non coprono il test della lezione; questa risposta è nostra, verificata con grammis."}]}]},{"page":"AB 160","heading":"Fokus Beruf: Kundenwünsche","heading_en":"Focus sul lavoro: richieste dei clienti","exercises":[{"no":"3","instruction":"Arbeiten Sie zu dritt. Wählen Sie je eine Rolle und spielen Sie drei Telefongespräche.","instruction_en":"Lavorate in tre: ognuno prende un ruolo e recitate tre telefonate. Esercitati scrivendole o dicendole; i dialoghi modello sono una delle possibilità. (Gli esercizi 1 e 2 sono ascolti e sono omessi.)","reading":[{"label":"A  Kundin/Kunde","text":"Sie machen heute eine Grillparty. Sie haben beim Getränkeservice *Getränkeblitz* drei Harasse Mineralwasser und vier Harasse Süssmost bestellt."},{"label":"B  Angestellte/Angestellter","text":"Sie arbeiten bei der Firma *Getränkeblitz* und bekommen einen Beschwerdeanruf von einer Kundin. Sie können nicht direkt helfen. Sie müssen zuerst mit dem Fahrer sprechen und rufen die Kundin dann zurück."},{"label":"C  Fahrerin/Fahrer","text":"Sie arbeiten als Fahrer/in für die Firma *Getränkeblitz*. Sie haben für die Grillparty sieben Harasse Mineralwasser geliefert."}],"phrases":["Gespräch 1 – Kunde: Ich habe bei Ihnen … bestellt. | Jetzt ist die Lieferung gekommen, aber … | Sie haben wohl einen Fehler gemacht. | Ich habe … bestellt und nicht …","Gespräch 1 – Angestellte: Oh, das tut mir leid. | Da ist wohl ein Fehler/ein Irrtum passiert. | Ich rufe sofort meine Kollegin/meinen Kollegen an. | Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","Gespräch 2 – Angestellte: Frau/Herr … hat angerufen. | Du hast ihm/ihr … statt … geliefert. | Wir machen Folgendes: … | Ich rufe an und frage nach, ob das okay ist.","Gespräch 2 – Fahrer: Oh je, da habe ich wohl einen Fehler gemacht. | Da habe ich wohl etwas verwechselt. | Was machen wir denn jetzt? | Ich könnte …","Gespräch 3 – Angestellte: Es tut mir wahnsinnig leid. | Meine Kollegin/Mein Kollege hat einen Fehler gemacht. | Wir könnten Ihnen … | Selbstverständlich geben wir Ihnen einen Rabatt.","Gespräch 3 – Kunde: Ja, damit bin ich einverstanden. | Nein, tut mir leid. Das war doch Ihr Fehler, nicht meiner. | Ich mache Ihnen einen anderen Vorschlag: …"],"items":[{"label":"1","lead":"Gespräch 1: Kundin und Angestellter","text":"","open":true,"solution":"Kundin: Grüezi, hier ist Meier. Ich habe bei Ihnen drei Harasse Mineralwasser und vier Harasse Süssmost bestellt. Jetzt ist die Lieferung gekommen, aber es sind sieben Harasse Mineralwasser. Ich habe Süssmost bestellt und nicht nur Wasser! / Angestellter: Oh, das tut mir leid. Da ist wohl ein Fehler passiert. Ich rufe sofort meinen Kollegen an. Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","en":"Cliente: Buongiorno, sono la signora Meier. Ho ordinato da voi tre casse di acqua minerale e quattro casse di succo di mela. Adesso è arrivata la consegna, ma sono sette casse di acqua minerale. Ho ordinato succo di mela e non solo acqua! / Impiegato: Oh, mi dispiace. Dev'esserci stato un errore. Chiamo subito il mio collega. Mi dia il suo numero di cellulare, la richiamo subito.","why":"Reclamo: di' che cosa hai ordinato e che cosa è arrivato (*bestellt … und nicht …*). L'impiegato si scusa e promette di richiamare. (*der Harass* = parola svizzera per cassa; *der Süssmost* = succo di mela svizzero.)","source":"hueber"},{"label":"2","lead":"Gespräch 2: Angestellter und Fahrer","text":"","open":true,"solution":"Angestellter: Hallo Marco, Frau Meier hat angerufen. Du hast ihr sieben Harasse Mineralwasser statt drei Harasse Wasser und vier Harasse Süssmost geliefert. / Fahrer: Oh je, da habe ich wohl etwas verwechselt. Was machen wir denn jetzt? Ich könnte heute Nachmittag noch einmal hinfahren. / Angestellter: Gut, wir machen Folgendes: Du bringst ihr vier Harasse Süssmost und holst vier Harasse Wasser wieder ab. Ich rufe an und frage nach, ob das okay ist.","en":"Impiegato: Ciao Marco, ha chiamato la signora Meier. Le hai consegnato sette casse di acqua minerale invece di tre casse d'acqua e quattro casse di succo di mela. / Autista: Oh no, devo aver confuso qualcosa. E adesso che cosa facciamo? Potrei tornarci oggi pomeriggio. / Impiegato: Bene, facciamo così: le porti quattro casse di succo di mela e riprendi quattro casse d'acqua. Io la chiamo e le chiedo se va bene.","why":"Tra colleghi si usa *du*. Qui *statt* + sostantivo (*statt drei Harasse Wasser*): la stessa idea di *statt … zu*, ma con una cosa.","source":"hueber"},{"label":"3","lead":"Gespräch 3: Angestellter und Kundin","text":"","open":true,"solution":"Angestellter: Frau Meier, es tut mir wahnsinnig leid. Mein Kollege hat einen Fehler gemacht. Wir könnten Ihnen den Süssmost noch heute bis 17 Uhr bringen. Selbstverständlich geben wir Ihnen einen Rabatt von 20 Prozent. / Kundin: Ja, damit bin ich einverstanden. Die Party fängt erst um 18 Uhr an. Vielen Dank!","en":"Impiegato: Signora Meier, mi dispiace tantissimo. Il mio collega ha fatto un errore. Potremmo portarle il succo di mela ancora oggi entro le 17. Naturalmente le facciamo uno sconto del 20 per cento. / Cliente: Sì, sono d'accordo. La festa comincia solo alle 18. Grazie mille!","why":"Proponi una soluzione con *Wir könnten Ihnen …* (Konjunktiv II = cortese). La cliente accetta: *damit bin ich einverstanden* (qui *damit* = con questo, non *affinché*).","source":"hueber"}]}]}],"sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (soluzioni ufficiali, Lektion 6)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (um … zu non ha un soggetto proprio; lo prende dalla frase principale)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"damit","title":"grammis, dizionario dei connettivi: damit (congiunzione subordinante con il verbo alla fine; anche avverbio che significa \"con questo\")","url":"https://grammis.ids-mannheim.de/konnektoren/407001"},{"id":"komma","title":"grammis: Komma bei Nebensätzen (le frasi infinitive con um, ohne, (an)statt sono separate da una virgola)","url":"https://grammis.ids-mannheim.de/rechtschreibung/6203"},{"id":"platzhalter","title":"grammis: Platzhalter (es in posizione 1; l'es formale con i verbi del tempo atmosferico resta: Heute schneit es)","url":"https://grammis.ids-mannheim.de/vggf/2284"},{"id":"korrelat","title":"grammis: Korrelat (es che anticipa una frase: Ich kann es nicht erwarten, euch zu sehen)","url":"https://grammis.ids-mannheim.de/vggf/2283"}]},{"id":"06-lektion-6-zusatzblaetter","no":6,"title":"Lektion 6 Homework – extra exercises from printed sheets","title_en":"Invece di (*anstatt … zu / anstatt dass*), senza (*ohne … zu / ohne dass*), scopo (*um … zu / damit*)","added":"2026-11-20","book":"Printed grammar sheets 48, 49 and 52 (extra homework for Schritte plus Neu 5, Lektion 6)","pages":[{"page":"Blatt 48 · S. 100","heading":"48  Ich lade gerne Freunde ein, anstatt allein zu essen.","heading_en":"Mi piace invitare amici invece di mangiare da solo. (Proposizione principale + proposizione infinitiva / proposizione modale: *anstatt … zu, anstatt dass*)","exercises":[{"no":"A","instruction":"Welches Foto passt? Kreuzen Sie an.","instruction_en":"Quale foto corrisponde alla frase? Foto A: amici che mangiano insieme a un grande tavolo. Foto B: un uomo che mangia da solo. Scrivi A o B. I riquadri delle regole B e C del foglio sono riportati qui sotto.","reading":[{"label":"B  Lesen Sie.","text":"Infinitiv mit anstatt … zu: Ich lade gerne Freunde ein, | anstatt immer allein zu essen.\nNebensatz mit anstatt dass: Ich lade gerne Freunde ein, | anstatt dass ich immer allein esse.\nDie Subjekte in Haupt- und Nebensatz sind gleich: anstatt … zu oder anstatt dass\nIch lade gerne Freunde ein, | anstatt immer allein zu essen. / anstatt dass ich immer allein esse.\nDie Subjekte in Hauptsatz und Nebensatz sind nicht gleich: immer anstatt dass\nEr lädt gerne Freunde ein, | anstatt dass wir immer allein essen."},{"label":"C  Lesen Sie.","text":"• *anstatt … zu* und *anstatt dass* signalisieren, dass eine Alternative möglich ist.\n• Im Infinitivsatz mit *anstatt … zu* steht kein Subjekt. Das Subjekt aus dem Hauptsatz ist auch Subjekt im Infinitivsatz.\n• Man kann *anstatt* oder *statt* benutzen, es gibt keinen Unterschied: Wir lachen anstatt zu weinen. = Wir lachen statt zu weinen."}],"items":[{"label":"1","text":"Ich lade gerne Freunde ein, anstatt immer allein zu essen. → Foto ___","gaps":[["A"]],"solution":"Ich lade gerne Freunde ein, anstatt immer allein zu essen. → Foto **A**","en":"Mi piace invitare amici invece di mangiare sempre da solo. → Foto A","why":"La foto A mostra gli amici a tavola, l'alternativa che ha scelto; la foto B mostra ciò che *non* fa.","source":"anstattdass"}]},{"no":"1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Quali frasi sono giuste? Scrivi *richtig* o *falsch*. Suggerimento: *anstatt* significa già \"non questo\", quindi dopo non seguono né *nicht* né *kein*.","example":[{"label":"1","text":"Ich verabrede mich mit Freunden, anstatt allein fernzusehen. → **richtig**"}],"items":[{"label":"2","text":"Ich verabrede mich mit Freunden, anstatt nicht allein fernzusehen. → ___","gaps":[["falsch"]],"solution":"Ich verabrede mich mit Freunden, anstatt nicht allein fernzusehen. → **falsch**","en":"Mi do appuntamento con gli amici invece di non guardare la TV da solo. → sbagliato","why":"*anstatt* nega già: *anstatt nicht …* dice il contrario di ciò che si intende.","source":"anstattdass"},{"label":"3","text":"Ich veröffentliche mein Buch bei Amazon, anstatt keinen Verlag zu suchen. → ___","gaps":[["falsch"]],"solution":"Ich veröffentliche mein Buch bei Amazon, anstatt keinen Verlag zu suchen. → **falsch**","en":"Pubblico il mio libro su Amazon invece di non cercare un editore. → sbagliato","why":"Niente *kein* dopo *anstatt*: l'azione sostituita è *einen Verlag suchen*.","source":"anstattdass"},{"label":"4","text":"Ich veröffentliche mein Buch bei Amazon, anstatt einen Verlag zu suchen. → ___","gaps":[["richtig"]],"solution":"Ich veröffentliche mein Buch bei Amazon, anstatt einen Verlag zu suchen. → **richtig**","en":"Pubblico il mio libro su Amazon invece di cercare un editore. → giusto","why":"Azione positiva dopo *anstatt*, *zu* + infinito alla fine.","source":"g6865"}]}]},{"page":"Blatt 48 · S. 101","heading":"48  Ich lade gerne Freunde ein, anstatt allein zu essen.","heading_en":"Mi piace invitare amici invece di mangiare da solo.","exercises":[{"no":"2","instruction":"Vereine. Verbinden Sie die Sätze mit *anstatt … zu*. Schreiben Sie in Ihr Heft.","instruction_en":"Associazioni. Unisci le due frasi con *anstatt … zu*. La seconda frase dice che cosa *non* succede: togli il suo *nicht* e il suo soggetto, metti *zu* + infinito alla fine.","example":[{"label":"1","lead":"Ich werde Mitglied in einem Fussballverein. Ich mache nicht allein Sport.","text":"Ich werde Mitglied in einem Fussballverein, **anstatt allein Sport zu machen**."}],"items":[{"label":"2","lead":"Sie können den Mitgliedsbeitrag auch monatlich überweisen. Sie zahlen nicht sofort fürs ganze Jahr.","text":"","accept":["Sie können den Mitgliedsbeitrag auch monatlich überweisen, anstatt sofort fürs ganze Jahr zu zahlen.","Sie können den Mitgliedsbeitrag auch monatlich überweisen, statt sofort fürs ganze Jahr zu zahlen."],"solution":"**Sie können den Mitgliedsbeitrag auch monatlich überweisen, anstatt sofort fürs ganze Jahr zu zahlen.**","en":"Può anche versare la quota associativa ogni mese invece di pagare subito per tutto l'anno.","why":"*nicht* si toglie; *zu zahlen* va alla fine.","source":"g6865"},{"label":"3","lead":"Wir nehmen Tom in unseren Verein auf. Wir sagen ihm nicht wieder ab.","text":"","accept":["Wir nehmen Tom in unseren Verein auf, anstatt ihm wieder abzusagen.","Wir nehmen Tom in unseren Verein auf, statt ihm wieder abzusagen."],"solution":"**Wir nehmen Tom in unseren Verein auf, anstatt ihm wieder abzusagen.**","en":"Accogliamo Tom nella nostra associazione invece di dirgli di nuovo di no.","why":"Verbo separabile: *zu* va tra prefisso e verbo: *abzusagen* (ab + zu + sagen).","source":"g6865"},{"label":"4","lead":"Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen. Sie werden nicht sofort Mitglied.","text":"","accept":["Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, anstatt sofort Mitglied zu werden.","Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, statt sofort Mitglied zu werden."],"solution":"**Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, anstatt sofort Mitglied zu werden.**","en":"Per cominciare può anche venire semplicemente ai nostri eventi, invece di diventare subito socio.","why":"Stesso soggetto *Sie*: *anstatt … Mitglied zu werden*.","source":"g6865"}]},{"no":"3","instruction":"Unterstreichen Sie die Subjekte. Welche sind gleich? Kreuzen Sie an.","instruction_en":"Trova il soggetto di ogni frase (chi fa l'azione), poi di' se è la stessa persona o cosa. Scrivi i due soggetti, poi *gleich* (uguale) o *nicht gleich* (non uguale). Attenzione: il soggetto non è sempre in posizione 1.","example":[{"label":"1","text":"Sie möchte Bücher schreiben. Sie arbeitet nicht weiter im Büro. → **Sie** / **Sie** → **gleich**"}],"items":[{"label":"2","text":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher. → ___ / ___ → ___","gaps":[["Der Verlag"],["Die Autoren"],["nicht gleich"]],"solution":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher. → **Der Verlag** / **Die Autoren** → **nicht gleich**","en":"La casa editrice ormai vuole sviluppare solo app. Gli autori non scrivono libri. → non uguale","why":"Due soggetti diversi: *der Verlag* e *die Autoren*.","source":"anstattdass"},{"label":"3","text":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag. → ___ / ___ → ___","gaps":[["Sie"],["sie"],["gleich"]],"solution":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag. → **Sie** / **sie** → **gleich**","en":"Pubblica il romanzo in autoedizione. Il manoscritto non lo manda a una casa editrice. → uguale","why":"*Das Manuskript* è il complemento oggetto (viene mandato); il soggetto *sie* viene dopo il verbo.","source":"g6865"},{"label":"4","text":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher. → ___ / ___ → ___","gaps":[["Der Verlag"],["Er"],["gleich"]],"solution":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher. → **Der Verlag** / **Er** → **gleich**","en":"La casa editrice ormai pubblica solo online. Non stampa libri. → uguale","why":"*Er* si riferisce a *der Verlag*.","source":"g6865"}]},{"no":"4","instruction":"Verbinden Sie die Sätze aus 4 mit *anstatt … zu* und / oder *anstatt dass*.","instruction_en":"Unisci le frasi dell'esercizio 3 (il foglio dice per errore \"aus 4\"). Stesso soggetto: funzionano entrambe le forme. Soggetti diversi: solo *anstatt dass*. Togli *nicht* / trasforma *kein* in *ein* o in niente.","example":[{"label":"1","text":"anstatt … zu: Sie möchte Bücher schreiben, **anstatt weiter im Büro zu arbeiten**.\nanstatt dass: Sie möchte Bücher schreiben, **anstatt dass sie weiter im Büro arbeitet**."}],"items":[{"label":"2 · anstatt dass","lead":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher.","text":"","accept":["Der Verlag möchte nur noch Apps entwickeln, anstatt dass die Autoren Bücher schreiben.","Der Verlag möchte nur noch Apps entwickeln, statt dass die Autoren Bücher schreiben."],"solution":"**Der Verlag möchte nur noch Apps entwickeln, anstatt dass die Autoren Bücher schreiben.**","en":"La casa editrice ormai vuole sviluppare solo app, invece che gli autori scrivano libri.","why":"Soggetti diversi → solo *anstatt dass*; *keine Bücher* → *Bücher*; verbo alla fine.","source":"anstattdass"},{"label":"3 · anstatt … zu","lead":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag.","text":"","accept":["Sie veröffentlicht den Roman im Selbstverlag, anstatt das Manuskript an einen Verlag zu schicken.","Sie veröffentlicht den Roman im Selbstverlag, statt das Manuskript an einen Verlag zu schicken."],"solution":"**Sie veröffentlicht den Roman im Selbstverlag, anstatt das Manuskript an einen Verlag zu schicken.**","en":"Pubblica il romanzo in autoedizione invece di mandare il manoscritto a una casa editrice.","why":"Stesso soggetto: niente *sie* nella frase infinitiva, niente virgola prima di *zu*.","source":"g6865"},{"label":"3 · anstatt dass","lead":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag.","text":"","accept":["Sie veröffentlicht den Roman im Selbstverlag, anstatt dass sie das Manuskript an einen Verlag schickt.","Sie veröffentlicht den Roman im Selbstverlag, statt dass sie das Manuskript an einen Verlag schickt."],"solution":"**Sie veröffentlicht den Roman im Selbstverlag, anstatt dass sie das Manuskript an einen Verlag schickt.**","en":"Pubblica il romanzo in autoedizione invece di mandare il manoscritto a una casa editrice.","why":"*anstatt dass* vuole un proprio soggetto *sie*; il verbo *schickt* va alla fine.","source":"anstattdass"},{"label":"4 · anstatt … zu","lead":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher.","text":"","accept":["Der Verlag veröffentlicht nur noch online, anstatt Bücher zu drucken.","Der Verlag veröffentlicht nur noch online, statt Bücher zu drucken."],"solution":"**Der Verlag veröffentlicht nur noch online, anstatt Bücher zu drucken.**","en":"La casa editrice ormai pubblica solo online invece di stampare libri.","why":"*keine Bücher* → *Bücher*; *zu drucken* alla fine.","source":"g6865"},{"label":"4 · anstatt dass","lead":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher.","text":"","accept":["Der Verlag veröffentlicht nur noch online, anstatt dass er Bücher druckt.","Der Verlag veröffentlicht nur noch online, statt dass er Bücher druckt."],"solution":"**Der Verlag veröffentlicht nur noch online, anstatt dass er Bücher druckt.**","en":"La casa editrice ormai pubblica solo online invece di stampare libri.","why":"Soggetto *er* + verbo *druckt* alla fine.","source":"anstattdass"}]},{"no":"5","instruction":"Was würden Sie gerne machen? Schreiben Sie Sätze mit *anstatt … zu*.","instruction_en":"Che cosa ti piacerebbe fare? Combina un desiderio della prima parte del riquadro (*Ich würde gerne …*) con qualcosa della seconda parte (*anstatt … zu*). Le espressioni cancellate sono usate nell'esempio. La risposta modello è una delle possibilità.","box":["Sport in einem Verein machen","an einem Tag Homeoffice machen","öfter an die frische Luft gehen","schöne Dinge kaufen","etwas mit meiner Familie unternehmen","immer nur sparen","jeden Tag ins Büro fahren","immer allein joggen","am Wochenende arbeiten","immer im klimatisierten Büro sitzen"],"box_used":[0,7],"example":[{"label":"Beispiel","text":"Ich würde gerne Sport in einem Verein machen, **anstatt immer allein zu joggen**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gerne an einem Tag Homeoffice machen, anstatt jeden Tag ins Büro zu fahren. Ich würde gerne öfter an die frische Luft gehen, anstatt immer im klimatisierten Büro zu sitzen. Ich würde gerne schöne Dinge kaufen, anstatt immer nur zu sparen. Ich würde gerne etwas mit meiner Familie unternehmen, anstatt am Wochenende zu arbeiten.","en":"Mi piacerebbe lavorare da casa un giorno alla settimana invece di andare in ufficio ogni giorno. Mi piacerebbe uscire all'aria aperta più spesso invece di passare sempre il tempo nell'ufficio climatizzato. Mi piacerebbe comprare belle cose invece di limitarmi sempre a risparmiare. Mi piacerebbe fare qualcosa con la mia famiglia invece di lavorare nel fine settimana.","why":"Desiderio con *würde gerne* + infinito, poi *anstatt … zu* + infinito alla fine; *nur* resta prima di *zu sparen*.","source":"g6865"}]}]},{"page":"Blatt 49 · Seite 1","heading":"49  Ich arbeite hier, ohne Stress zu haben.","heading_en":"Qui lavoro senza stress. (Proposizione principale + proposizione infinitiva / proposizione modale: *ohne … zu, ohne dass*)","exercises":[{"no":"A","instruction":"Lesen Sie und unterstreichen Sie *ohne … zu*.","instruction_en":"Leggi il fumetto e scrivi la parte con *ohne … zu*. I riquadri delle regole B e C del foglio sono riportati qui sotto.","reading":[{"label":"Sprechblase","text":"Homeoffice! Ja, cool! Ich arbeite hier, ohne Stress zu haben."},{"label":"B  Lesen Sie.","text":"Infinitiv mit ohne zu: Ich arbeite hier, | ohne Stress zu haben.\nNebensatz mit ohne dass: Ich arbeite hier, | ohne dass ich Stress habe.\nDie Subjekte in Haupt- und Nebensatz sind gleich: ohne zu oder ohne dass\nIch arbeite hier, | ohne Stress zu haben. / ohne dass ich Stress habe.\nDie Subjekte in Haupt- und Nebensatz sind verschieden: immer ohne dass\nIch arbeite hier, | ohne dass mein Chef Stress macht."},{"label":"C  Lesen Sie.","text":"• *ohne … zu* und *ohne dass* drücken aus, dass etwas nicht ist oder nicht passiert.\n• Im Infinitivsatz mit *ohne … zu* steht kein Subjekt. Das Subjekt aus dem Hauptsatz ist auch Subjekt im Infinitivsatz."}],"items":[{"label":"1","text":"Homeoffice! Ja, cool! Ich arbeite hier, ___.","gaps":[["ohne Stress zu haben"]],"solution":"Homeoffice! Ja, cool! Ich arbeite hier, **ohne Stress zu haben**.","en":"Telelavoro! Sì, forte! Qui lavoro senza stress.","why":"*ohne* apre la frase, *zu* + infinito la chiude.","source":"g6865"}]},{"no":"1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Quali frasi sono giuste? Scrivi *richtig* o *falsch*. Suggerimento: *ohne* significa già \"non\", quindi dopo non seguono né *nicht* né *kein*.","example":[{"label":"1","text":"Ich kann hier gut Klavier spielen, ohne die Nachbarn zu stören. → **richtig**"}],"items":[{"label":"2","text":"Ich kann hier gut Klavier spielen, ohne die Nachbarn nicht zu stören. → ___","gaps":[["falsch"]],"solution":"Ich kann hier gut Klavier spielen, ohne die Nachbarn nicht zu stören. → **falsch**","en":"Qui posso suonare bene il pianoforte senza non disturbare i vicini. → sbagliato","why":"*ohne … nicht* è una doppia negazione: vorrebbe dire che li disturbi *davvero*.","source":"ohnedass"},{"label":"3","text":"Er bekommt mehr Lohn, ohne eine Stunde mehr dafür zu arbeiten. → ___","gaps":[["richtig"]],"solution":"Er bekommt mehr Lohn, ohne eine Stunde mehr dafür zu arbeiten. → **richtig**","en":"Riceve un salario più alto senza lavorare per questo un'ora in più. → giusto","why":"*ohne* + espressione positiva (*eine Stunde*) + *zu arbeiten*.","source":"g6865"},{"label":"4","text":"Er bekommt mehr Lohn, ohne keine Stunde mehr dafür zu arbeiten. → ___","gaps":[["falsch"]],"solution":"Er bekommt mehr Lohn, ohne keine Stunde mehr dafür zu arbeiten. → **falsch**","en":"Riceve un salario più alto senza non lavorare per questo nemmeno un'ora in più. → sbagliato","why":"Niente *kein* dopo *ohne*: *keine Stunde* diventa *eine Stunde*.","source":"ohnedass"}]}]},{"page":"Blatt 49 · Seite 2","heading":"49  Ich arbeite hier, ohne Stress zu haben.","heading_en":"Qui lavoro senza stress.","exercises":[{"no":"2","instruction":"Der Alltag eines Bloggers. Schreiben Sie Sätze mit *ohne … zu* in Ihr Heft.","instruction_en":"La vita quotidiana di un blogger. Unisci le due frasi con *ohne … zu*. Togli *nicht*; trasforma *kein* in *ein* (o toglilo davanti a un plurale).","example":[{"label":"1","lead":"Ich arbeite bequem von zu Hause. Ich fahre nicht ins Büro.","text":"Ich arbeite bequem von zu Hause, **ohne ins Büro zu fahren**."}],"items":[{"label":"2","lead":"Ich arbeite selbstständig. Ich habe keinen Vertrag.","text":"","accept":["Ich arbeite selbstständig, ohne einen Vertrag zu haben."],"solution":"**Ich arbeite selbstständig, ohne einen Vertrag zu haben.**","en":"Lavoro come indipendente senza avere un contratto.","why":"*keinen Vertrag* → *einen Vertrag*: *ohne* dice già \"non\".","source":"ohnedass"},{"label":"3","lead":"Ich mache Pausen und gehe auch mal zum Sport. Ich informiere meine Kollegen nicht.","text":"","accept":["Ich mache Pausen und gehe auch mal zum Sport, ohne meine Kollegen zu informieren."],"solution":"**Ich mache Pausen und gehe auch mal zum Sport, ohne meine Kollegen zu informieren.**","en":"Faccio pause e ogni tanto vado anche a fare sport senza informare i miei colleghi.","why":"*nicht* si toglie; *zu informieren* alla fine.","source":"g6865"},{"label":"4","lead":"Ich wähle die Themen für meinen Blog. Ich frage den Chef nicht.","text":"","accept":["Ich wähle die Themen für meinen Blog, ohne den Chef zu fragen."],"solution":"**Ich wähle die Themen für meinen Blog, ohne den Chef zu fragen.**","en":"Scelgo i temi per il mio blog senza chiedere al capo.","why":"*nicht* si toglie; il complemento oggetto *den Chef* va prima di *zu fragen*.","source":"g6865"},{"label":"5","lead":"Ich habe viel Zeit für mein Kind. Ich mache mir keine Sorgen um meine Karriere.","text":"","accept":["Ich habe viel Zeit für mein Kind, ohne mir Sorgen um meine Karriere zu machen."],"solution":"**Ich habe viel Zeit für mein Kind, ohne mir Sorgen um meine Karriere zu machen.**","en":"Ho molto tempo per mio figlio senza preoccuparmi della mia carriera.","why":"*keine Sorgen* → *Sorgen* (plurale: niente articolo); il riflessivo *mir* resta.","source":"ohnedass"}]},{"no":"3","instruction":"Mein Leben. *ohne dass* oder *ohne*? Unterstreichen Sie.","instruction_en":"La mia vita. Scrivi *ohne dass* o *ohne*. Guarda la fine: *zu* + infinito → *ohne*; un nuovo soggetto e un verbo coniugato alla fine → *ohne dass*.","example":[{"label":"1","text":"Ich möchte abends Musik hören, **ohne dass** sich meine Nachbarn beschweren."}],"items":[{"label":"2","text":"Ich trinke nie Kaffee, ___ dabei Zeitung zu lesen.","gaps":[["ohne"]],"solution":"Ich trinke nie Kaffee, **ohne** dabei Zeitung zu lesen.","en":"Non bevo mai il caffè senza leggere il giornale nel frattempo.","why":"*zu lesen* alla fine, nessun nuovo soggetto → *ohne*.","source":"g6865"},{"label":"3","text":"Ich gehe nie ins Theater, ___ mich vorher über das Stück zu informieren.","gaps":[["ohne"]],"solution":"Ich gehe nie ins Theater, **ohne** mich vorher über das Stück zu informieren.","en":"Non vado mai a teatro senza informarmi prima sullo spettacolo.","why":"*zu informieren* alla fine → *ohne*; *mich* è il riflessivo, non un soggetto.","source":"g6865"},{"label":"4","text":"Meine Kinder gehen nie aus, ___ ich etwas davon weiss.","gaps":[["ohne dass"]],"solution":"Meine Kinder gehen nie aus, **ohne dass** ich etwas davon weiss.","en":"I miei figli non escono mai senza che io lo sappia.","why":"Nuovo soggetto *ich*, *weiss* alla fine → *ohne dass*.","source":"ohnedass"}]},{"no":"4","instruction":"Computer. Unterstreichen Sie die Subjekte. Sind sie (nicht) gleich? Kreuzen Sie an.","instruction_en":"Computer. Trova il soggetto di ogni frase e scrivi i due soggetti, poi *gleich* (uguale) o *nicht gleich* (non uguale). *Sie* con la maiuscola = il \"Lei\" di cortesia.","example":[{"label":"1","text":"Sie verlässt einfach das Büro. Sie sichert die Daten im Computer nicht. → **Sie** / **Sie** → **gleich**"}],"items":[{"label":"2","text":"Die Firma speichert unsere Daten. Wir haben keine Ahnung. → ___ / ___ → ___","gaps":[["Die Firma"],["Wir"],["nicht gleich"]],"solution":"Die Firma speichert unsere Daten. Wir haben keine Ahnung. → **Die Firma** / **Wir** → **nicht gleich**","en":"La ditta salva i nostri dati. Non ne abbiamo idea. → non uguale","why":"Due soggetti diversi: *die Firma* e *wir*.","source":"ohnedass"},{"label":"3","text":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange. → ___ / ___ → ___","gaps":[["Wir"],["Wir"],["gleich"]],"solution":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange. → **Wir** / **Wir** → **gleich**","en":"Dovremmo elaborare i dati elettronicamente. Non aspettiamo a lungo. → uguale","why":"In entrambe le frasi: *wir*.","source":"g6865"},{"label":"4","text":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht. → ___ / ___ → ___","gaps":[["Sie"],["Der Techniker"],["nicht gleich"]],"solution":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht. → **Sie** / **Der Techniker** → **nicht gleich**","en":"Lei può installare il software. Il tecnico non La aiuta. → non uguale","why":"*Ihnen* è il complemento al dativo; il soggetto della seconda frase è *der Techniker*.","source":"ohnedass"},{"label":"5","text":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht. → ___ / ___ → ___","gaps":[["Ich"],["Ich"],["gleich"]],"solution":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht. → **Ich** / **Ich** → **gleich**","en":"Collego il computer. Non chiedo al reparto IT. → uguale","why":"In entrambe le frasi: *ich*.","source":"g6865"}]},{"no":"5","instruction":"Verbinden Sie die Sätze aus 4 mit *ohne dass* und, wo möglich, mit *ohne zu*. Schreiben Sie in Ihr Heft.","instruction_en":"Unisci le frasi dell'esercizio 4 con *ohne dass*, e anche con *ohne … zu* dove i soggetti sono uguali. Togli *nicht*; trasforma *keine* in *eine*.","example":[{"label":"1","text":"Sie verlässt einfach das Büro, **ohne die Daten im Computer zu sichern**.\nSie verlässt einfach das Büro, **ohne dass sie die Daten im Computer sichert**."}],"items":[{"label":"2 · ohne dass","lead":"Die Firma speichert unsere Daten. Wir haben keine Ahnung.","text":"","accept":["Die Firma speichert unsere Daten, ohne dass wir eine Ahnung haben.","Die Firma speichert unsere Daten, ohne dass wir eine Ahnung davon haben."],"solution":"**Die Firma speichert unsere Daten, ohne dass wir eine Ahnung haben.**","en":"La ditta salva i nostri dati senza che noi ne abbiamo idea.","why":"Soggetti diversi → solo *ohne dass*; *keine Ahnung* → *eine Ahnung*.","source":"ohnedass"},{"label":"3 · ohne … zu","lead":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange.","text":"","accept":["Wir sollten die Daten elektronisch verarbeiten, ohne lange zu warten."],"solution":"**Wir sollten die Daten elektronisch verarbeiten, ohne lange zu warten.**","en":"Dovremmo elaborare i dati elettronicamente senza aspettare a lungo.","why":"Stesso soggetto: *nicht* si toglie, *zu warten* alla fine.","source":"g6865"},{"label":"3 · ohne dass","lead":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange.","text":"","accept":["Wir sollten die Daten elektronisch verarbeiten, ohne dass wir lange warten."],"solution":"**Wir sollten die Daten elektronisch verarbeiten, ohne dass wir lange warten.**","en":"Dovremmo elaborare i dati elettronicamente senza aspettare a lungo.","why":"Soggetto *wir* ripetuto, *warten* alla fine.","source":"ohnedass"},{"label":"4 · ohne dass","lead":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht.","text":"","accept":["Sie können die Software installieren, ohne dass der Techniker Ihnen hilft.","Sie können die Software installieren, ohne dass Ihnen der Techniker hilft."],"solution":"**Sie können die Software installieren, ohne dass der Techniker Ihnen hilft.**","en":"Lei può installare il software senza che il tecnico La aiuti.","why":"Soggetti diversi → solo *ohne dass*; *hilft* alla fine.","source":"ohnedass"},{"label":"5 · ohne … zu","lead":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht.","text":"","accept":["Ich schliesse den Computer an, ohne die IT-Abteilung zu fragen."],"solution":"**Ich schliesse den Computer an, ohne die IT-Abteilung zu fragen.**","en":"Collego il computer senza chiedere al reparto IT.","why":"Stesso soggetto: *ohne die IT-Abteilung zu fragen*.","source":"g6865"},{"label":"5 · ohne dass","lead":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht.","text":"","accept":["Ich schliesse den Computer an, ohne dass ich die IT-Abteilung frage."],"solution":"**Ich schliesse den Computer an, ohne dass ich die IT-Abteilung frage.**","en":"Collego il computer senza chiedere al reparto IT.","why":"Soggetto *ich* ripetuto, *frage* alla fine.","source":"ohnedass"}]},{"no":"6","instruction":"Was würden Sie gerne machen? Schreiben Sie Sätze mit *ohne … zu* in Ihr Heft.","instruction_en":"Che cosa ti piacerebbe fare? Combina un desiderio della prima parte del riquadro con qualcosa della seconda parte, usando *ohne … zu*. Le espressioni cancellate sono usate nell'esempio. La risposta modello è una delle possibilità.","box":["viel Geld verdienen","eine eigene Firma gründen","fliessend Deutsch sprechen","mehrmals im Jahr verreisen","immer sparen","noch mehr arbeiten","Sprachkurse besuchen","die Risiken tragen"],"box_used":[0,5],"example":[{"label":"Beispiel","text":"Ich würde gerne viel Geld verdienen, **ohne noch mehr zu arbeiten**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gerne eine eigene Firma gründen, ohne die Risiken zu tragen. Ich würde gerne fliessend Deutsch sprechen, ohne Sprachkurse zu besuchen. Ich würde gerne mehrmals im Jahr verreisen, ohne immer zu sparen.","en":"Mi piacerebbe fondare una mia ditta senza assumermi i rischi. Mi piacerebbe parlare tedesco correntemente senza frequentare corsi di lingua. Mi piacerebbe viaggiare più volte all'anno senza dover sempre risparmiare.","why":"Desiderio con *würde gerne* + infinito, poi *ohne … zu* + infinito alla fine.","source":"g6865"}]}]},{"page":"Blatt 52 · S. 108","heading":"52  Ich fahre langsam, um Benzin zu sparen.","heading_en":"Guido piano per risparmiare benzina. (Proposizione principale + proposizione finale: *um … zu, damit*)","exercises":[{"no":"A","instruction":"Lesen Sie und ordnen Sie zu.","instruction_en":"Leggi e abbina ogni frase a una foto. Foto A: un uomo che gira la manopola di un termosifone. Foto B: mani sul volante. Scrivi A o B. I riquadri delle regole B e C del foglio sono riportati qui sotto.","reading":[{"label":"Alles, um die Umwelt zu schützen","text":"1 Ich fahre langsam, um Benzin zu sparen.\n2 Um Energie zu sparen, schalten wir die Heizung nachts aus."},{"label":"B  Lesen Sie.","text":"Infinitiv mit um zu: Ich fahre langsam, | um Benzin zu sparen.\nNebensatz mit damit: Ich fahre langsam, | damit ich Benzin spare.\nDie Subjekte in Haupt- und Nebensatz sind gleich: um zu oder damit\nIch fahre langsam, | um Benzin zu sparen. / damit ich Benzin spare.\nDie Subjekte in Haupt- und Nebensatz sind nicht gleich: immer damit\nMeine Eltern sparen, | damit ich studieren kann."},{"label":"C  Lesen Sie.","text":"• *um … zu* und *damit* drücken einen Zweck oder eine Absicht aus.\n• Der Satz mit *um … zu* ist ein Infinitivsatz. Am Ende steht der Infinitiv."}],"items":[{"label":"1","text":"Foto ___: Ich fahre langsam, um Benzin zu sparen.","gaps":[["B"]],"solution":"Foto **B**: Ich fahre langsam, um Benzin zu sparen.","en":"Foto B: Guido piano per risparmiare benzina.","why":"Guidare → il volante.","source":"adverbial"},{"label":"2","text":"Foto ___: Um Energie zu sparen, schalten wir die Heizung nachts aus.","gaps":[["A"]],"solution":"Foto **A**: Um Energie zu sparen, schalten wir die Heizung nachts aus.","en":"Foto A: Per risparmiare energia, di notte spegniamo il riscaldamento.","why":"Riscaldamento → il termosifone. Quando *um … zu* viene prima, la frase principale comincia con il verbo: *schalten wir*.","source":"g6865"}]},{"no":"1","instruction":"Wozu das? Verbinden Sie die Sätze mit *um … zu* und schreiben Sie in Ihr Heft.","instruction_en":"A che scopo? Unisci ogni frase allo scopo tra parentesi, usando *um … zu*: *um* dopo la virgola, *zu* + infinito alla fine.","example":[{"label":"1","lead":"Wir fahren in die Berge. (→ wandern und ein Picknick machen)","text":"Wir fahren in die Berge, **um zu wandern und ein Picknick zu machen**."}],"items":[{"label":"2","lead":"Wir fahren an den See. (→ dort spazieren gehen)","text":"","accept":["Wir fahren an den See, um dort spazieren zu gehen."],"solution":"**Wir fahren an den See, um dort spazieren zu gehen.**","en":"Andiamo al lago per fare una passeggiata.","why":"Due verbi: *zu* va prima dell'ultimo: *spazieren zu gehen*.","source":"g6865"},{"label":"3","lead":"Wir haben lange gespart. (→ die Wohnung kaufen)","text":"","accept":["Wir haben lange gespart, um die Wohnung zu kaufen."],"solution":"**Wir haben lange gespart, um die Wohnung zu kaufen.**","en":"Abbiamo risparmiato a lungo per comprare l'appartamento.","why":"*um die Wohnung zu kaufen*: il complemento oggetto va tra *um* e *zu*.","source":"g6865"},{"label":"4","lead":"Ich muss in die Klinik. (→ meinen kranken Onkel besuchen)","text":"","accept":["Ich muss in die Klinik, um meinen kranken Onkel zu besuchen."],"solution":"**Ich muss in die Klinik, um meinen kranken Onkel zu besuchen.**","en":"Devo andare in clinica per trovare mio zio malato.","why":"*um … zu besuchen*.","source":"g6865"},{"label":"5","lead":"Ihr müsst mehr trainieren. (→ am Marathon teilnehmen können)","text":"","accept":["Ihr müsst mehr trainieren, um am Marathon teilnehmen zu können."],"solution":"**Ihr müsst mehr trainieren, um am Marathon teilnehmen zu können.**","en":"Dovete allenarvi di più per poter partecipare alla maratona.","why":"Con un verbo modale, *zu* va prima del modale: *teilnehmen zu können*.","source":"g6865"},{"label":"6","lead":"Du musst Sport machen. (→ gesund bleiben)","text":"","accept":["Du musst Sport machen, um gesund zu bleiben."],"solution":"**Du musst Sport machen, um gesund zu bleiben.**","en":"Devi fare sport per restare in salute.","why":"*um gesund zu bleiben*.","source":"g6865"}]}]},{"page":"Blatt 52 · S. 109","heading":"52  Ich fahre langsam, um Benzin zu sparen.","heading_en":"Guido piano per risparmiare benzina.","exercises":[{"no":"2","instruction":"Ordnen Sie zu und verbinden Sie Sätze mit *damit*. Beginnen Sie die Sätze auch mit *damit*. Schreiben Sie in Ihr Heft.","instruction_en":"Abbina ogni domanda a uno scopo (a–c), poi rispondi due volte: una volta con *damit* dopo la frase principale, una volta cominciando con *Damit*. Nella frase con *damit* il verbo va alla fine; dopo una frase con *Damit* messa all'inizio, la frase principale comincia con il suo verbo.","phrases":["a  Wir prüfen endlich die Rechnung.","b  Meine Frau wartet nicht so lange.","c  Ich repariere ihr Fahrrad.","d  Du verstehst mich gut. (Beispiel)"],"example":[{"label":"1","lead":"Wozu übst du die Aussprache? → d","text":"Ich übe die Aussprache, **damit du mich gut verstehst**.\n**Damit du mich gut verstehst**, übe ich die Aussprache."}],"items":[{"label":"2","text":"Wozu holt Paul den Taschenrechner? → ___","gaps":[["a"]],"solution":"Wozu holt Paul den Taschenrechner? → **a**","en":"Paul va a prendere la calcolatrice affinché possiamo finalmente controllare il conto.","why":"Trova lo scopo adatto alla domanda.","source":"damit"},{"label":"2 · damit am Ende","lead":"Wozu holt Paul den Taschenrechner? → a","text":"","accept":["Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen.","Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen können."],"solution":"**Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen.**","en":"Paul va a prendere la calcolatrice affinché possiamo finalmente controllare il conto.","why":"Nuovo soggetto *wir* → *damit*; *prüfen* alla fine.","source":"damit"},{"label":"2 · Damit am Anfang","lead":"Wozu holt Paul den Taschenrechner? → a","text":"","accept":["Damit wir endlich die Rechnung prüfen, holt Paul den Taschenrechner.","Damit wir endlich die Rechnung prüfen können, holt Paul den Taschenrechner."],"solution":"**Damit wir endlich die Rechnung prüfen, holt Paul den Taschenrechner.**","en":"Paul va a prendere la calcolatrice affinché possiamo finalmente controllare il conto.","why":"Frase con *Damit* all'inizio, poi il verbo: *holt Paul*.","source":"damit"},{"label":"3","text":"Wozu fahren Sie so schnell? → ___","gaps":[["b"]],"solution":"Wozu fahren Sie so schnell? → **b**","en":"Vado così veloce affinché mia moglie non debba aspettare così a lungo.","why":"Trova lo scopo adatto alla domanda.","source":"damit"},{"label":"3 · damit am Ende","lead":"Wozu fahren Sie so schnell? → b","text":"","accept":["Ich fahre so schnell, damit meine Frau nicht so lange wartet.","Ich fahre so schnell, damit meine Frau nicht so lange warten muss."],"solution":"**Ich fahre so schnell, damit meine Frau nicht so lange wartet.**","en":"Vado così veloce affinché mia moglie non debba aspettare così a lungo.","why":"La domanda usa *Sie*, la risposta *ich*. Qui *nicht* resta: *damit* non nega.","source":"damit"},{"label":"3 · Damit am Anfang","lead":"Wozu fahren Sie so schnell? → b","text":"","accept":["Damit meine Frau nicht so lange wartet, fahre ich so schnell.","Damit meine Frau nicht so lange warten muss, fahre ich so schnell."],"solution":"**Damit meine Frau nicht so lange wartet, fahre ich so schnell.**","en":"Vado così veloce affinché mia moglie non debba aspettare così a lungo.","why":"Frase con *Damit* all'inizio, poi *fahre ich*.","source":"damit"},{"label":"4","text":"Wozu hat Emilia eine Zange mitgenommen? → ___","gaps":[["c"]],"solution":"Wozu hat Emilia eine Zange mitgenommen? → **c**","en":"Emilia ha portato una pinza affinché io possa riparare la sua bici.","why":"Trova lo scopo adatto alla domanda.","source":"damit"},{"label":"4 · damit am Ende","lead":"Wozu hat Emilia eine Zange mitgenommen? → c","text":"","accept":["Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad repariere.","Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad reparieren kann."],"solution":"**Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad repariere.**","en":"Emilia ha portato una pinza affinché io possa riparare la sua bici.","why":"*ihr Fahrrad* = la bici di Emilia; nuovo soggetto *ich* → *damit*.","source":"damit"},{"label":"4 · Damit am Anfang","lead":"Wozu hat Emilia eine Zange mitgenommen? → c","text":"","accept":["Damit ich ihr Fahrrad repariere, hat Emilia eine Zange mitgenommen.","Damit ich ihr Fahrrad reparieren kann, hat Emilia eine Zange mitgenommen."],"solution":"**Damit ich ihr Fahrrad repariere, hat Emilia eine Zange mitgenommen.**","en":"Emilia ha portato una pinza affinché io possa riparare la sua bici.","why":"Frase con *Damit* all'inizio, poi *hat Emilia … mitgenommen*.","source":"damit"}]},{"no":"3","instruction":"Welche Sätze kann man mit *um … zu* verbinden? Kreuzen Sie an.","instruction_en":"Quali coppie si possono unire con *um … zu*? Solo quando le due frasi hanno lo stesso soggetto. Scrivi *ja* o *nein*.","example":[{"label":"1","text":"Ich mache eine Zusatzqualifikation. Ich möchte die Teamleitung bekommen. → **ja**"}],"items":[{"label":"2","text":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser. → ___","gaps":[["nein"]],"solution":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser. → **nein**","en":"Betty fa un corso estivo a Parigi. I suoi voti di francese migliorano. → no","why":"I soggetti *Betty* e *ihre Noten* sono diversi.","source":"g6865"},{"label":"3","text":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken. → ___","gaps":[["ja"]],"solution":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken. → **ja**","en":"Abbiamo bisogno del Suo consenso. Vorremmo inviarLe pubblicità. → sì","why":"In entrambe: *wir*.","source":"g6865"},{"label":"4","text":"David hat auch abends noch genügend Energie. Er möchte Sport machen. → ___","gaps":[["ja"]],"solution":"David hat auch abends noch genügend Energie. Er möchte Sport machen. → **ja**","en":"David ha ancora abbastanza energia anche la sera. Vuole fare sport. → sì","why":"*Er* = David.","source":"g6865"},{"label":"5","text":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren. → ___","gaps":[["nein"]],"solution":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren. → **nein**","en":"Stasera preparo già tutto. Domani potete partire molto presto. → no","why":"I soggetti *ich* e *ihr* sono diversi.","source":"g6865"},{"label":"6","text":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen. → ___","gaps":[["nein"]],"solution":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen. → **nein**","en":"Compriamo sempre più spesso prodotti bio. I nostri figli possono mangiare sano. → no","why":"I soggetti *wir* e *unsere Kinder* sono diversi.","source":"g6865"},{"label":"7","text":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen. → ___","gaps":[["ja"]],"solution":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen. → **ja**","en":"Emma e Pia si incontrano in città. Vogliono fare acquisti insieme. → sì","why":"*Sie* = Emma e Pia.","source":"g6865"},{"label":"8","text":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen. → ___","gaps":[["ja"]],"solution":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen. → **ja**","en":"Ti serve un buon metodo di lavoro. Vuoi risolvere i compiti velocemente. → sì","why":"In entrambe: *du*.","source":"g6865"}]},{"no":"4","instruction":"Verbinden Sie die Sätze in 3 mit *damit* und, wo möglich, mit *um … zu*. Schreiben Sie in Ihr Heft.","instruction_en":"Unisci le coppie dell'esercizio 3 con *damit*, e anche con *um … zu* dove il soggetto è lo stesso. *möchte(n)* si toglie: la parola di scopo dice già \"volere\".","example":[{"label":"1","text":"Ich mache eine Zusatzqualifikation, **um die Teamleitung zu bekommen**.\nIch mache eine Zusatzqualifikation, **damit ich die Teamleitung bekomme**."}],"items":[{"label":"2 · damit","lead":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser.","text":"","accept":["Betty macht einen Sommerkurs in Paris, damit ihre Noten in Französisch besser werden.","Betty macht einen Sommerkurs in Paris, damit ihre Französischnoten besser werden."],"solution":"**Betty macht einen Sommerkurs in Paris, damit ihre Noten in Französisch besser werden.**","en":"Betty fa un corso estivo a Parigi affinché i suoi voti di francese migliorino.","why":"Soggetti diversi → solo *damit*; *werden* alla fine.","source":"damit"},{"label":"3 · um … zu","lead":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken.","text":"","accept":["Wir brauchen Ihre Zustimmung, um Ihnen Werbung zuzuschicken."],"solution":"**Wir brauchen Ihre Zustimmung, um Ihnen Werbung zuzuschicken.**","en":"Abbiamo bisogno del Suo consenso per inviarLe pubblicità.","why":"Verbo separabile: *zuzuschicken* (zu + zu + schicken); *möchten* si toglie.","source":"g6865"},{"label":"3 · damit","lead":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken.","text":"","accept":["Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken dürfen.","Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken können.","Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken."],"solution":"**Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken dürfen.**","en":"Abbiamo bisogno del Suo consenso affinché ci sia permesso inviarLe pubblicità.","why":"*damit wir … zuschicken dürfen*: il consenso dà il permesso, quindi *dürfen* è il più adatto.","source":"damit","check":"Il foglio non ha soluzioni: qui vanno bene *dürfen*, *können* o nessun modale; chiedi al tuo insegnante quale vuole."},{"label":"4 · um … zu","lead":"David hat auch abends noch genügend Energie. Er möchte Sport machen.","text":"","accept":["David hat auch abends noch genügend Energie, um Sport zu machen."],"solution":"**David hat auch abends noch genügend Energie, um Sport zu machen.**","en":"David ha ancora abbastanza energia anche la sera per fare sport.","why":"Stesso soggetto: *um Sport zu machen*.","source":"g6865"},{"label":"4 · damit","lead":"David hat auch abends noch genügend Energie. Er möchte Sport machen.","text":"","accept":["David hat auch abends noch genügend Energie, damit er Sport machen kann.","David hat auch abends noch genügend Energie, damit er Sport macht."],"solution":"**David hat auch abends noch genügend Energie, damit er Sport machen kann.**","en":"David ha ancora abbastanza energia anche la sera, così da poter fare sport.","why":"Soggetto *er* ripetuto, verbo alla fine.","source":"damit"},{"label":"5 · damit","lead":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren.","text":"","accept":["Ich bereite heute Abend schon alles vor, damit ihr morgen ganz früh losfahren könnt."],"solution":"**Ich bereite heute Abend schon alles vor, damit ihr morgen ganz früh losfahren könnt.**","en":"Stasera preparo già tutto affinché domani possiate partire molto presto.","why":"Soggetti diversi → solo *damit*; *könnt* proprio alla fine.","source":"damit"},{"label":"6 · damit","lead":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen.","text":"","accept":["Wir kaufen immer öfter Bio-Qualität, damit unsere Kinder gesund essen können."],"solution":"**Wir kaufen immer öfter Bio-Qualität, damit unsere Kinder gesund essen können.**","en":"Compriamo sempre più spesso prodotti bio affinché i nostri figli possano mangiare sano.","why":"Soggetti diversi → solo *damit*.","source":"damit"},{"label":"7 · um … zu","lead":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen.","text":"","accept":["Emma und Pia treffen sich in der Stadt, um zusammen einzukaufen."],"solution":"**Emma und Pia treffen sich in der Stadt, um zusammen einzukaufen.**","en":"Emma e Pia si incontrano in città per fare acquisti insieme.","why":"Verbo separabile: *einzukaufen* (ein + zu + kaufen).","source":"g6865"},{"label":"7 · damit","lead":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen.","text":"","accept":["Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen können.","Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen."],"solution":"**Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen können.**","en":"Emma e Pia si incontrano in città, così da poter fare acquisti insieme.","why":"Soggetto *sie* ripetuto, verbo alla fine.","source":"damit"},{"label":"8 · um … zu","lead":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen.","text":"","accept":["Du brauchst eine gute Arbeitstechnik, um die Aufgaben schnell zu lösen."],"solution":"**Du brauchst eine gute Arbeitstechnik, um die Aufgaben schnell zu lösen.**","en":"Ti serve un buon metodo di lavoro per risolvere i compiti velocemente.","why":"Stesso soggetto: *um … zu lösen*.","source":"g6865"},{"label":"8 · damit","lead":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen.","text":"","accept":["Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell lösen kannst.","Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell löst."],"solution":"**Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell lösen kannst.**","en":"Ti serve un buon metodo di lavoro, così da poter risolvere i compiti velocemente.","why":"Soggetto *du* ripetuto, verbo alla fine.","source":"damit"}]},{"no":"5","instruction":"Lesen Sie Frau Deckers Blog und verbinden Sie die Sätze mit *um … zu* oder *damit*.","instruction_en":"Leggi il blog della signora Decker e unisci ogni coppia: stesso soggetto → *um … zu* (meglio); soggetto diverso → *damit*. Togli *möchte*.","reading":[{"label":"www.mein-tag.de","text":"1 Ich stehe morgens früh auf. Ich möchte noch vor dem Frühstück joggen.\n2 Ich fahre oft mit dem Auto ins Büro. Ich möchte pünktlich sein.\n3 Am Vormittag arbeite ich schnell und konzentriert. Meine Kunden sind zufrieden.\n4 Ich fahre in der Mittagspause in den Supermarkt. Ich kaufe schnell etwas fürs Abendessen ein.\n5 Ich verlasse die Firma um drei. Meine Kinder sind nicht zu lange allein."}],"example":[{"label":"1","text":"Ich stehe morgens früh auf, **um noch vor dem Frühstück zu joggen**."}],"items":[{"label":"2","lead":"Ich fahre oft mit dem Auto ins Büro. Ich möchte pünktlich sein.","text":"","accept":["Ich fahre oft mit dem Auto ins Büro, um pünktlich zu sein.","Ich fahre oft mit dem Auto ins Büro, damit ich pünktlich bin."],"solution":"**Ich fahre oft mit dem Auto ins Büro, um pünktlich zu sein.**","en":"Vado spesso in ufficio in macchina per essere puntuale.","why":"Stesso soggetto *ich* → *um pünktlich zu sein*.","source":"g6865"},{"label":"3","lead":"Am Vormittag arbeite ich schnell und konzentriert. Meine Kunden sind zufrieden.","text":"","accept":["Am Vormittag arbeite ich schnell und konzentriert, damit meine Kunden zufrieden sind."],"solution":"**Am Vormittag arbeite ich schnell und konzentriert, damit meine Kunden zufrieden sind.**","en":"In mattinata lavoro in modo rapido e concentrato affinché i miei clienti siano soddisfatti.","why":"Nuovo soggetto *meine Kunden* → *damit*; *sind* alla fine.","source":"damit"},{"label":"4","lead":"Ich fahre in der Mittagspause in den Supermarkt. Ich kaufe schnell etwas fürs Abendessen ein.","text":"","accept":["Ich fahre in der Mittagspause in den Supermarkt, um schnell etwas fürs Abendessen einzukaufen.","Ich fahre in der Mittagspause in den Supermarkt, damit ich schnell etwas fürs Abendessen einkaufe."],"solution":"**Ich fahre in der Mittagspause in den Supermarkt, um schnell etwas fürs Abendessen einzukaufen.**","en":"Nella pausa pranzo vado al supermercato per comprare velocemente qualcosa per cena.","why":"Stesso soggetto; verbo separabile: *einzukaufen* (ein + zu + kaufen).","source":"g6865"},{"label":"5","lead":"Ich verlasse die Firma um drei. Meine Kinder sind nicht zu lange allein.","text":"","accept":["Ich verlasse die Firma um drei, damit meine Kinder nicht zu lange allein sind."],"solution":"**Ich verlasse die Firma um drei, damit meine Kinder nicht zu lange allein sind.**","en":"Esco dal lavoro alle tre affinché i miei figli non restino soli troppo a lungo.","why":"Nuovo soggetto *meine Kinder* → *damit*; *nicht* resta (solo *ohne* e *anstatt* lo assorbono).","source":"damit"}]},{"no":"6","instruction":"Wozu machen Sie was? Schreiben Sie 3 Sätze über Ihren Tag in Ihr Heft und nennen Sie den Zweck.","instruction_en":"Che cosa fai, e a che scopo? Scrivi 3 frasi sulla tua giornata e indica lo scopo con *um … zu* o *damit*. La risposta modello è una delle possibilità.","example":[{"label":"Beispiel","text":"Ich gehe schon um drei aus dem Büro, **um früh bei den Kindern zu sein**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich stehe um halb sieben auf, um den Zug nach Zürich zu erreichen. Ich nehme mein Mittagessen von zu Hause mit, um Geld zu sparen. Am Abend lerne ich eine halbe Stunde Deutsch, damit meine Chancen im Job besser werden.","en":"Mi alzo alle sei e mezza per prendere il treno per Zurigo. Porto il pranzo da casa per risparmiare soldi. La sera studio tedesco per mezz'ora affinché le mie possibilità sul lavoro migliorino.","why":"Stesso soggetto → *um … zu*; un nuovo soggetto (*meine Chancen*) → *damit*.","source":"adverbial"}]}]}],"sources":[{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (um / ohne / anstatt … zu non hanno un soggetto proprio; lo prendono dalla frase principale)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"damit","title":"dizionario dei connettivi di grammis: damit (subordinante con il verbo alla fine)","url":"https://grammis.ids-mannheim.de/konnektoren/407001"},{"id":"adverbial","title":"grammis: Adverbial (le frasi con um … zu e damit sono complementi avverbiali di scopo)","url":"https://grammis.ids-mannheim.de/vggf/2280"},{"id":"ohnedass","title":"dizionario dei connettivi di grammis: ohne dass (subordinante, verbo alla fine; induce negazione: la frase dice che cosa non succede)","url":"https://grammis.ids-mannheim.de/konnektoren/406910"},{"id":"anstattdass","title":"dizionario dei connettivi di grammis: anstatt dass (subordinante, verbo alla fine; sostitutivo e induce negazione; anche statt dass)","url":"https://grammis.ids-mannheim.de/konnektoren/406953"}]}];
